                      );
                    }}
                    title={`Discovered Route: ${ep.method} ${ep.path}`}
                  >
                    <span className="chip-env-tag">CODE</span>
                    <span className={`chip-method method-${(ep.method || "GET").toLowerCase()}`}>
                      {ep.method}
                    </span>
                    {ep.path}
                  </button>
                ))}
