                    {copiedResponse ? <FaCheck style={{ color: "#22c55e" }} /> : <FaCopy />} Copy
                  </button>
                  <button
                    className="api-btn-xs"
                    onClick={handleDownloadResponse}
                    title="Download response file"
                  >
                    <FaDownload /> Download
                  </button>
                  <button
                    className="api-btn-xs api-btn-ai"
                    onClick={handleAiAnalyzeResponse}
                    disabled={aiLoading}
