                      </div>
                    ) : aiError ? (
                      <div className="api-ai-error">{aiError}</div>
                    ) : aiAnalysis ? (
                      <div className="api-ai-markdown-rendered">
                        <ReactMarkdown
                          remarkPlugins={[remarkGfm]}
                          components={{
                            h1: ({ children }) => <h1 className="ai-md-h1">{children}</h1>,
                            h2: ({ children }) => <h2 className="ai-md-h2">{children}</h2>,
                            h3: ({ children }) => <h3 className="ai-md-h3">{children}</h3>,
                            h4: ({ children }) => <h4 className="ai-md-h4">{children}</h4>,
                            p: ({ children }) => <p className="ai-md-p">{children}</p>,
                            ul: ({ children }) => <ul className="ai-md-ul">{children}</ul>,
                            ol: ({ children }) => <ol className="ai-md-ol">{children}</ol>,
                            li: ({ children }) => <li className="ai-md-li">{children}</li>,
                            hr: () => <hr className="ai-md-hr" />,
                            blockquote: ({ children }) => <blockquote className="ai-md-quote">{children}</blockquote>,
                            strong: ({ children }) => <strong className="ai-md-strong">{children}</strong>,
                            code: ({ inline, className, children, ...props }) => {
                              if (inline) {
                                return (
                                  <code className="ai-md-inline-code" {...props}>
                                    {children}
                                  </code>
                                );
                              }
                              return (
                                <div className="ai-md-code-card">
                                  <pre className="ai-md-pre">
                                    <code className="ai-md-code-block" {...props}>
                                      {children}
                                    </code>
                                  </pre>
                                </div>
                              );
                            }
                          }}
                        >
                          {aiAnalysis}
                        </ReactMarkdown>
                      </div>
                    ) : (
                      <div className="api-empty-state">
                        Click "AI Analyze" or "Security Audit" above to inspect this production or local API response.
                      </div>
                    )}
                  </div>
                )}
              </div>
            </>
          ) : (
            <div className="api-response-placeholder">
              <GiCurledTentacle className="api-placeholder-icon" />
              <h3>Production & Localhost API Tester</h3>
              <p>
                Test production HTTPS backend endpoints or local microservices with CORS-bypassing proxy, cURL generation, and AI diagnostics.
              </p>
              <div className="api-hint-box">
                <strong>🚀 Production Testing:</strong> Switch Environment to <code>Production</code> or paste any remote HTTPS endpoint (e.g. <code>https://api.domain.com</code>). The proxy will execute the cURL request without CORS blocks!
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Environment & Variables Configuration Modal */}
      {isEnvModalOpen && (
        <div className="api-modal-backdrop" onClick={() => setIsEnvModalOpen(false)}>
          <div className="api-modal-card env-modal" onClick={(e) => e.stopPropagation()}>
            <div className="api-modal-header">
              <h3>
                <FaCog /> Environment & Variables Manager
              </h3>
              <button className="api-btn-icon" onClick={() => setIsEnvModalOpen(false)}>
                <FaTimes />
              </button>
            </div>

            <div className="api-modal-body">
              <p>Configure production base URLs and auth tokens for seamless environment switching:</p>

              <div className="api-env-form-group">
                <label>Production Base URL (<code>&#123;&#123;baseUrl&#125;&#125;</code> in Prod):</label>
                <input
                  type="text"
                  className="api-input"
                  placeholder="https://api.yourproject.com"
                  value={envConfig.productionBase}
                  onChange={(e) => setEnvConfig({ ...envConfig, productionBase: e.target.value })}
                />
              </div>

              <div className="api-env-form-group">
                <label>Production Bearer Token (<code>&#123;&#123;token&#125;&#125;</code> in Prod):</label>
                <input
                  type="text"
                  className="api-input"
                  placeholder="prod_secret_token_xyz"
                  value={envConfig.prodToken}
                  onChange={(e) => setEnvConfig({ ...envConfig, prodToken: e.target.value })}
                />
              </div>

              <div className="api-env-form-group">
                <label>Production API Key (<code>&#123;&#123;apiKey&#125;&#125;</code> in Prod):</label>
                <input
                  type="text"
                  className="api-input"
                  placeholder="live_api_key_12345"
                  value={envConfig.prodApiKey}
                  onChange={(e) => setEnvConfig({ ...envConfig, prodApiKey: e.target.value })}
                />
              </div>

              <div className="api-env-form-group">
                <label>Staging Base URL:</label>
                <input
                  type="text"
                  className="api-input"
                  placeholder="https://staging-api.yourproject.com"
                  value={envConfig.stagingBase}
                  onChange={(e) => setEnvConfig({ ...envConfig, stagingBase: e.target.value })}
                />
              </div>

              <div className="api-env-form-row">
                <div className="api-env-form-group half">
                  <label>Request Timeout (Seconds):</label>
                  <input
                    type="number"
                    min="5"
                    max="120"
                    className="api-input"
                    value={envConfig.timeoutSec}
                    onChange={(e) => setEnvConfig({ ...envConfig, timeoutSec: Number(e.target.value) || 30 })}
                  />
                </div>
                <div className="api-env-form-group half checkbox-group">
                  <label className="api-checkbox-label">
                    <input
                      type="checkbox"
                      checked={envConfig.insecureSsl}
                      onChange={(e) => setEnvConfig({ ...envConfig, insecureSsl: e.target.checked })}
                    />
                    Allow Insecure SSL (<code>-k</code> / self-signed certs)
                  </label>
                </div>
              </div>
            </div>

            <div className="api-modal-footer">
              <button className="api-btn-primary" onClick={() => setIsEnvModalOpen(false)}>
                Save & Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Import cURL Modal */}
      {isImportOpen && (
        <div className="api-modal-backdrop" onClick={() => setIsImportOpen(false)}>
          <div className="api-modal-card" onClick={(e) => e.stopPropagation()}>
            <div className="api-modal-header">
              <h3>
                <FaTerminal /> Import cURL Command
              </h3>
              <button className="api-btn-icon" onClick={() => setIsImportOpen(false)}>
                <FaTimes />
              </button>
            </div>

            <div className="api-modal-body">
              <p>Paste any production or localhost <code>curl</code> command below from Chrome DevTools or docs:</p>
              <textarea
                className="api-modal-textarea"
                rows={6}
                value={importCurlText}
                onChange={(e) => setImportCurlText(e.target.value)}
                placeholder='curl -X POST "https://api.github.com/user/repos" -H "Authorization: Bearer ghp_xxx" -d "{\"name\":\"new-repo\"}"'
              />
              {importError && <div className="api-modal-error">{importError}</div>}
            </div>

            <div className="api-modal-footer">
              <button className="api-btn-secondary" onClick={() => setIsImportOpen(false)}>
                Cancel
              </button>
              <button className="api-btn-primary" onClick={handleImportCurl}>
                Parse & Load
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// src/components/Architecture/ArchitectureCanvas.jsx
import { useState, useMemo, useEffect, useRef } from "react";
import "./ArchitectureCanvas.css";
import {
  FaProjectDiagram,
  FaBolt,
  FaBook,
  FaSearch,
  FaSearchPlus,
  FaSearchMinus,
  FaExpandArrowsAlt,
  FaDownload,
  FaDatabase,
  FaServer,
  FaSyncAlt,
  FaLayerGroup,
  FaCube,
  FaCode,
  FaFileCode,
  FaShieldAlt,
  FaNetworkWired,
  FaFolderOpen
} from "react-icons/fa";
import useEditor from "../../hooks/useEditor";
import { scanCodebaseArchitecture, isIgnoredPath } from "../../services/architectureScanner";
import { traceExecutionSequences } from "../../services/lifecycleTracer";
import {
  generateArchitectureFlowchart,
  generateSequenceMermaid,
  generateEntityRelationshipDiagram
} from "../../services/mermaidGenerator";
import SequenceVisualizer from "./SequenceVisualizer";
import MermaidRenderer from "./MermaidRenderer";
import MongoSchemaERD from "./MongoSchemaERD";
import BackendApiRoutes from "./BackendApiRoutes";
import ProjectFileTree from "./ProjectFileTree";
import ThreeArchitectureDiagram from "./ThreeArchitectureDiagram";

export default function ArchitectureCanvas() {
  const { files = [], openFile, scanWorkspaceFiles, isScanningWorkspace, scanProgress, openBackendRoutesTab } = useEditor();
  const [activeTab, setActiveTab] = useState("graph"); // "graph" | "filetree" | "mongoschema" | "routes" | "mermaid" | "sequence" | "dictionary"
  const [mermaidDiagramType, setMermaidDiagramType] = useState("flowchart"); // "flowchart" | "sequence" | "erd"
  const [catalogFilter, setCatalogFilter] = useState("ALL");
  const [zoom, setZoom] = useState(100);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef({ x: 0, y: 0 });
  const viewportRef = useRef(null);

  const handleCanvasMouseDown = (e) => {
    if (e.button !== 0) return;
    if (
      e.target.closest("button") ||
      e.target.closest("input") ||
      e.target.closest("a") ||
      e.target.closest(".arch-card-btn")
    ) {
      return;
    }
    setIsDragging(true);
    dragStartRef.current = {
      x: e.clientX - pan.x,
      y: e.clientY - pan.y
    };
  };

  const handleCanvasMouseMove = (e) => {
    if (!isDragging) return;
    setPan({
      x: e.clientX - dragStartRef.current.x,
      y: e.clientY - dragStartRef.current.y
    });
  };

  const handleCanvasMouseUp = () => {
    setIsDragging(false);
  };

  const handleCanvasWheel = (e) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -10 : 10;
      setZoom(z => Math.max(30, Math.min(z + delta, 300)));
    }
  };

  const handleResetZoomPan = () => {
    setZoom(100);
    setPan({ x: 0, y: 0 });
  };
  const [search, setSearch] = useState("");
  const [activeLayers, setActiveLayers] = useState({
    model: true,
    backend: true,
    service: true,
    context: true,
    hook: true,
    page: true,
    component: true,
    util: true,
    config: true
  });

  // Automatically scan workspace files on mount if any code files have null/empty content
  useEffect(() => {
    if (!scanWorkspaceFiles || isScanningWorkspace) return;
    const hasUnscannedFiles = files.some(f =>
      !isIgnoredPath(f.path, f.name) &&
      (f.content == null || f.content === "") &&
      ["js", "jsx", "ts", "tsx", "json"].some(ext => (f.name || "").toLowerCase().endsWith("." + ext))
    );
    if (hasUnscannedFiles) {
      scanWorkspaceFiles(false);
    }
  }, [files.length]);

  // Scan codebase excluding node_modules, dist, and caches
  const architecture = useMemo(() => {
    return scanCodebaseArchitecture(files);
  }, [files]);

  // Trace execution flow
  const executionSteps = useMemo(() => {
    return traceExecutionSequences(architecture);
  }, [architecture]);

  // Generate Mermaid diagram codes dynamically for whatever project is active
  const mermaidFlowchart = useMemo(() => {
    return generateArchitectureFlowchart(architecture);
  }, [architecture]);

  const mermaidSequence = useMemo(() => {
    return generateSequenceMermaid(executionSteps);
  }, [executionSteps]);

  const mermaidErd = useMemo(() => {
    return generateEntityRelationshipDiagram(architecture.nodes);
  }, [architecture.nodes]);

  const toggleLayer = (layer) => {
    setActiveLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  const filteredNodes = useMemo(() => {
    const q = search.toLowerCase().trim();
    return architecture.nodes.filter(n => {
      if (!activeLayers[n.layer]) return false;
      if (!q) return true;
      const matchName = n.name.toLowerCase().includes(q);
      const matchFile = n.fileName.toLowerCase().includes(q);
      const matchVars = (n.details.stateVars || []).some(v => v.state?.toLowerCase().includes(q));
      const matchConstants = (n.details.constants || []).some(c => c.name?.toLowerCase().includes(q) || c.value?.toLowerCase().includes(q));
      const matchFuncs = (n.details.functions || []).some(f => f.toLowerCase().includes(q));
      const matchFields = (n.details.fields || []).some(f => f.name?.toLowerCase().includes(q));
      const matchEndpoints = (n.details.endpoints || []).some(e => e.path?.toLowerCase().includes(q));
      return matchName || matchFile || matchVars || matchConstants || matchFuncs || matchFields || matchEndpoints;
    });
  }, [architecture.nodes, activeLayers, search]);

  const handleOpenFile = (node) => {
    if (!openFile) return;
    // Match by exact fileId or exact filePath excluding node_modules/ignored files
    let target = files.find(f => !isIgnoredPath(f.path, f.name) && (f.id === node.fileId || f.path === node.filePath));
    if (!target) {
      target = files.find(f => !isIgnoredPath(f.path, f.name) && f.name === node.fileName);
    }
    if (target) {
      openFile(target);
    }
  };

  const handleDownloadJson = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(architecture, null, 2));
    const dlAnchor = document.createElement("a");
    dlAnchor.setAttribute("href", dataStr);
    dlAnchor.setAttribute("download", "architecture-spec.json");
    dlAnchor.click();
  };

  const layerSections = [
    { key: "model", title: "Database Models & Schemas", icon: <FaDatabase color="#3fb950" /> },
    { key: "backend", title: "Backend Server & API Routing", icon: <FaServer color="#f85149" /> },
    { key: "service", title: "Services & Network Fetchers", icon: <FaSyncAlt color="#d29922" /> },
    { key: "context", title: "Context Providers & State Stores", icon: <FaLayerGroup color="#bc8cff" /> },
    { key: "hook", title: "Custom React Hooks", icon: <FaCode color="#f0883e" /> },
    { key: "page", title: "Views & Page Hierarchies", icon: <FaCube color="#58a6ff" /> },
    { key: "component", title: "UI Components & Widgets", icon: <FaCube color="#79c0ff" /> },
    { key: "util", title: "Utilities, Helpers & Modules", icon: <FaCode color="#e5c07b" /> },
    { key: "config", title: "Configuration & Environment", icon: <FaShieldAlt color="#f472b6" /> }
