  return (
    <div className="arch-canvas-container">
      {/* Top Toolbar */}
      <div className="arch-canvas-toolbar">
        <div className="arch-toolbar-left">
          <button
            className={`arch-view-tab ${activeTab === "graph" ? "active" : ""}`}
            onClick={() => setActiveTab("graph")}
            title="Interactive multi-layer architecture cards and relations"
          >
            <FaProjectDiagram /> Visual Architecture
          </button>
          <button
            className={`arch-view-tab ${activeTab === "filetree" ? "active" : ""}`}
            onClick={() => setActiveTab("filetree")}
            style={{ color: activeTab === "filetree" ? "#00ff88" : undefined }}
            title="Windows ASCII directory tree structure (tree /F /A)"
          >
            <FaFolderOpen color="#00ff88" /> Project Tree
          </button>
          <button
            className={`arch-view-tab ${activeTab === "mongoschema" ? "active" : ""}`}
            onClick={() => setActiveTab("mongoschema")}
            style={{ color: activeTab === "mongoschema" ? "#00ff88" : undefined }}
            title="Mongoose schema cards, fields, sub-schemas & Chen ERD"
          >
            <FaDatabase color="#00ff88" /> MongoSchema ERD
          </button>
          <button
            className={`arch-view-tab ${activeTab === "routes" ? "active" : ""}`}
            onClick={() => setActiveTab("routes")}
            style={{ color: activeTab === "routes" ? "#38bdf8" : undefined }}
            title="Backend REST API routes & controller endpoints"
          >
            <FaNetworkWired color="#38bdf8" /> API Routes
          </button>
          <button
            className={`arch-view-tab ${activeTab === "mermaid" ? "active" : ""}`}
            onClick={() => setActiveTab("mermaid")}
            title="Mermaid architecture flowchart, call sequence, and ERD diagrams"
          >
            <FaCode /> Mermaid Diagrams
          </button>
          <button
            className={`arch-view-tab ${activeTab === "sequence" ? "active" : ""}`}
            onClick={() => setActiveTab("sequence")}
            title={`Traced execution sequences (${executionSteps.length} steps)`}
          >
            <FaBolt color="#e3b341" /> Execution Flow <span className="arch-tab-badge">{executionSteps.length}</span>
          </button>
          <button
            className={`arch-view-tab ${activeTab === "dictionary" ? "active" : ""}`}
            onClick={() => setActiveTab("dictionary")}
            title="Workspace symbols, state variables, and function definitions"
          >
            <FaBook /> Symbol Catalog
          </button>
        </div>

        <div className="arch-toolbar-right">
          <button
            className={`arch-tool-btn arch-scan-btn ${isScanningWorkspace ? "scanning" : ""}`}
            onClick={() => scanWorkspaceFiles && scanWorkspaceFiles(true)}
            disabled={isScanningWorkspace}
            title={isScanningWorkspace ? "Scanning files in workspace..." : "Scan workspace files to index models, routes & architecture without opening each file"}
            style={{
              background: isScanningWorkspace ? "rgba(227, 179, 65, 0.2)" : "rgba(0, 255, 136, 0.15)",
              color: isScanningWorkspace ? "#e3b341" : "#00ff88",
              borderColor: isScanningWorkspace ? "rgba(227, 179, 65, 0.4)" : "rgba(0, 255, 136, 0.4)",
              fontWeight: 600,
              display: "flex",
              alignItems: "center",
              gap: "6px"
            }}
          >
            <FaSyncAlt className={isScanningWorkspace ? "spinning" : ""} size={11} />
            {isScanningWorkspace
              ? (scanProgress ? `Scanning (${scanProgress.current}/${scanProgress.total})...` : "Scanning...")
              : "⚡ Scan Codebase"}
          </button>

          {activeTab === "graph" && (
            <>
              <button
                className="arch-tool-btn"
                onClick={() => setZoom(z => Math.max(z - 15, 30))}
                title="Zoom Out"
              >
                <FaSearchMinus />
              </button>
              <span style={{ fontSize: "11px", color: "#888", minWidth: "35px", textAlign: "center" }}>{zoom}%</span>
              <button
                className="arch-tool-btn"
                onClick={() => setZoom(z => Math.min(z + 15, 300))}
                title="Zoom In"
              >
                <FaSearchPlus />
              </button>
              <button
                className="arch-tool-btn"
                onClick={handleResetZoomPan}
                title="Reset Pan & Zoom"
              >
                <FaExpandArrowsAlt /> Reset
              </button>
            </>
          )}

          <button className="arch-tool-btn" onClick={handleDownloadJson} title="Export Architecture JSON Spec">
            <FaDownload /> Export Spec
          </button>
        </div>
      </div>

      {/* Layer Filter Bar */}
      {activeTab === "graph" && (
        <div className="arch-filter-bar">
          <span style={{ fontSize: "11px", color: "#888", marginRight: "4px" }}>Filter Layers:</span>
          {layerSections.map(s => (
            <span
              key={s.key}
              className={`arch-filter-pill ${activeLayers[s.key] ? "active" : ""}`}
              onClick={() => toggleLayer(s.key)}
            >
              {s.icon} {s.title.split(" ")[0]}
            </span>
          ))}
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: "6px" }}>
            <FaSearch color="#666" />
            <input
              type="text"
              placeholder="Search symbols or constants..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{
                background: "#222",
                border: "1px solid #333",
                color: "#ccc",
                borderRadius: "3px",
                fontSize: "11px",
                padding: "2px 6px"
              }}
            />
          </div>
        </div>
      )}

      {/* Mode 1: Interactive Node Graph */}
      {activeTab === "graph" && (
        <div
          ref={viewportRef}
          className={`arch-viewport ${isDragging ? "dragging" : ""}`}
          onMouseDown={handleCanvasMouseDown}
          onMouseMove={handleCanvasMouseMove}
          onMouseUp={handleCanvasMouseUp}
          onMouseLeave={handleCanvasMouseUp}
          onWheel={handleCanvasWheel}
          onDoubleClick={handleResetZoomPan}
        >
          <div
            className="arch-graph-grid"
            style={{
              transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom / 100})`,
              transformOrigin: "top left"
            }}
          >
            {layerSections.map(sec => {
              const nodesInLayer = filteredNodes.filter(n => n.layer === sec.key);
              if (nodesInLayer.length === 0) return null;

              return (
                <div key={sec.key} className="arch-layer-section">
                  <div className="arch-layer-title">
                    {sec.icon} {sec.title} ({nodesInLayer.length})
                  </div>

                  <div className="arch-cards-row">
                    {nodesInLayer.map(node => (
                      <div
                        key={node.id}
                        className="arch-node-card"
                        onClick={() => handleOpenFile(node)}
                        title={`Click to open ${node.fileName} in editor`}
                      >
                        <div className={`arch-card-top ${node.layer}`}>
                          <span className="arch-card-name">{node.name}</span>
                          <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                            {node.layer === "model" && (
                              <button
                                style={{
                                  background: "rgba(0, 255, 136, 0.15)",
                                  color: "#00ff88",
                                  border: "1px solid rgba(0, 255, 136, 0.4)",
                                  fontSize: "9px",
                                  padding: "1px 6px",
                                  borderRadius: "3px",
                                  cursor: "pointer",
                                  fontWeight: "600"
                                }}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setActiveTab("mongoschema");
                                }}
                                title="Open MongoSchema ERD"
                              >
                                ERD ➔
                              </button>
                            )}
                            <span className="arch-card-badge">{node.layer}</span>
                          </div>
                        </div>

                        <div className="arch-card-body">
                          {/* File path link */}
                          <div style={{ fontSize: "10px", color: "#6e7681", display: "flex", alignItems: "center", gap: "4px" }}>
                            <FaFileCode /> {node.filePath} ({node.lineCount} lines)
                          </div>

                          {/* Backend Server: Port & Middleware */}
                          {node.layer === "backend" && (
                            <div>
                              <div style={{ display: "flex", alignItems: "center", gap: "6px", fontSize: "11px", color: "#9cdcfe" }}>
                                <FaNetworkWired /> Port: {node.details.port || "5000"}
                              </div>
                              {node.details.middleware?.length > 0 && (
                                <div style={{ marginTop: "4px", display: "flex", flexWrap: "wrap", gap: "4px" }}>
                                  {node.details.middleware.map((m, i) => (
                                    <span key={i} className="arch-var-chip" style={{ color: "#fca5a5" }}>
                                      {m}
                                    </span>
                                  ))}
                                </div>
                              )}
                            </div>
                          )}

                          {/* Backend Server: HTTP Endpoints & Routes */}
                          {node.details.endpoints?.length > 0 && (
                            <div>
                              <div className="arch-section-title">
                                {node.layer === "backend" ? "Express HTTP Routes" : "API Endpoints"}
                              </div>
                              <div style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
                                {node.details.endpoints.slice(0, 8).map((ep, i) => (
                                  <div
                                    key={i}
                                    style={{
                                      fontSize: "11px",
                                      fontFamily: "monospace",
                                      background: "#141414",
                                      padding: "3px 6px",
                                      borderRadius: "3px",
                                      border: "1px solid #282828",
                                      display: "flex",
                                      alignItems: "center",
                                      justifyContent: "space-between"
                                    }}
                                  >
                                    <span style={{ color: ep.method === "GET" ? "#3fb950" : "#d29922", fontWeight: "700" }}>
                                      {ep.method} {ep.path}
                                    </span>
                                    {ep.isProtected && (
                                      <span title="Protected Route" style={{ color: "#f85149" }}>
                                        <FaShieldAlt size={10} />
                                      </span>
                                    )}
                                  </div>
                                ))}
                                {node.details.endpoints.length > 8 && (
                                  <span style={{ fontSize: "10px", color: "#888" }}>
                                    +{node.details.endpoints.length - 8} more routes...
                                  </span>
                                )}
                              </div>
                            </div>
                          )}

                          {/* Backend Server: Database Models Queried */}
                          {node.details.queriedModels?.length > 0 && (
                            <div>
                              <div className="arch-section-title">Database Models Accessed</div>
                              <div className="arch-chip-list">
                                {node.details.queriedModels.map((m, i) => (
                                  <span key={i} className="arch-field-chip">
                                    {m}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {/* 1. Arrow Functions & Handlers (Explicitly Differentiated) */}
                          {node.details.arrowFunctions?.length > 0 && (
                            <div>
                              <div className="arch-section-title" style={{ color: "#38bdf8" }}>
                                <FaBolt size={9} color="#38bdf8" /> Arrow Functions ({node.details.arrowFunctions.length})
                              </div>
                              <div className="arch-chip-list">
                                {node.details.arrowFunctions.slice(0, 8).map((fn, i) => (
                                  <span
                                    key={i}
                                    className="arch-var-chip"
                                    style={{ color: "#38bdf8", borderColor: "rgba(56, 189, 248, 0.3)" }}
                                    title={`${fn.name}() => ${fn.value}`}
                                  >
                                    <span style={{ fontSize: "8px", padding: "1px 4px", borderRadius: "2px", background: "rgba(56, 189, 248, 0.15)", marginRight: "4px", fontWeight: "700" }}>
                                      () =&gt;
                                    </span>
                                    {fn.name}
                                  </span>
                                ))}
                                {node.details.arrowFunctions.length > 8 && (
                                  <span style={{ fontSize: "10px", color: "#888" }}>
                                    +{node.details.arrowFunctions.length - 8} more...
                                  </span>
                                )}
                              </div>
                            </div>
                          )}

                          {/* 2. Constants & Configuration Values */}
                          {node.details.constants?.length > 0 && (
                            <div>
                              <div className="arch-section-title" style={{ color: "#e3b341" }}>
                                <FaShieldAlt size={9} color="#e3b341" /> Constants &amp; Values ({node.details.constants.length})
                              </div>
                              <div className="arch-chip-list">
                                {node.details.constants.slice(0, 8).map((c, i) => (
                                  <span
                                    key={i}
                                    className="arch-var-chip"
                                    style={{ color: "#e3b341", borderColor: "rgba(227, 179, 65, 0.3)" }}
                                    title={`${c.name} (${c.type}): ${c.value}`}
                                  >
                                    <span style={{ fontSize: "8px", padding: "1px 4px", borderRadius: "2px", background: "rgba(227, 179, 65, 0.15)", marginRight: "4px", fontWeight: "700" }}>
                                      CONST
                                    </span>
                                    {c.name}: {c.value}
                                  </span>
                                ))}
                                {node.details.constants.length > 8 && (
                                  <span style={{ fontSize: "10px", color: "#888" }}>
                                    +{node.details.constants.length - 8} more...
                                  </span>
                                )}
                              </div>
                            </div>
                          )}

                          {/* 3. Instances, Schemas & Refs */}
                          {(node.details.instances?.length > 0 || node.details.schemas?.length > 0) && (
                            <div>
                              <div className="arch-section-title" style={{ color: "#f472b6" }}>
                                Instances &amp; Schemas
                              </div>
                              <div className="arch-chip-list">
                                {(node.details.instances || []).map((ins, i) => (
                                  <span
                                    key={`ins-${i}`}
                                    className="arch-var-chip"
                                    style={{ color: "#f472b6", borderColor: "rgba(244, 114, 182, 0.3)" }}
                                    title={`${ins.name} (${ins.type}): ${ins.value}`}
                                  >
                                    <span style={{ fontSize: "8px", padding: "1px 4px", borderRadius: "2px", background: "rgba(244, 114, 182, 0.15)", marginRight: "4px", fontWeight: "700" }}>
                                      INSTANCE
                                    </span>
                                    {ins.name}
                                  </span>
                                ))}
                                {(node.details.schemas || []).map((sc, i) => (
                                  <span
                                    key={`sc-${i}`}
                                    className="arch-var-chip"
                                    style={{ color: "#3fb950", borderColor: "rgba(63, 185, 80, 0.3)" }}
                                    title={`${sc.name} (${sc.type})`}
                                  >
                                    <span style={{ fontSize: "8px", padding: "1px 4px", borderRadius: "2px", background: "rgba(63, 185, 80, 0.15)", marginRight: "4px", fontWeight: "700" }}>
                                      SCHEMA
                                    </span>
                                    {sc.name}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {/* Schema Fields (for Models) */}
                          {node.details.fields?.length > 0 && (
                            <div>
                              <div className="arch-section-title">Schema Fields</div>
                              <div className="arch-chip-list">
                                {node.details.fields.slice(0, 6).map((f, i) => (
                                  <span key={i} className="arch-field-chip">
                                    {f.name}: {f.type}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {/* State Variables */}
                          {node.details.stateVars?.length > 0 && (
                            <div>
                              <div className="arch-section-title">State Hooks</div>
                              <div className="arch-chip-list">
                                {node.details.stateVars.map((v, i) => (
                                  <span key={i} className="arch-var-chip">
                                    {v.state}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {/* Functions & Handlers */}
                          {node.details.functions?.length > 0 && (
                            <div>
                              <div className="arch-section-title">Functions & Handlers</div>
                              <div className="arch-chip-list">
                                {node.details.functions.slice(0, 6).map((fn, i) => (
                                  <span key={i} className="arch-func-chip">
                                    {fn}()
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Mode 0: Project File Tree (tree /F) */}
      {activeTab === "filetree" && (
        <ProjectFileTree onOpenFile={handleOpenFile} />
      )}

      {/* Mode 1: Dedicated MongoSchema ERD */}
      {activeTab === "mongoschema" && (
        <MongoSchemaERD />
      )}

      {/* Mode 2: Backend API Routes */}
      {activeTab === "routes" && (
        <BackendApiRoutes />
      )}

      {/* Mode 2: Execution Sequence Visualizer */}
      {activeTab === "sequence" && (
        <SequenceVisualizer steps={executionSteps} />
      )}

      {/* Mode 3: Visual Rendered Mermaid Diagrams */}
      {activeTab === "mermaid" && (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", width: "100%", overflow: "hidden" }}>
          {/* Sub-toolbar to pick diagram type */}
          <div style={{ display: "flex", gap: "8px", padding: "8px 16px", background: "#1c1c1c", borderBottom: "1px solid #2d2d30", alignItems: "center", flexWrap: "wrap" }}>
            <button
              className={`mermaid-btn ${mermaidDiagramType === "flowchart" ? "active" : ""}`}
              onClick={() => setMermaidDiagramType("flowchart")}
              style={{ background: mermaidDiagramType === "flowchart" ? "#0e639c" : "#2d2d30" }}
            >
              🏗️ Architecture Flowchart
            </button>
            <button
              className={`mermaid-btn ${mermaidDiagramType === "3d" ? "active" : ""}`}
              onClick={() => setMermaidDiagramType("3d")}
              style={{
                background: mermaidDiagramType === "3d" ? "#0e639c" : "#2d2d30",
                color: mermaidDiagramType === "3d" ? "#ffffff" : "#38bdf8",
                fontWeight: "600",
                display: "inline-flex",
                alignItems: "center",
                gap: "6px"
              }}
            >
              <FaCube size={11} color="#38bdf8" /> 🧊 3D Architecture View
            </button>
            <button
              className={`mermaid-btn ${mermaidDiagramType === "sequence" ? "active" : ""}`}
              onClick={() => setMermaidDiagramType("sequence")}
              style={{ background: mermaidDiagramType === "sequence" ? "#0e639c" : "#2d2d30" }}
            >
              ⚡ Call Sequence Diagram
            </button>
            <button
              className={`mermaid-btn ${mermaidDiagramType === "erd" ? "active" : ""}`}
              onClick={() => setMermaidDiagramType("erd")}
              style={{ background: mermaidDiagramType === "erd" ? "#0e639c" : "#2d2d30" }}
            >
              🗄️ Database ERD Diagram
            </button>
          </div>

          <div style={{ flex: 1, minHeight: 0 }}>
            {mermaidDiagramType === "flowchart" && (
              <MermaidRenderer
                code={mermaidFlowchart}
                title="Architecture & Component Flowchart"
                onSwitchTo3D={() => setMermaidDiagramType("3d")}
              />
            )}
            {mermaidDiagramType === "3d" && (
              <ThreeArchitectureDiagram
                architectureGraph={architecture}
                onSwitchTo2D={() => setMermaidDiagramType("flowchart")}
              />
            )}
            {mermaidDiagramType === "sequence" && (
              <MermaidRenderer code={mermaidSequence} title="Runtime Execution Call Sequence Diagram" />
            )}
            {mermaidDiagramType === "erd" && (
              <MermaidRenderer code={mermaidErd} title="Database Entity Relationship Diagram" />
            )}
          </div>
        </div>
      )}

      {/* Mode 4: Symbol Catalog */}
      {activeTab === "dictionary" && (
        <div className="arch-dict-view">
          <div style={{ display: "flex", gap: "8px", padding: "10px 16px", background: "#18181b", borderBottom: "1px solid #27272a", alignItems: "center", flexWrap: "wrap" }}>
            <span style={{ fontSize: "11px", color: "#888", marginRight: "4px" }}>Filter Concept:</span>
            {[
              { id: "ALL", label: "All Symbols" },
              { id: "ARROW_FN", label: "⚡ Arrow Functions", color: "#38bdf8" },
              { id: "CONST", label: "🔒 Constants & Config", color: "#e3b341" },
              { id: "STATE", label: "🔄 React State", color: "#79c0ff" },
              { id: "SCHEMA", label: "🗄️ Schemas & Fields", color: "#3fb950" },
              { id: "ROUTES", label: "🚀 HTTP Routes", color: "#f87171" }
            ].map(f => (
              <button
                key={f.id}
                onClick={() => setCatalogFilter(f.id)}
                style={{
                  background: catalogFilter === f.id ? (f.color || "#00ff88") : "#27272a",
                  color: catalogFilter === f.id ? "#000000" : "#d4d4d8",
                  border: "none",
                  borderRadius: "4px",
                  fontSize: "11px",
                  fontWeight: catalogFilter === f.id ? "700" : "500",
                  padding: "4px 10px",
                  cursor: "pointer",
                  transition: "all 0.15s ease"
                }}
              >
                {f.label}
              </button>
            ))}
          </div>

          <table className="arch-dict-table">
            <thead>
              <tr>
                <th>Symbol / Concept</th>
                <th>Type</th>
                <th>Defined In File</th>
                <th>Layer</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {architecture.nodes.flatMap(n => {
                const rows = [];
                // Endpoints
                (n.details.endpoints || []).forEach(ep => {
                  rows.push({
                    name: `${ep.method} ${ep.path}`,
                    type: "HTTP Route",
                    kind: "route",
                    file: n.fileName,
                    layer: n.layer,
                    details: ep.models?.length ? `Queries: ${ep.models.join(", ")}` : "Express route"
                  });
                });
                // Arrow Functions (Explicitly Differentiated)
                (n.details.arrowFunctions || []).forEach(fn => {
                  rows.push({
                    name: `${fn.name}()`,
                    type: "Arrow Function",
                    kind: "arrow-function",
                    file: n.fileName,
                    layer: n.layer,
                    details: `() => ${fn.value || 'handler'}`
                  });
                });
                // Constants & Values
                (n.details.constants || []).forEach(c => {
                  rows.push({
                    name: c.name,
                    type: c.type || "Constant Value",
                    kind: "constant",
                    file: n.fileName,
                    layer: n.layer,
                    details: `CONST: ${c.value || 'undefined'}`
                  });
                });
                // Instances
                (n.details.instances || []).forEach(ins => {
                  rows.push({
                    name: ins.name,
                    type: ins.type || "Instance",
                    kind: "instance",
                    file: n.fileName,
                    layer: n.layer,
                    details: ins.value || "class instance"
                  });
                });
                // Model fields
                (n.details.fields || []).forEach(f => {
                  rows.push({
                    name: f.name,
                    type: "Schema Field",
                    kind: "field",
                    file: n.fileName,
                    layer: n.layer,
                    details: `Type: ${f.type}${f.ref ? ` (ref: ${f.ref})` : ""}`
                  });
                });
                // State variables
                (n.details.stateVars || []).forEach(v => {
                  rows.push({
                    name: v.state,
                    type: "React useState",
                    kind: "state",
                    file: n.fileName,
                    layer: n.layer,
                    details: `Setter: ${v.setter}, Initial: ${v.initial}`
                  });
                });
                // Functions
                (n.details.functions || []).forEach(fn => {
                  rows.push({
                    name: `${fn}()`,
                    type: "Function",
                    kind: "function",
                    file: n.fileName,
                    layer: n.layer,
                    details: "Callable method"
                  });
                });
                // API functions
                (n.details.apiFunctions || []).forEach(af => {
                  rows.push({
                    name: `${af}()`,
                    type: "API Service",
                    kind: "service",
                    file: n.fileName,
                    layer: n.layer,
                    details: "Network fetcher"
                  });
                });
                return rows;
              }).filter(r => {
                if (catalogFilter === "ARROW_FN") return r.kind === "arrow-function";
                if (catalogFilter === "CONST") return r.kind === "constant";
                if (catalogFilter === "STATE") return r.kind === "state";
                if (catalogFilter === "SCHEMA") return r.kind === "field" || r.kind === "schema";
                if (catalogFilter === "ROUTES") return r.type === "HTTP Route";
                return true;
              }).map((r, i) => {
                let badgeColor = "#cccccc";
                let badgeBg = "#252528";
                if (r.kind === "arrow-function") {
                  badgeColor = "#38bdf8";
                  badgeBg = "rgba(56, 189, 248, 0.15)";
                } else if (r.kind === "constant") {
                  badgeColor = "#e3b341";
                  badgeBg = "rgba(227, 179, 65, 0.15)";
                } else if (r.kind === "instance") {
                  badgeColor = "#f472b6";
                  badgeBg = "rgba(244, 114, 182, 0.15)";
                } else if (r.kind === "schema") {
                  badgeColor = "#3fb950";
                  badgeBg = "rgba(63, 185, 80, 0.15)";
                } else if (r.kind === "ref") {
                  badgeColor = "#38bdf8";
                  badgeBg = "rgba(56, 189, 248, 0.15)";
                } else if (r.kind === "state") {
                  badgeColor = "#79c0ff";
                  badgeBg = "rgba(121, 192, 255, 0.15)";
                }

                return (
                  <tr key={i}>
                    <td style={{ fontFamily: "monospace", color: badgeColor, fontWeight: "600" }}>{r.name}</td>
                    <td>
                      <span style={{
                        fontSize: "10px",
                        padding: "2px 6px",
                        borderRadius: "3px",
                        background: badgeBg,
                        color: badgeColor,
                        fontWeight: "600"
                      }}>
                        {r.type}
                      </span>
                    </td>
                    <td style={{ color: "#e6edf3" }}>{r.file}</td>
                    <td>
                      <span className={`arch-card-badge ${r.layer}`}>{r.layer}</span>
                    </td>
                    <td style={{ color: "#8b949e" }}>{r.details}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// src/components/Architecture/ArchitecturePanel.jsx
import { useState, useMemo, useEffect } from "react";
import "./ArchitecturePanel.css";
import {
  FaProjectDiagram,
  FaDatabase,
  FaCube,
  FaServer,
  FaSyncAlt,
  FaSearch,
  FaExternalLinkAlt,
  FaChevronDown,
  FaChevronRight,
  FaCode,
  FaLayerGroup,
  FaShieldAlt
} from "react-icons/fa";
import useEditor from "../../hooks/useEditor";
import { scanCodebaseArchitecture, isIgnoredPath } from "../../services/architectureScanner";

export default function ArchitecturePanel({ onOpenFullView }) {
  const { files = [], openFile, openMongoSchemaTab, openBackendRoutesTab, scanWorkspaceFiles, isScanningWorkspace, scanProgress } = useEditor();
  const [search, setSearch] = useState("");
  const [collapsedLayers, setCollapsedLayers] = useState({});

  // Auto-scan on mount if any files lack content
  useEffect(() => {
    if (!scanWorkspaceFiles || isScanningWorkspace) return;
    const hasUnscannedFiles = files.some(f =>
      !isIgnoredPath(f.path, f.name) &&
      (f.content == null || f.content === "") &&
      ["js", "jsx", "ts", "tsx", "json"].some(ext => (f.name || "").toLowerCase().endsWith("." + ext))
    );
    if (hasUnscannedFiles) {
      scanWorkspaceFiles(false);
    }
  }, [files.length]);

  const architecture = useMemo(() => {
    return scanCodebaseArchitecture(files);
  }, [files]);

  const toggleLayer = (layerKey) => {
    setCollapsedLayers(prev => ({
      ...prev,
      [layerKey]: !prev[layerKey]
    }));
  };

  const filteredNodes = useMemo(() => {
    if (!search.trim()) return architecture.nodes;
    const q = search.toLowerCase();
    return architecture.nodes.filter(n => {
      const matchName = n.name.toLowerCase().includes(q);
      const matchFile = n.fileName.toLowerCase().includes(q);
      const matchVars = (n.details.stateVars || []).some(v => v.state?.toLowerCase().includes(q));
      const matchConstants = (n.details.constants || []).some(c => c.name?.toLowerCase().includes(q) || c.value?.toLowerCase().includes(q));
      const matchFuncs = (n.details.functions || []).some(f => f.toLowerCase().includes(q));
      const matchFields = (n.details.fields || []).some(f => f.name?.toLowerCase().includes(q));
      return matchName || matchFile || matchVars || matchConstants || matchFuncs || matchFields;
    });
  }, [architecture.nodes, search]);

  const layerDefinitions = [
    { key: "model", label: "Database Models", icon: <FaDatabase color="#3fb950" /> },
    { key: "backend", label: "Backend & Routes", icon: <FaServer color="#f85149" /> },
    { key: "service", label: "Services & APIs", icon: <FaSyncAlt color="#d29922" /> },
    { key: "context", label: "Context & State", icon: <FaLayerGroup color="#bc8cff" /> },
    { key: "hook", label: "Custom Hooks", icon: <FaCode color="#f0883e" /> },
    { key: "page", label: "Pages & Views", icon: <FaCube color="#58a6ff" /> },
    { key: "component", label: "UI Components", icon: <FaCube color="#79c0ff" /> },
    { key: "util", label: "Utilities & Modules", icon: <FaCode color="#e5c07b" /> },
    { key: "config", label: "Config & Setup", icon: <FaShieldAlt color="#f472b6" /> }
  ];

  const handleNodeClick = (node) => {
    if (!openFile) return;
    // 1. Match by fileId or exact filePath excluding node_modules/ignored files
    let targetFile = files.find(f => !isIgnoredPath(f.path, f.name) && (f.id === node.fileId || f.path === node.filePath));
    // 2. Fallback to exact filename among valid workspace files
    if (!targetFile) {
      targetFile = files.find(f => !isIgnoredPath(f.path, f.name) && f.name === node.fileName);
    }
    if (targetFile) {
      openFile(targetFile);
    }
  };

  return (
    <div className="arch-panel-container">
      {/* Panel Header */}
      <div className="arch-panel-header">
        <div className="arch-header-top">
          <span className="arch-title">
            <FaProjectDiagram /> Architecture
          </span>
          <button
            className="arch-badge-btn"
            onClick={onOpenFullView}
            title="Open Full Visual Canvas"
          >
            <FaExternalLinkAlt />
          </button>
        </div>

        <div style={{ display: "flex", gap: "6px", width: "100%" }}>
          <button className="arch-open-canvas-btn" style={{ flex: 1 }} onClick={onOpenFullView} title="Open Architecture Blueprint Canvas">
            <FaProjectDiagram /> Blueprint
          </button>
          <button
            className="arch-open-canvas-btn"
            style={{
              flex: 1,
              background: "rgba(0, 255, 136, 0.12)",
              color: "#00ff88",
              borderColor: "rgba(0, 255, 136, 0.3)"
            }}
            onClick={() => openMongoSchemaTab && openMongoSchemaTab()}
            title="Open Dedicated MongoSchema ERD"
          >
            <FaDatabase /> Mongo ERD
          </button>
        </div>

        <div style={{ display: "flex", gap: "6px", width: "100%", marginTop: "6px" }}>
          <button
            className="arch-open-canvas-btn"
            style={{
              width: "100%",
              background: isScanningWorkspace ? "rgba(227, 179, 65, 0.15)" : "rgba(56, 189, 248, 0.12)",
              color: isScanningWorkspace ? "#e3b341" : "#38bdf8",
              borderColor: isScanningWorkspace ? "rgba(227, 179, 65, 0.3)" : "rgba(56, 189, 248, 0.3)",
              justifyContent: "center"
            }}
            onClick={() => scanWorkspaceFiles && scanWorkspaceFiles(true)}
            disabled={isScanningWorkspace}
            title="Scan all workspace files across all directories without opening them"
          >
            <FaSyncAlt className={isScanningWorkspace ? "spinning" : ""} />
            {isScanningWorkspace
              ? (scanProgress ? `Scanning ${scanProgress.current}/${scanProgress.total}` : "Scanning...")
              : "⚡ Scan All Folders"}
          </button>
        </div>
      </div>

      {/* Stats Summary Chips */}
      <div className="arch-stats-row">
        <span
          className="arch-stat-chip model"
          title="Click to open MongoSchema ERD"
          style={{ cursor: "pointer" }}
          onClick={() => openMongoSchemaTab && openMongoSchemaTab()}
        >
          <FaDatabase /> {architecture.stats.models} Models
        </span>
        <span className="arch-stat-chip component" title="Components & Pages">
          <FaCube /> {architecture.stats.components + architecture.stats.pages} UI
        </span>
        <span className="arch-stat-chip context" title="Context Providers">
          <FaLayerGroup /> {architecture.stats.contexts} Contexts
        </span>
        <span
          className="arch-stat-chip service"
          title="Click to open Backend API Routes"
          style={{ cursor: "pointer" }}
          onClick={() => openBackendRoutesTab && openBackendRoutesTab()}
        >
          <FaSyncAlt /> {architecture.stats.services} Services
        </span>
        <span className="arch-stat-chip util" title="Utilities, Helpers & Modules" style={{ color: "#e5c07b" }}>
          <FaCode /> {architecture.stats.utils || 0} Utils
        </span>
        <span className="arch-stat-chip config" title="Configuration & Environment" style={{ color: "#f472b6" }}>
          <FaShieldAlt /> {architecture.stats.configs || 0} Config
        </span>
      </div>

      {/* Search Filter */}
      <div className="arch-search-box">
        <FaSearch color="#666" />
        <input
          type="text"
          className="arch-search-input"
          placeholder="Filter models, components, functions..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* Architecture Layers Tree */}
      <div className="arch-tree-container">
        {layerDefinitions.map(def => {
          const layerNodes = filteredNodes.filter(n => n.layer === def.key);
          if (layerNodes.length === 0) return null;
          const isCollapsed = collapsedLayers[def.key];

          return (
            <div key={def.key} className="arch-layer-group">
              <div className="arch-layer-header" onClick={() => toggleLayer(def.key)}>
                <span style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                  {isCollapsed ? <FaChevronRight size={10} /> : <FaChevronDown size={10} />}
                  {def.icon}
                  {def.label}
                </span>
                <span className="arch-node-symbol-count">{layerNodes.length}</span>
              </div>

              {!isCollapsed && (
                <div className="arch-layer-items">
                  {layerNodes.map(node => {
                    const symbolCount =
                      (node.details.fields?.length || 0) +
                      (node.details.stateVars?.length || 0) +
                      (node.details.constants?.length || 0) +
                      (node.details.functions?.length || 0) +
                      (node.details.endpoints?.length || 0);

                    return (
                      <div
                        key={node.id}
                        className="arch-node-item"
                        onClick={() => handleNodeClick(node)}
                        title={`Open ${node.fileName} (${node.filePath})`}
                      >
                        <span>{node.name}</span>
                        {symbolCount > 0 && (
                          <span className="arch-node-symbol-count">{symbolCount} sym</span>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// src/components/Architecture/BackendApiRoutes.jsx
import { useState, useMemo, useEffect } from "react";
import "./BackendApiRoutes.css";
import {
  FaNetworkWired,
  FaSyncAlt,
  FaDownload,
  FaProjectDiagram,
  FaDatabase,
  FaCode,
  FaSearch,
  FaShieldAlt
} from "react-icons/fa";
import useEditor from "../../hooks/useEditor";
import { extractWorkspaceRoutes } from "../../services/backendRouteParser";
import { isIgnoredPath } from "../../services/architectureScanner";

export default function BackendApiRoutes({ onOpenModel = null }) {
  const { files = [], openFile, openMongoSchemaTab, jumpToProblem, scanWorkspaceFiles, isScanningWorkspace, scanProgress } = useEditor();

  const [activeMethod, setActiveMethod] = useState("ALL");
  const [search, setSearch] = useState("");
  const [protectedOnly, setProtectedOnly] = useState(false);
  const [viewMode, setViewMode] = useState("table"); // "table" | "flow"
  const [zoom, setZoom] = useState(100);

  // Extract all routes from workspace across all folder directories
  const routesData = useMemo(() => {
    return extractWorkspaceRoutes(files);
  }, [files]);

  const { routers = [], endpoints = [], stats = { totalEndpoints: 0, routerFiles: 0, protectedCount: 0, linkedModelsCount: 0 }, methodCounts = {} } = routesData;

  // Auto-scan on mount if any files lack content or no endpoints found yet
  useEffect(() => {
    if (!scanWorkspaceFiles || isScanningWorkspace) return;
    const hasUnscannedFiles = files.some(f =>
      !isIgnoredPath(f.path, f.name) &&
      (f.content == null || f.content === "") &&
      ["js", "jsx", "ts", "tsx", "json"].some(ext => (f.name || "").toLowerCase().endsWith("." + ext))
    );
    if (hasUnscannedFiles || endpoints.length === 0) {
      scanWorkspaceFiles(false);
    }
  }, [files.length]);

  // Filtered endpoints for table
  const filteredEndpoints = useMemo(() => {
    return endpoints.filter(ep => {
      if (activeMethod !== "ALL" && ep.method !== activeMethod) return false;
      if (protectedOnly && !ep.isProtected) return false;
      if (!search.trim()) return true;
      const q = search.toLowerCase();
      return (
        ep.path?.toLowerCase().includes(q) ||
        ep.handler?.toLowerCase().includes(q) ||
        ep.middlewares?.toLowerCase().includes(q) ||
        (ep.models || []).some(m => m.toLowerCase().includes(q))
      );
    });
  }, [endpoints, activeMethod, protectedOnly, search]);

  const handleOpenSourceLine = (ep) => {
    if (!openFile) return;
    let target = files.find(f => !isIgnoredPath(f.path, f.name) && (f.id === ep.fileId || f.path === ep.filePath));
    if (!target) {
      target = files.find(f => !isIgnoredPath(f.path, f.name) && f.name === "server.js");
    }
    if (target) {
      openFile(target);
      if (jumpToProblem && ep.line) {
        jumpToProblem({
          fileId: target.id,
          filename: target.name,
          lineNumber: ep.line,
          startLineNumber: ep.line,
          column: 1
        });
      }
    }
  };

  const handleExportJson = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(routesData, null, 2));
    const dlAnchor = document.createElement("a");
    dlAnchor.setAttribute("href", dataStr);
    dlAnchor.setAttribute("download", "backend-api-routes.json");
    dlAnchor.click();
  };

  const handleModelClick = (modelName) => {
    if (openMongoSchemaTab) {
      openMongoSchemaTab(modelName);
    } else if (onOpenModel) {
      onOpenModel(modelName);
    }
  };

  // Distinct linked models for Visual Flow Graph
  const allUniqueModels = useMemo(() => {
    const set = new Set();
    endpoints.forEach(e => (e.models || []).forEach(m => set.add(m)));
    return Array.from(set);
  }, [endpoints]);

  // Visual Flow Graph Layout Coordinates
  const flowLayout = useMemo(() => {
    const routerX = 140;
    const routerY = Math.max(120, (endpoints.length * 52) / 2);

    const endpointsX = 480;
    const endpointsYStep = 56;
    const endpointsStartY = 40;

    const endpointNodes = endpoints.map((ep, i) => ({
      ...ep,
      x: endpointsX,
      y: endpointsStartY + i * endpointsYStep,
      w: 220,
      h: 44
    }));

    const modelsX = 840;
    const modelsYStep = 80;
    const modelsStartY = Math.max(40, (endpointNodes.length * endpointsYStep - allUniqueModels.length * modelsYStep) / 2);

    const modelNodes = allUniqueModels.map((m, i) => ({
      name: m,
      x: modelsX,
      y: modelsStartY + i * modelsYStep,
      w: 130,
      h: 46
    }));

    return {
      router: { name: routers[0]?.fileName || "Server.js", routesCount: endpoints.length, x: routerX, y: routerY, w: 160, h: 56 },
      endpointNodes,
      modelNodes,
      totalHeight: Math.max(800, endpointNodes.length * endpointsYStep + 100),
      totalWidth: 1060
    };
  }, [endpoints, routers, allUniqueModels]);

  return (
    <div className="routes-container">
      {/* 1. TOP HEADER */}
      <div className="routes-header">
        <div className="routes-title-wrap">
          <div className="routes-title">
            <FaNetworkWired size={18} /> Backend API Routes
          </div>
          <span className="routes-endpoint-count-pill">{stats.totalEndpoints} endpoints</span>
        </div>

        <div className="routes-header-actions">
          <button
            className={`routes-action-pill ${viewMode === "flow" ? "active" : ""}`}
            onClick={() => setViewMode(v => v === "flow" ? "table" : "flow")}
          >
            <FaProjectDiagram size={11} /> {viewMode === "flow" ? "Table View" : "Visual Flow Graph"}
          </button>
          <button
            className="routes-action-pill"
            onClick={() => openMongoSchemaTab && openMongoSchemaTab()}
          >
            <FaDatabase size={11} /> ER Diagram
          </button>
          <button
            className="routes-action-pill"
            onClick={handleExportJson}
          >
            <FaDownload size={11} /> Export JSON
          </button>
          <button
            className={`routes-btn-refresh ${isScanningWorkspace ? "scanning" : ""}`}
            onClick={() => scanWorkspaceFiles && scanWorkspaceFiles(true)}
            disabled={isScanningWorkspace}
            title="Scan all workspace files across all folders to parse backend API routes without opening each file"
          >
            <FaSyncAlt className={isScanningWorkspace ? "spinning" : ""} size={10} />
            {isScanningWorkspace
              ? (scanProgress ? `Scanning (${scanProgress.current}/${scanProgress.total})...` : "Scanning...")
              : "⚡ Scan / Refresh"}
          </button>
        </div>
      </div>

      {/* 2. STATS 4-CARD SUMMARY */}
      <div className="routes-stats-row">
        <div className="routes-stat-box">
          <span className="routes-stat-number">{stats.totalEndpoints}</span>
          <span className="routes-stat-label">Endpoints</span>
        </div>
        <div className="routes-stat-box">
          <span className="routes-stat-number">{stats.routerFiles}</span>
          <span className="routes-stat-label">Router Files</span>
        </div>
        <div className="routes-stat-box">
          <span className="routes-stat-number">{stats.protectedCount}</span>
          <span className="routes-stat-label">Protected</span>
        </div>
        <div className="routes-stat-box">
          <span className="routes-stat-number">{stats.linkedModelsCount}</span>
          <span className="routes-stat-label">Linked Models</span>
        </div>
      </div>

      {/* 3. FILTER BAR */}
      <div className="routes-filter-bar">
        <div className="routes-method-pills">
          {["ALL", "GET", "POST", "PUT", "DELETE", "PATCH"].map(m => (
            <button
              key={m}
              className={`routes-method-btn ${activeMethod === m ? "active" : ""}`}
              onClick={() => setActiveMethod(m)}
            >
              {m} ({methodCounts[m] || 0})
            </button>
          ))}
        </div>

        <div className="routes-search-section">
          <input
            type="text"
            className="routes-search-input"
            placeholder="Search path, handler, middleware..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <label className="routes-checkbox-label">
            <input
              type="checkbox"
              checked={protectedOnly}
              onChange={(e) => setProtectedOnly(e.target.checked)}
            />
            Protected Only
          </label>
        </div>
      </div>

      {/* 4. MAIN CONTENT VIEWPORT */}
      {routers.length === 0 ? (
        <div className="routes-empty-state" style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "60px 20px", textAlign: "center", color: "#a1a1aa" }}>
          <FaNetworkWired size={44} style={{ color: "#38bdf8", marginBottom: "16px", opacity: 0.8 }} />
          <h3 style={{ color: "#f4f4f5", fontSize: "18px", marginBottom: "8px" }}>No Backend API Routes Indexed</h3>
          <p style={{ maxWidth: "460px", fontSize: "13px", lineHeight: "1.6", marginBottom: "20px" }}>
            Express server routes, router definitions, and API endpoints are indexed automatically across all workspace folders. Click below to scan the workspace.
          </p>
          <button
            className="routes-btn-refresh"
            onClick={() => scanWorkspaceFiles && scanWorkspaceFiles(true)}
            disabled={isScanningWorkspace}
            style={{ padding: "8px 18px", fontSize: "13px" }}
          >
            <FaSyncAlt className={isScanningWorkspace ? "spinning" : ""} size={12} />
            {isScanningWorkspace ? "Scanning Codebase..." : "⚡ Scan Codebase for Routes"}
          </button>
        </div>
      ) : viewMode === "table" ? (
        <div className="routes-scroll-body">
          {routers.map((router, rIdx) => (
            <div key={rIdx} style={{ marginBottom: "24px" }}>
              <div className="routes-file-header">
                <div>
                  <span className="routes-file-name">{router.fileName}</span>
                  <span className="routes-file-path">{router.filePath}</span>
                </div>
                <span className="routes-file-count">{filteredEndpoints.length} routes</span>
              </div>

              <table className="routes-table">
                <thead>
                  <tr>
                    <th style={{ width: "70px" }}>METHOD</th>
                    <th style={{ width: "200px" }}>ENDPOINT PATH</th>
                    <th style={{ width: "70px" }}>PARAMS</th>
                    <th style={{ width: "100px" }}>MIDDLEWARES</th>
                    <th>HANDLER</th>
                    <th style={{ width: "220px" }}>LINKED MODELS</th>
                    <th style={{ width: "80px", textAlign: "right" }}>ACTION</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredEndpoints.map((ep, eIdx) => {
                    const methodClass = ep.method.toLowerCase();
                    return (
                      <tr key={eIdx}>
                        <td>
                          <span className={`routes-badge-method ${methodClass}`}>
                            {ep.method}
                          </span>
                        </td>
                        <td>
                          <span className="routes-cell-path">
                            {ep.path}
                          </span>
                        </td>
                        <td style={{ color: "#71717a" }}>{ep.params}</td>
                        <td style={{ color: "#71717a" }}>{ep.middlewares}</td>
                        <td>
                          <span className="routes-cell-handler">
                            {ep.handler}
                          </span>
                        </td>
                        <td>
                          <div style={{ display: "flex", gap: "4px", flexWrap: "wrap" }}>
                            {ep.models.map((m, mIdx) => (
                              <span
                                key={mIdx}
                                className="routes-model-pill"
                                onClick={() => handleModelClick(m)}
                                title={`View ${m} in MongoSchema ERD`}
                              >
                                {m}
                              </span>
                            ))}
                          </div>
                        </td>
                        <td style={{ textAlign: "right" }}>
                          <span
                            className="routes-action-code"
                            onClick={() => handleOpenSourceLine(ep)}
                            title={`Jump to line ${ep.line} in ${router.fileName}`}
                          >
                            Code :{ep.line}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          ))}
        </div>
      ) : (
        /* VISUAL FLOW GRAPH VIEW (3-COLUMN BEZIER FLOW) */
        <div className="routes-flow-canvas-viewport">
          <svg
            className="routes-flow-svg"
            style={{
              width: flowLayout.totalWidth,
              height: flowLayout.totalHeight,
              transform: `scale(${zoom / 100})`,
              transformOrigin: "top left"
            }}
          >
            {/* 1. Connecting Bezier Curves from Router to Endpoints */}
            {flowLayout.endpointNodes.map((ep, i) => {
              const x1 = flowLayout.router.x + flowLayout.router.w;
              const y1 = flowLayout.router.y + flowLayout.router.h / 2;
              const x2 = ep.x;
              const y2 = ep.y + ep.h / 2;
              const dx = (x2 - x1) * 0.5;

              return (
                <path
                  key={`r-to-e-${i}`}
                  d={`M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`}
                  className="routes-flow-curve"
                />
              );
            })}

            {/* 2. Connecting Bezier Curves from Endpoints to Linked Models */}
            {flowLayout.endpointNodes.map((ep, i) => {
              const x1 = ep.x + ep.w;
              const y1 = ep.y + ep.h / 2;

              return (ep.models || []).map((mName, mi) => {
                const targetModel = flowLayout.modelNodes.find(mn => mn.name.toLowerCase() === mName.toLowerCase());
                if (!targetModel) return null;

                const x2 = targetModel.x;
                const y2 = targetModel.y + targetModel.h / 2;
                const dx = (x2 - x1) * 0.5;

                return (
                  <path
                    key={`e-to-m-${i}-${mi}`}
                    d={`M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`}
                    className="routes-flow-curve"
                  />
                );
              });
            })}

            {/* 3. Column 1: Router Node */}
            <g
              className="routes-flow-node-router"
              onClick={() => handleOpenSourceLine(flowLayout.endpointNodes[0] || {})}
            >
              <rect
                x={flowLayout.router.x}
                y={flowLayout.router.y}
                width={flowLayout.router.w}
                height={flowLayout.router.h}
                rx={6}
                fill="#0d1416"
                stroke="#00ff88"
                strokeWidth={1.5}
              />
              <text
                x={flowLayout.router.x + 14}
                y={flowLayout.router.y + 24}
                fill="#00ff88"
                fontSize="13"
                fontWeight="700"
              >
                Router: {flowLayout.router.name}
              </text>
              <text
                x={flowLayout.router.x + 14}
                y={flowLayout.router.y + 42}
                fill="#71717a"
                fontSize="11"
              >
                {flowLayout.router.routesCount} routes
              </text>
            </g>

            {/* 4. Column 2: Endpoint Nodes */}
            {flowLayout.endpointNodes.map((ep, i) => (
              <g
                key={`ep-${i}`}
                className="routes-flow-node-endpoint"
                onClick={() => handleOpenSourceLine(ep)}
              >
                <rect
                  x={ep.x}
                  y={ep.y}
                  width={ep.w}
                  height={ep.h}
                  rx={5}
                  fill="#101214"
                  stroke="#27272a"
                  strokeWidth={1}
                />
                <text
                  x={ep.x + 10}
                  y={ep.y + 18}
                  fill={ep.method === "GET" ? "#00ff88" : ep.method === "POST" ? "#38bdf8" : "#f59e0b"}
                  fontSize="10"
                  fontFamily="monospace"
                  fontWeight="700"
                >
                  {ep.method}
                </text>
                <text
                  x={ep.x + (ep.method === "GET" ? 42 : ep.method === "POST" ? 46 : 38)}
                  y={ep.y + 18}
                  fill="#00ff88"
                  fontSize="11"
                  fontFamily="monospace"
                  fontWeight="600"
                >
                  {ep.path}
                </text>
                <text
                  x={ep.x + 10}
                  y={ep.y + 34}
                  fill="#60a5fa"
                  fontSize="10"
                  fontFamily="monospace"
                >
                  {ep.handler?.length > 28 ? ep.handler.slice(0, 26) + "..." : ep.handler}
                </text>
              </g>
            ))}

            {/* 5. Column 3: Model Nodes */}
            {flowLayout.modelNodes.map((mn, i) => (
              <g
                key={`mn-${i}`}
                className="routes-flow-node-model"
                onClick={() => handleModelClick(mn.name)}
              >
                <rect
                  x={mn.x}
                  y={mn.y}
                  width={mn.w}
                  height={mn.h}
                  rx={5}
                  fill="#0c1214"
                  stroke="#38bdf8"
                  strokeWidth={1}
                />
                <text
                  x={mn.x + 12}
                  y={mn.y + 20}
                  fill="#00ff88"
                  fontSize="13"
                  fontWeight="700"
                >
                  {mn.name}
                </text>
                <text
                  x={mn.x + 12}
                  y={mn.y + 36}
                  fill="#71717a"
                  fontSize="10"
                >
                  Model Schema
                </text>
              </g>
            ))}
          </svg>
        </div>
      )}
    </div>
  );
}

