import "./Editor.css";
import { useEffect, useState, useRef, useCallback } from "react";
import MonacoEditor, { DiffEditor } from "@monaco-editor/react";
import useEditor from "../../hooks/useEditor";
import Preview from "../Preview";
import LiveBrowser from "../LiveBrowser/LiveBrowser";
import ArchitectureCanvas from "../Architecture/ArchitectureCanvas";
import MongoSchemaERD from "../Architecture/MongoSchemaERD";
import BackendApiRoutes from "../Architecture/BackendApiRoutes";
import SeleniumRunner from "../RunDebug/SeleniumRunner";
import ApiClient from "../ApiClient/ApiClient";
import SourceControl from "../SourceControl/SourceControl";
import SettingsPage from "../../pages/SettingsPage/SettingsPage";
import TestingSuite from "../TestingSuite/TestingSuite";
import {
  DocxPreview,
  PptxPreview,
  XlsxPreview,
  CsvPreview,
  MarkdownPreview,
  ImagePreview
} from "../Previews";
import { getFileExtension } from "../../utils/fileIcons";
import { isBinaryFile } from "../../services/fileService";
import { checkClientSyntax, getCodeDiagnostics } from "../../utils/codeDiagnostics";
import useFile from "../../hooks/useFile";
import useTheme from "../../hooks/useTheme";

function Editor() {
  const { activeFile, updateContent, setEditorInstance, closeFile, setProblems, isWordWrapOn, saveActiveFile, files } = useEditor();
  const { persistedFolderInfo } = useFile();
  const { currentTheme, isDark } = useTheme();
  const [previewUrl, setPreviewUrl] = useState(null);
  const monacoRef = useRef(null);
  const editorRef = useRef(null);
  const debounceTimerRef = useRef(null);
  const saveActiveFileRef = useRef(saveActiveFile);
  saveActiveFileRef.current = saveActiveFile;
  const mediaBlobUrlRef = useRef(null);

  const runDiagnostics = useCallback(async (code, file, monacoInstance, editorInstance) => {
    if (!file || file.isBinary || file.isPreview || file.isLiveUrl) return;
    const monaco = monacoInstance || monacoRef.current;
    const editor = editorInstance || editorRef.current;
    if (!monaco || !editor) return;

    const model = editor.getModel();
    if (!model) return;

    const language = file.language || getFileExtension(file.name);
    const filename = file.name || "";

    // 1. Instant client-side check (0ms latency)
    const clientMarkers = checkClientSyntax(code, language, filename);
    monaco.editor.setModelMarkers(model, "diagnostics", clientMarkers);

    // 2. Authoritative compiler/interpreter check (GCC, Python AST, etc.)
    try {
      const markers = await getCodeDiagnostics({ code, language, filename });
      if (markers !== undefined) {
        monaco.editor.setModelMarkers(model, "diagnostics", markers);
      }
    } catch {}
  }, []);

  function handleEditorChange(value) {
    updateContent(value);

    // 0ms instant syntax feedback on keystroke
    if (editorRef.current && monacoRef.current && activeFile) {
      const model = editorRef.current.getModel();
      if (model) {
        const lang = activeFile.language || getFileExtension(activeFile.name);
        const instantMarkers = checkClientSyntax(value, lang, activeFile.name);
        monacoRef.current.editor.setModelMarkers(model, "diagnostics", instantMarkers);
      }
    }

    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(() => {
      runDiagnostics(value, activeFile);
    }, 250);
  }

  useEffect(() => {
    let isCancelled = false;

    async function createMediaPreview() {
      if (!activeFile) {
        setPreviewUrl(null);
        return;
      }

      const extension = getFileExtension(activeFile.name);
      const isImage = ["png", "jpg", "jpeg", "gif", "svg", "webp"].includes(extension);
      const isMedia = isImage || ["pdf", "mp3", "wav", "mp4", "webm"].includes(extension);

      if (!isMedia) {
        setPreviewUrl(null);
        return;
      }

      // Find file handle if not directly on activeFile
      let handle = activeFile.handle;
      if (!handle && files) {
        const found = files.find((f) => f.id === activeFile.id || f.path === activeFile.path || f.name === activeFile.name);
        if (found?.handle) {
          handle = found.handle;
        }
      }

      if (handle) {
        try {
          const file = await handle.getFile();
          if (isCancelled) return;

          if (file.size === 0) {
            setPreviewUrl("EMPTY_FILE");
            return;
          }

          if (isImage) {
            // Use FileReader to create permanent, unrevokable Data URL
            const reader = new FileReader();
            reader.onload = () => {
              if (!isCancelled) {
                setPreviewUrl(reader.result);
              }
            };
            reader.onerror = () => {
              if (!isCancelled) {
                if (mediaBlobUrlRef.current) URL.revokeObjectURL(mediaBlobUrlRef.current);
                const url = URL.createObjectURL(file);
                mediaBlobUrlRef.current = url;
                setPreviewUrl(url);
              }
            };
            reader.readAsDataURL(file);
            return;
          } else {
            // For PDF, audio, video: use Blob URL with proper lifetime management
            if (mediaBlobUrlRef.current) {
              URL.revokeObjectURL(mediaBlobUrlRef.current);
            }
            const mimeType = extension === "mp4" ? "video/mp4" :
                             extension === "mp3" ? "audio/mpeg" :
                             extension === "pdf" ? "application/pdf" : file.type;
            const blob = file.type ? file : new Blob([await file.arrayBuffer()], { type: mimeType });
            if (isCancelled) return;
            const url = URL.createObjectURL(blob);
            mediaBlobUrlRef.current = url;
            setPreviewUrl(url);
            return;
          }
        } catch (e) {
          console.error("Failed to load binary media from handle:", e);
        }
      }

      // If no handle or handle failed, try backend host path
      const filePath = activeFile.path || (persistedFolderInfo?.path ? `${persistedFolderInfo.path}/${activeFile.name}` : null);
      if (filePath) {
        try {
          const res = await fetch(`/api/sandbox/workspace/file?path=${encodeURIComponent(filePath)}`);
          if (res.ok) {
            const blob = await res.blob();
            if (isCancelled) return;
            if (blob.size === 0) {
              setPreviewUrl("EMPTY_FILE");
              return;
            }
            if (isImage) {
              const reader = new FileReader();
              reader.onload = () => {
                if (!isCancelled) setPreviewUrl(reader.result);
              };
              reader.readAsDataURL(blob);
              return;
            } else {
              if (mediaBlobUrlRef.current) URL.revokeObjectURL(mediaBlobUrlRef.current);
              const url = URL.createObjectURL(blob);
              mediaBlobUrlRef.current = url;
              setPreviewUrl(url);
              return;
            }
          }
        } catch (err) {
          console.warn("Backend media load error:", err);
        }
      }

      setPreviewUrl(null);
    }

    createMediaPreview();

    return () => {
      isCancelled = true;
    };
  }, [activeFile?.id, activeFile?.name, activeFile?.path, files, persistedFolderInfo?.path]);

  function renderBinaryPreview() {
    if (!activeFile) {
      return null;
    }

    const extension = getFileExtension(activeFile.name);
    const imageExtensions = new Set(["png", "jpg", "jpeg", "gif", "svg", "webp"]);

    if (previewUrl === "EMPTY_FILE") {
      return (
        <div className="editor-binary-state" style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100%", gap: "10px", color: "#cccccc" }}>
          <div style={{ fontSize: "28px" }}>⚠️</div>
          <div style={{ fontSize: "16px", fontWeight: "600" }}>Image file is empty (0 bytes)</div>
          <div style={{ color: "#858585", fontSize: "13px" }}>{activeFile.name} does not contain any image data.</div>
        </div>
      );
    }

    if (extension === "pdf") {
      if (!previewUrl) {
        return <div className="editor-binary-state">Loading PDF preview...</div>;
      }
      return <iframe title={activeFile.name} src={previewUrl} className="binary-preview" />;
    }

    if (imageExtensions.has(extension)) {
      if (!previewUrl) {
        return <div className="editor-binary-state">Loading image preview...</div>;
      }
      return <ImagePreview src={previewUrl} fileName={activeFile.name} />;
    }

    if (extension === "mp3" || extension === "wav") {
      if (!previewUrl) {
        return <div className="editor-binary-state">Loading audio preview...</div>;
      }
      return (
        <div className="editor-binary-state media-preview">
          <audio controls src={previewUrl} className="audio-player">
            Your browser does not support the audio element.
          </audio>
        </div>
      );
    }

    if (extension === "mp4" || extension === "webm") {
      if (!previewUrl) {
        return <div className="editor-binary-state">Loading video preview...</div>;
      }
      return (
        <div className="editor-binary-state media-preview">
          <video controls src={previewUrl} className="video-player" />
        </div>
      );
    }

    return (
      <div className="editor-binary-state">
        <div>Cannot preview this binary file type directly in the editor.</div>
        <div>{activeFile.name}</div>
        {previewUrl && (
          <a href={previewUrl} target="_blank" rel="noreferrer">
            Open file externally
          </a>
        )}
      </div>
    );
  }

  const getMonacoThemeConfig = (theme) => {
    const isPixelatteDark = theme?.id === "pixelatte";
    const isPixelatteLight = theme?.id === "pixelatte-light";
    const ui = theme?.ui || {};

    if (isPixelatteLight) {
      return {
        base: "vs",
        inherit: true,
        rules: [
          { token: "", foreground: "1f1d16" },
          { token: "keyword", foreground: "c90057", fontStyle: "bold" },
          { token: "string", foreground: "008744" },
          { token: "number", foreground: "a84200" },
          { token: "comment", foreground: "7a288a", fontStyle: "italic" },
          { token: "identifier", foreground: "1f1d16" },
          { token: "type", foreground: "b38600", fontStyle: "bold" },
          { token: "delimiter", foreground: "1f1d16" },
          { token: "operator", foreground: "c90057" },
          { token: "function", foreground: "007769", fontStyle: "bold" }
        ],
        colors: {
          "editor.background": "#f7f4ea",
          "editor.foreground": "#1f1d16",
          "editorLineNumber.foreground": "#a09885",
          "editorLineNumber.activeForeground": "#1f1d16",
          "editorCursor.foreground": "#1f1d16",
          "editor.selectionBackground": "#ded9c8bb",
          "editor.inactiveSelectionBackground": "#eae6d988",
          "editor.lineHighlightBackground": "#ede8d866",
          "editor.lineHighlightBorder": "#1f1d1633",
          "editorIndentGuide.background": "#d0c9b4",
          "editorIndentGuide.activeBackground": "#1f1d16",
          "editorGutter.background": "#ded9c8",
          "editorWidget.background": "#ffffff",
          "editorWidget.border": "#1f1d16",
          "editorSuggestWidget.background": "#ffffff",
          "editorSuggestWidget.border": "#1f1d16",
          "editorSuggestWidget.selectedBackground": "#f59e0b",
          "editorSuggestWidget.highlightForeground": "#007769"
        }
      };
    }

    if (isPixelatteDark) {
      return {
        base: "vs-dark",
        inherit: true,
        rules: [
          { token: "", foreground: "ffff00" },
          { token: "keyword", foreground: "ff70a6", fontStyle: "bold" },
          { token: "string", foreground: "00f076" },
          { token: "number", foreground: "ffe600" },
          { token: "comment", foreground: "7b2cbf", fontStyle: "italic" },
          { token: "identifier", foreground: "ffff00" },
          { token: "type", foreground: "00f5d4" },
          { token: "delimiter", foreground: "facc15" },
          { token: "operator", foreground: "ff007f" },
          { token: "function", foreground: "00f5d4", fontStyle: "bold" }
        ],
        colors: {
          "editor.background": "#0f0728",
          "editor.foreground": "#ffff00",
          "editorLineNumber.foreground": "#7b2cbf",
          "editorLineNumber.activeForeground": "#ffff00",
          "editorCursor.foreground": "#ffff00",
          "editor.selectionBackground": "#281566bb",
          "editor.inactiveSelectionBackground": "#1b0e4588",
          "editor.lineHighlightBackground": "#170c3d88",
          "editor.lineHighlightBorder": "#facc1544",
          "editorIndentGuide.background": "#221356",
          "editorIndentGuide.activeBackground": "#facc15",
          "editorGutter.background": "#0f0728",
          "editorWidget.background": "#170c3d",
          "editorWidget.border": "#facc15",
          "editorSuggestWidget.background": "#170c3d",
          "editorSuggestWidget.border": "#facc15",
          "editorSuggestWidget.selectedBackground": "#351c86",
          "editorSuggestWidget.highlightForeground": "#00f5d4"
        }
      };
    }
    return {
      base: theme?.type === "light" ? "vs" : "vs-dark",
      inherit: true,
      rules: [],
      colors: {
        "editor.background": ui.editorBg || (theme?.type === "light" ? "#ffffff" : "#1e1e1e"),
        "editorLineNumber.foreground": ui.textSecondary || "#858585",
        "editorCursor.foreground": ui.accentColor || (theme?.type === "light" ? "#007acc" : "#ffffff")
      }
    };
  };

  function handleEditorDidMount(editor, monaco) {
    editor.focus();
    editorRef.current = editor;
    monacoRef.current = monaco;
    if (setEditorInstance) {
      setEditorInstance(editor);
    }

    const themeName = currentTheme ? `hyperion-${currentTheme.id}` : "hyperion-dark";
    const themeConfig = getMonacoThemeConfig(currentTheme);
    monaco.editor.defineTheme(themeName, themeConfig);
    monaco.editor.setTheme(themeName);

    // Run initial diagnostics on editor mount
    if (activeFile && activeFile.content != null) {
      runDiagnostics(activeFile.content, activeFile, monaco, editor);
    }
  }

  // Synchronize Monaco markers with Problems panel in real-time
  useEffect(() => {
    const monaco = monacoRef.current;
    if (!monaco) return;

    const syncMarkers = () => {
      const allMarkers = monaco.editor.getModelMarkers({});
      const formatted = allMarkers.map((m) => {
        const uriPath = m.resource?.path || "";
        const fname = uriPath.split("/").pop() || activeFile?.name || "file";
        return {
          id: `${fname}-${m.startLineNumber}-${m.startColumn}-${m.message}`,
          filename: fname,
          fileId: activeFile?.id,
          message: m.message,
          severity: m.severity, // 8 = Error, 4 = Warning, 2 = Info
          startLineNumber: m.startLineNumber,
          startColumn: m.startColumn,
          endLineNumber: m.endLineNumber,
          endColumn: m.endColumn,
          source: m.source || (m.severity === 8 ? "Error" : "Warning")
        };
      });
      if (setProblems) {
        setProblems(formatted);
      }
    };

    const disposable = monaco.editor.onDidChangeMarkers(() => {
      syncMarkers();
    });

    syncMarkers();

    return () => disposable.dispose();
  }, [setProblems, activeFile?.id, activeFile?.name]);

  // Update Monaco theme dynamically when IDE theme changes
  useEffect(() => {
    if (!monacoRef.current || !currentTheme) return;
    const monaco = monacoRef.current;
    const themeName = `hyperion-${currentTheme.id}`;
    const themeConfig = getMonacoThemeConfig(currentTheme);
    monaco.editor.defineTheme(themeName, themeConfig);
    monaco.editor.setTheme(themeName);
  }, [currentTheme]);

  // Re-run diagnostics when switching active file
  useEffect(() => {
    if (activeFile && activeFile.content != null && monacoRef.current && editorRef.current) {
      runDiagnostics(activeFile.content, activeFile);
    }
  }, [activeFile?.id, activeFile?.name, runDiagnostics]);

  if (!activeFile) {
    return (
      <div className="editor-container">
        <div className="editor-empty-state">Select a file from the explorer to start editing.</div>
      </div>
    );
  }

  // 1. Live Browser Preview tab (Hyperion IDE Simple Browser style)
  if (activeFile.isLiveUrl || activeFile.type === "browser") {
    return (
      <div className="editor-container">
        <LiveBrowser
          initialUrl={activeFile.url}
          title={activeFile.name}
          onClose={() => closeFile(activeFile.id)}
        />
      </div>
    );
  }

  // 1b. Side-by-side Diff comparison tab
  if (activeFile.isDiff || activeFile.type === "diff") {
    return (
      <div className="editor-container">
        <DiffEditor
          height="100%"
          theme={currentTheme ? `hyperion-${currentTheme.id}` : (isDark ? "vs-dark" : "vs")}
          original={activeFile.originalFile?.content || ""}
          modified={activeFile.modifiedFile?.content || ""}
          language={activeFile.modifiedFile?.language || activeFile.originalFile?.language || "javascript"}
          options={{
            readOnly: false,
            minimap: { enabled: false },
            automaticLayout: true
          }}
        />
      </div>
    );
  }

  // Architecture Blueprint Canvas tab
  if (activeFile.type === "architecture" || activeFile.isArchitecture) {
    return (
      <div className="editor-container">
        <ArchitectureCanvas />
      </div>
    );
  }

  // MongoSchema ERD tab
  if (activeFile.type === "mongoschema" || activeFile.isMongoSchema) {
    return (
      <div className="editor-container">
        <MongoSchemaERD initialModel={activeFile.initialModel} />
      </div>
    );
  }

  // Backend API Routes tab
  if (activeFile.type === "backend-routes" || activeFile.isBackendRoutes) {
    return (
      <div className="editor-container">
        <BackendApiRoutes />
      </div>
    );
  }

  // Selenium QA Studio tab
  if (activeFile.type === "selenium-studio" || activeFile.isSeleniumStudio) {
    return (
      <div className="editor-container">
        <SeleniumRunner isStudioMode={true} />
      </div>
    );
  }

  // API Client & cURL tab
  if (activeFile.type === "api-client" || activeFile.isApiClient) {
    return (
      <div className="editor-container">
        <ApiClient isFullTab={true} />
      </div>
    );
  }

  // Source Control Git Studio tab
  if (activeFile.type === "source-control" || activeFile.isSourceControl) {
    return (
      <div className="editor-container">
        <SourceControl isFullTab={true} />
      </div>
    );
  }

  // Settings tab
  if (activeFile.type === "settings" || activeFile.isSettings) {
    return (
      <div className="editor-container">
        <SettingsPage />
      </div>
    );
  }

  // Individual Testing Suite Tabs: Load Test, Speed Test, Secret Test
  if (activeFile.type === "load-test" || activeFile.isLoadTest) {
    return (
      <div className="editor-container">
        <TestingSuite mode="load" />
      </div>
    );
  }

  if (activeFile.type === "speed-test" || activeFile.isSpeedTest) {
    return (
      <div className="editor-container">
        <TestingSuite mode="speed" />
      </div>
    );
  }

  if (activeFile.type === "secret-test" || activeFile.isSecretTest) {
    return (
      <div className="editor-container">
        <TestingSuite mode="secret" />
      </div>
    );
  }

  // Unified Testing Studio fallback
  if (activeFile.type === "testing-studio" || activeFile.isTestingStudio) {
    return (
      <div className="editor-container">
        <TestingSuite mode={activeFile.initialTab || "all"} />
      </div>
    );
  }

  // 2. Static HTML / React Live Sandbox Preview tab
  if (activeFile.isPreview) {
    return (
      <div className="editor-container">
        <div className="editor-preview-container">
          <Preview sourceFile={activeFile.sourceFile} />
        </div>
      </div>
    );
  }

  const ext = getFileExtension(activeFile.name);

  // 2. Microsoft Word Document (.docx, .doc)
  if (ext === "docx" || ext === "doc") {
    return (
      <div className="editor-container">
        <DocxPreview file={activeFile} />
      </div>
    );
  }

  // 3. Microsoft PowerPoint Presentation (.pptx, .ppt)
  if (ext === "pptx" || ext === "ppt") {
    return (
      <div className="editor-container">
        <PptxPreview file={activeFile} />
      </div>
    );
  }

  // 4. Microsoft Excel Spreadsheet (.xlsx, .xls)
  if (ext === "xlsx" || ext === "xls") {
    return (
      <div className="editor-container">
        <XlsxPreview file={activeFile} />
      </div>
    );
  }

  // 5. CSV / TSV Data (.csv, .tsv)
  if (ext === "csv" || ext === "tsv") {
    return (
      <div className="editor-container">
        <CsvPreview file={activeFile} />
      </div>
    );
  }

  // 6. Markdown (.md, .markdown)
  if (ext === "md" || ext === "markdown") {
    return (
      <div className="editor-container">
        <MarkdownPreview
          file={activeFile}
          onContentChange={handleEditorChange}
          onMount={handleEditorDidMount}
        />
      </div>
    );
  }

  // 7. Binary preview (PDF, Image, Audio, Video)
  if (activeFile.isBinary || isBinaryFile(activeFile.name)) {
    return (
      <div className="editor-container">
        {renderBinaryPreview()}
      </div>
    );
  }

  // 8. Code & Text Editor (Monaco)
  return (
    <div className="editor-container">
      <MonacoEditor
        height="100%"
        theme={currentTheme ? `hyperion-${currentTheme.id}` : (isDark ? "vs-dark" : "vs")}
        language={activeFile.language || "javascript"}
        value={activeFile.content || ""}
        onChange={handleEditorChange}
        onMount={handleEditorDidMount}
        options={{
          minimap: { enabled: true },
          fontSize: 15,
          fontFamily: "Consolas",
          lineNumbers: "on",
          automaticLayout: true,
          scrollBeyondLastLine: false,
          tabSize: 4,
          wordWrap: isWordWrapOn ? "on" : "off",
          cursorBlinking: "smooth",
          smoothScrolling: true,
          mouseWheelZoom: true,
          renderWhitespace: "selection",
          bracketPairColorization: { enabled: true },
          guides: { indentation: true },
          formatOnPaste: true,
          formatOnType: true
        }}
      />
    </div>
  );
}

export default Editor;

