import React, { useState, useRef, useEffect } from "react";
import { FaSearchPlus, FaSearchMinus, FaRedo } from "react-icons/fa";
import "./ImagePreview.css";

export default function ImagePreview({ src, fileName }) {
  const [zoom, setZoom] = useState(1);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
  const [hasError, setHasError] = useState(false);
  const containerRef = useRef(null);
  const isDraggingRef = useRef(false);
  const startPosRef = useRef({ x: 0, y: 0, scrollLeft: 0, scrollTop: 0 });

  useEffect(() => {
    setHasError(false);
  }, [src]);

  const handleImageLoad = (e) => {
    setHasError(false);
    const { naturalWidth, naturalHeight } = e.target;
    setDimensions({ width: naturalWidth, height: naturalHeight });
  };

  const handleImageError = () => {
    setHasError(true);
  };

  const handleZoomIn = () => {
    setZoom((prev) => Math.min(Number((prev + 0.25).toFixed(2)), 5));
  };

  const handleZoomOut = () => {
    setZoom((prev) => Math.max(Number((prev - 0.25).toFixed(2)), 0.25));
  };

  const handleResetZoom = () => {
    setZoom(1);
  };

  // Mouse wheel zoom
  const handleWheel = (e) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      if (e.deltaY < 0) {
        handleZoomIn();
      } else {
        handleZoomOut();
      }
    }
  };

  // Drag to pan
  const handleMouseDown = (e) => {
    if (e.button !== 0) return; // Only left-click
    isDraggingRef.current = true;
    startPosRef.current = {
      x: e.clientX,
      y: e.clientY,
      scrollLeft: containerRef.current ? containerRef.current.scrollLeft : 0,
      scrollTop: containerRef.current ? containerRef.current.scrollTop : 0
    };
    if (containerRef.current) {
      containerRef.current.style.cursor = "grabbing";
      containerRef.current.style.userSelect = "none";
    }
  };

  const handleMouseMove = (e) => {
    if (!isDraggingRef.current || !containerRef.current) return;
    const dx = e.clientX - startPosRef.current.x;
    const dy = e.clientY - startPosRef.current.y;
    containerRef.current.scrollLeft = startPosRef.current.scrollLeft - dx;
    containerRef.current.scrollTop = startPosRef.current.scrollTop - dy;
  };

  const handleMouseUp = () => {
    isDraggingRef.current = false;
    if (containerRef.current) {
      containerRef.current.style.cursor = "default";
      containerRef.current.style.userSelect = "auto";
    }
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, []);

  return (
    <div
      className="image-preview-root"
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      {/* Hyperion IDE Floating Zoom & Info Toolbar */}
      <div className="image-preview-toolbar" onMouseDown={(e) => e.stopPropagation()}>
        <button
          className="img-tool-btn"
          onClick={handleZoomOut}
          title="Zoom Out (Ctrl+Minus / Ctrl+Wheel Down)"
          aria-label="Zoom Out"
        >
          <FaSearchMinus />
        </button>

        <span
          className="img-zoom-label"
          onClick={handleResetZoom}
          title="Click to reset to 100% (1:1 Natural Size)"
        >
          {Math.round(zoom * 100)}%
        </span>

        <button
          className="img-tool-btn"
          onClick={handleZoomIn}
          title="Zoom In (Ctrl+Plus / Ctrl+Wheel Up)"
          aria-label="Zoom In"
        >
          <FaSearchPlus />
        </button>

        <button
          className="img-tool-btn"
          onClick={handleResetZoom}
          title="Reset to 100% Original Size"
          aria-label="Reset Zoom"
        >
          <FaRedo />
        </button>

        {dimensions.width > 0 && (
          <span className="img-dimensions-badge">
            {dimensions.width} × {dimensions.height} px
          </span>
        )}
      </div>

      {/* Centered Image Canvas - strictly natural size, never fit-to-window */}
      <div className="image-viewport-wrapper">
        <div
          className="image-canvas-frame"
          style={{
            transform: `scale(${zoom})`,
            transformOrigin: "top center"
          }}
        >
          {hasError ? (
            <div style={{ padding: "40px 28px", color: "#f87171", textAlign: "center", lineHeight: "1.5" }}>
              <div style={{ fontSize: "28px", marginBottom: "8px" }}>⚠️</div>
              <div style={{ fontSize: "14px", fontWeight: "600", color: "#f3f4f6" }}>
                Could not display image: {fileName}
              </div>
              <div style={{ fontSize: "12px", color: "#9ca3af", marginTop: "4px" }}>
                The image file may be empty, corrupted, or unsupported.
              </div>
            </div>
          ) : (
            <img
              src={src}
              alt={fileName || "Image Preview"}
              onLoad={handleImageLoad}
              onError={handleImageError}
              className="natural-image"
              draggable={false}
            />
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import MonacoEditor from "@monaco-editor/react";
import {
  FaMarkdown,
  FaEye,
  FaEdit,
  FaColumns,
  FaCopy,
  FaCheck,
  FaSpinner
} from "react-icons/fa";
import "./MarkdownPreview.css";

function CodeBlock({ node, inline, className, children, ...props }) {
  const [copied, setCopied] = useState(false);
  const match = /language-(\w+)/.exec(className || "");
  const lang = match ? match[1] : "";
  const codeString = String(children).replace(/\n$/, "");

  const handleCopyCode = () => {
    navigator.clipboard.writeText(codeString).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  if (inline) {
    return (
      <code className="md-inline-code" {...props}>
        {children}
      </code>
    );
  }

  return (
    <div className="md-code-block-wrapper">
      <div className="md-code-block-header">
        <span className="md-code-lang">{lang || "text"}</span>
        <button
          className="md-code-copy-btn"
          onClick={handleCopyCode}
          title="Copy code"
        >
          {copied ? <FaCheck style={{ color: "#22c55e" }} /> : <FaCopy />}
        </button>
      </div>
      <pre className="md-pre" {...props}>
        <code className={className}>{children}</code>
      </pre>
    </div>
  );
}

export function MarkdownPreview({ file, onContentChange, onMount }) {
  const [content, setContent] = useState("");
  const [mode, setMode] = useState("preview"); // "preview" | "split" | "editor"
  const [loading, setLoading] = useState(true);
  const [copiedAll, setCopiedAll] = useState(false);

  useEffect(() => {
    let isCancelled = false;

    async function loadMarkdown() {
      setLoading(true);
      try {
        let text = "";
        if (file?.content != null && typeof file.content === "string") {
          text = file.content;
        } else if (file?.handle) {
          const rawFile = await file.handle.getFile();
          text = await rawFile.text();
        } else if (file?.rawFile && typeof file.rawFile.text === "function") {
          text = await file.rawFile.text();
        }

        if (!isCancelled) {
          setContent(text || "");
          setLoading(false);
        }
      } catch (err) {
        if (!isCancelled) {
          console.error("Error loading markdown:", err);
          setContent("# Error\nFailed to read markdown file.");
          setLoading(false);
        }
      }
    }

    if (file) {
      loadMarkdown();
    }

    return () => {
      isCancelled = true;
    };
  }, [file]);

  const handleChange = (val) => {
    setContent(val || "");
    if (onContentChange) {
      onContentChange(val || "");
    }
  };

  const handleCopyAll = () => {
    navigator.clipboard.writeText(content).then(() => {
      setCopiedAll(true);
      setTimeout(() => setCopiedAll(false), 2000);
    });
  };

  // Word & character statistics
  const words = content.trim().split(/\s+/).filter(Boolean).length;
  const characters = content.length;

  return (
    <div className="md-preview-container">
      {/* Top Toolbar */}
      <div className="md-toolbar">
        <div className="md-toolbar-left">
          <FaMarkdown className="md-brand-icon" />
          <span className="md-file-name">{file?.name || "document.md"}</span>
          <span className="md-badge">Markdown</span>
        </div>

        <div className="md-toolbar-center">
          <div className="md-mode-switch">
            <button
              className={`md-mode-btn ${mode === "preview" ? "active" : ""}`}
              onClick={() => setMode("preview")}
              title="Rich Rendered Preview"
            >
              <FaEye />
              <span>Preview</span>
            </button>
            <button
              className={`md-mode-btn ${mode === "split" ? "active" : ""}`}
              onClick={() => setMode("split")}
              title="Side-by-Side Editor & Preview"
            >
              <FaColumns />
              <span>Split</span>
            </button>
            <button
              className={`md-mode-btn ${mode === "editor" ? "active" : ""}`}
              onClick={() => setMode("editor")}
              title="Raw Code Editor"
            >
              <FaEdit />
              <span>Editor</span>
            </button>
          </div>
        </div>

        <div className="md-toolbar-right">
          <span className="md-stat-badge">{words.toLocaleString()} words</span>
          <button
            className="md-tool-btn"
            onClick={handleCopyAll}
            title="Copy Raw Markdown"
          >
            {copiedAll ? <FaCheck style={{ color: "#22c55e" }} /> : <FaCopy />}
            <span>Copy</span>
          </button>
        </div>
      </div>

      {/* Main View Area */}
      <div className="md-view-wrapper">
        {loading ? (
          <div className="md-state-view">
            <FaSpinner className="md-spinner" />
            <span>Loading markdown...</span>
          </div>
        ) : (
          <div className={`md-body-layout md-layout-${mode}`}>
            {/* Monaco Editor Pane (Visible in 'editor' and 'split' modes) */}
            {(mode === "editor" || mode === "split") && (
              <div className="md-editor-pane">
                <MonacoEditor
                  height="100%"
                  language="markdown"
                  value={content}
                  onChange={handleChange}
                  onMount={onMount}
                  theme="vs-dark"
                  options={{
                    minimap: { enabled: false },
                    fontSize: 14,
                    fontFamily: "Consolas",
                    lineNumbers: "on",
                    automaticLayout: true,
                    wordWrap: "on",
                    scrollBeyondLastLine: false,
                    tabSize: 2
                  }}
                />
              </div>
            )}

            {/* Rendered Markdown Pane (Visible in 'preview' and 'split' modes) */}
            {(mode === "preview" || mode === "split") && (
              <div className="md-rendered-pane">
                <article className="md-article">
                  <ReactMarkdown
                    remarkPlugins={[remarkGfm]}
                    components={{
                      code: CodeBlock
                    }}
                  >
                    {content}
                  </ReactMarkdown>
                </article>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default MarkdownPreview;

import "./Repl.css";
import { useEffect, useRef, useState, useContext, useCallback } from "react";
import { Terminal as XtermTerminal } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";
import { WebLinksAddon } from "@xterm/addon-web-links";
import "@xterm/xterm/css/xterm.css";
import {
  FaPlay,
  FaRedo,
  FaTrash,
  FaStop,
  FaCheckCircle,
  FaSpinner
} from "react-icons/fa";
import { SiPython, SiNodedotjs } from "react-icons/si";
import { startReplSession, evalReplCode, exitReplSession } from "../../services/sandboxService";
import { EditorContext } from "../../context/EditorContext";
import { FileContext } from "../../context/FileContext";
import useTheme from "../../hooks/useTheme";
import { getStoredWorkspaceState } from "../../services/workspacePersistence";

export default function Repl() {
  const { currentTheme, isDark } = useTheme();

  const getXtermTheme = (theme, dark) => {
    const ui = theme?.ui || {};
    const bg = ui.editorBg || ui.bgPrimary || (dark ? "#181818" : "#ffffff");
    const fg = ui.textPrimary || (dark ? "#d4d4d4" : "#1f2328");
    const cursor = ui.accentColor || (dark ? "#ffffff" : "#0969da");
    const selectBg = dark ? "rgba(255, 255, 255, 0.2)" : "rgba(9, 105, 218, 0.25)";
    return {
      background: bg,
      foreground: fg,
      cursor: cursor,
      cursorAccent: bg,
      selectionBackground: selectBg,
      black: dark ? "#1e1e1e" : "#24292e",
      brightBlack: dark ? "#808080" : "#6a737d",
      red: "#f44747",
      brightRed: "#f44747",
      green: "#6a9955",
      brightGreen: "#3fb950",
      yellow: "#dcdcaa",
      brightYellow: "#d7ba7d",
      blue: "#569cd6",
      brightBlue: "#2188ff",
      magenta: "#c586c0",
      brightMagenta: "#bc8cff",
      cyan: "#4ec9b0",
      brightCyan: "#39c5bb",
      white: dark ? "#d4d4d4" : "#24292e",
      brightWhite: dark ? "#ffffff" : "#000000"
    };
  };
  const terminalRef = useRef(null);
  const xtermRef = useRef(null);
  const fitAddonRef = useRef(null);

  const editorCtx = useContext(EditorContext);
  const fileCtx = useContext(FileContext);
  const getSelectedText = editorCtx?.getSelectedText;

  const cachedState = getStoredWorkspaceState();
  const workspacePath = fileCtx?.persistedFolderInfo?.path || cachedState?.folderPath || null;

  const [runtime, setRuntime] = useState("python");
  const [isRunning, setIsRunning] = useState(false);
  const [status, setStatus] = useState("initializing");

  const currentCommand = useRef("");
  const historyRef = useRef([]);
  const historyIndex = useRef(-1);
  const promptRef = useRef(">>> ");
  const isMultiLineRef = useRef(false);
  const activeSessionIdRef = useRef(`repl-panel-${runtime}`);
  const runtimeRef = useRef(runtime);
  runtimeRef.current = runtime;

  const initSession = useCallback(async (selectedRuntime = runtime) => {
    const term = xtermRef.current;
    if (!term) return;

    setStatus("initializing");
    term.clear();
    term.writeln(`\x1b[90mStarting ${selectedRuntime.toUpperCase()} interactive REPL session...\x1b[0m`);

    const sessionId = `repl-panel-${selectedRuntime}-${Date.now()}`;
    activeSessionIdRef.current = sessionId;

    try {
      const res = await startReplSession({
        sessionId,
        runtime: selectedRuntime,
        cwd: workspacePath
      });

      term.clear();
      if (res.banner) {
        const lines = res.banner.split(/\r?\n/);
        lines.forEach(l => term.writeln(l));
      }

      const p = res.prompt || (selectedRuntime === "node" ? "> " : ">>> ");
      promptRef.current = p;
      isMultiLineRef.current = false;
      currentCommand.current = "";
      historyIndex.current = -1;

      term.write(p);
      setStatus("ready");
    } catch (err) {
      term.writeln(`\x1b[31mFailed to start ${selectedRuntime} REPL: ${err.message}\x1b[0m`);
      term.writeln(`\x1b[90mCheck if ${selectedRuntime} runtime is installed on the host machine.\x1b[0m`);
      setStatus("error");
    }
  }, [runtime, workspacePath]);

  // Initialize terminal instance once
  useEffect(() => {
    if (!terminalRef.current) return;

    const term = new XtermTerminal({
      cursorBlink: true,
      cursorStyle: "block",
      fontSize: 14,
      fontFamily: "'Cascadia Code', Consolas, 'Fira Code', monospace",
      lineHeight: 1.25,
      theme: getXtermTheme(currentTheme, isDark)
    });

    const fitAddon = new FitAddon();
    term.loadAddon(fitAddon);
    term.loadAddon(new WebLinksAddon());

    term.open(terminalRef.current);
    fitAddon.fit();

    xtermRef.current = term;
    fitAddonRef.current = fitAddon;

    const resizeObserver = new ResizeObserver(() => {
      try {
        fitAddon.fit();
      } catch {}
    });
    resizeObserver.observe(terminalRef.current);

    // Keyboard navigation
    term.onKey(({ domEvent }) => {
      const activePrompt = promptRef.current || (runtime === "node" ? "> " : ">>> ");

      // Ctrl+C (Cancel line or interrupt)
      if (domEvent.ctrlKey && domEvent.key.toLowerCase() === "c") {
        domEvent.preventDefault();
        term.write(`^C\r\n${activePrompt}`);
        currentCommand.current = "";
        historyIndex.current = -1;
        isMultiLineRef.current = false;
        return;
      }

      // Ctrl+L (Clear screen)
      if (domEvent.ctrlKey && domEvent.key.toLowerCase() === "l") {
        domEvent.preventDefault();
        term.clear();
        term.write(activePrompt + currentCommand.current);
        return;
      }

      // Arrow Up
      if (domEvent.key === "ArrowUp") {
        domEvent.preventDefault();
        const hist = historyRef.current;
        if (hist.length === 0) return;

        let newIdx;
        if (historyIndex.current === -1) {
          newIdx = hist.length - 1;
        } else if (historyIndex.current > 0) {
          newIdx = historyIndex.current - 1;
        } else {
          newIdx = 0;
        }

        historyIndex.current = newIdx;
        const cmd = hist[newIdx] || "";
        term.write(`\x1b[2K\r${activePrompt}${cmd}`);
        currentCommand.current = cmd;
        return;
      }

      // Arrow Down
      if (domEvent.key === "ArrowDown") {
        domEvent.preventDefault();
        const hist = historyRef.current;
        if (hist.length === 0 || historyIndex.current === -1) return;

        if (historyIndex.current < hist.length - 1) {
          historyIndex.current++;
          const cmd = hist[historyIndex.current] || "";
          term.write(`\x1b[2K\r${activePrompt}${cmd}`);
          currentCommand.current = cmd;
        } else {
          historyIndex.current = -1;
          term.write(`\x1b[2K\r${activePrompt}`);
          currentCommand.current = "";
        }
        return;
      }
    });

    // Character data handler
    term.onData(async (data) => {
      if (data === "\r") {
        const toEval = currentCommand.current;
        currentCommand.current = "";
        historyIndex.current = -1;

        const activePrompt = promptRef.current || (runtime === "node" ? "> " : ">>> ");

        // Empty line when NOT in multi-line block
        if (!toEval.trim() && !isMultiLineRef.current) {
          term.write(`\r\n${activePrompt}`);
          return;
        }

        term.write("\r\n");

        if (toEval.trim()) {
          historyRef.current.push(toEval);
        }

        // Handle exit command
        const trimmed = toEval.trim();
        const isExit = trimmed === "exit()" || trimmed === "quit()" || trimmed === ".exit" ||
          (trimmed === "exit" && (runtimeRef.current === "python" || runtimeRef.current === "node"));

        if (isExit) {
          term.writeln(`\x1b[90m[Exited ${runtimeRef.current.toUpperCase()} REPL. Restarting session...]\x1b[0m`);
          await exitReplSession(activeSessionIdRef.current).catch(() => {});
          await initSession(runtimeRef.current);
          return;
        }

        setIsRunning(true);
        setStatus("evaluating");

        try {
          const res = await evalReplCode({
            sessionId: activeSessionIdRef.current,
            code: toEval
          });

          if (res.exited) {
            term.writeln(`\x1b[90m[REPL session closed by process]\x1b[0m`);
            await initSession(runtimeRef.current);
            return;
          }

          if (res.output) {
            const lines = res.output.replace(/\r\n/g, "\n").split("\n");
            lines.forEach(l => term.writeln(l));
          }

          const nextPrompt = res.prompt || (runtimeRef.current === "node" ? "> " : ">>> ");
          promptRef.current = nextPrompt;
          isMultiLineRef.current = !!res.isMultiLine;
          term.write(nextPrompt);
        } catch (err) {
          term.writeln(`\x1b[31mError: ${err.message}\x1b[0m`);
          const defaultPrompt = runtimeRef.current === "node" ? "> " : ">>> ";
          promptRef.current = defaultPrompt;
          isMultiLineRef.current = false;
          term.write(defaultPrompt);
        } finally {
          setIsRunning(false);
          setStatus("ready");
        }

      } else if (data === "\x7f" || data === "\b") {
        if (currentCommand.current.length > 0) {
          term.write("\b \b");
          currentCommand.current = currentCommand.current.slice(0, -1);
        }
      } else if (data.length > 0 && !data.includes("\x1b")) {
        currentCommand.current += data;
        term.write(data);
      }
    });

    initSession(runtime);

    return () => {
      exitReplSession(activeSessionIdRef.current).catch(() => {});
      term.dispose();
      xtermRef.current = null;
    };
  }, []);

  // Update xterm theme dynamically when active theme changes
  useEffect(() => {
    if (xtermRef.current) {
      xtermRef.current.options.theme = getXtermTheme(currentTheme, isDark);
    }
  }, [currentTheme, isDark]);

  const switchRuntime = (newRuntime) => {
    if (newRuntime === runtime) return;
    setRuntime(newRuntime);
    runtimeRef.current = newRuntime;
    initSession(newRuntime);
  };

  const handleRestart = () => {
    initSession(runtime);
  };

  const handleClear = () => {
    const term = xtermRef.current;
    if (term) {
      term.clear();
      term.write(promptRef.current || (runtime === "node" ? "> " : ">>> "));
      currentCommand.current = "";
    }
  };

  const handleEvalSelection = async () => {
    const selected = getSelectedText ? getSelectedText() : "";
    if (!selected || !selected.trim()) {
      const term = xtermRef.current;
      if (term) {
        term.writeln("\r\n\x1b[33m[No text selected in editor. Highlight code first.]\x1b[0m");
        term.write(promptRef.current || (runtime === "node" ? "> " : ">>> "));
      }
      return;
    }

    const term = xtermRef.current;
    if (!term) return;

    term.write(`\r\n\x1b[36m>>> # Evaluating selected code:\x1b[0m\r\n`);
    const lines = selected.split(/\r?\n/);
    lines.forEach(l => term.writeln(`\x1b[90m| ${l}\x1b[0m`));

    setIsRunning(true);
    setStatus("evaluating");

    try {
      const res = await evalReplCode({
        sessionId: activeSessionIdRef.current,
        code: selected
      });

      if (res.output) {
        const outLines = res.output.replace(/\r\n/g, "\n").split("\n");
        outLines.forEach(l => term.writeln(l));
      }

      const nextPrompt = res.prompt || (runtime === "node" ? "> " : ">>> ");
      promptRef.current = nextPrompt;
      isMultiLineRef.current = !!res.isMultiLine;
      term.write(nextPrompt);
    } catch (err) {
      term.writeln(`\x1b[31mError: ${err.message}\x1b[0m`);
      term.write(promptRef.current || (runtime === "node" ? "> " : ">>> "));
    } finally {
      setIsRunning(false);
      setStatus("ready");
    }
  };

  return (
    <div className="repl-container">
      <div className="repl-toolbar">
        <div className="repl-toolbar-left">
          <div className="repl-runtime-selector">
            <button
              className={`repl-runtime-btn python ${runtime === "python" ? "active" : ""}`}
              onClick={() => switchRuntime("python")}
              title="Python 3.12 Interactive Console"
            >
              <SiPython /> Python 3.12
            </button>
            <button
              className={`repl-runtime-btn node ${runtime === "node" ? "active" : ""}`}
              onClick={() => switchRuntime("node")}
              title="Node.js Interactive REPL"
            >
              <SiNodedotjs /> Node.js
            </button>
          </div>

          {status === "evaluating" || isRunning ? (
            <span className="repl-status-badge evaluating">
              <FaSpinner className="spin-icon" /> Evaluating
            </span>
          ) : status === "ready" ? (
            <span className="repl-status-badge ready">
              <FaCheckCircle /> {runtime.toUpperCase()} REPL Ready
            </span>
          ) : (
            <span className="repl-status-badge evaluating">
              <FaSpinner className="spin-icon" /> Starting
            </span>
          )}
        </div>

        <div className="repl-toolbar-right">
          <button
            className="repl-btn eval-sel-btn"
            onClick={handleEvalSelection}
            disabled={isRunning}
            title="Evaluate Selected Code from Editor"
            aria-label="Evaluate Selected Code"
          >
            <FaPlay />
          </button>

          <button
            className="repl-btn"
            onClick={handleRestart}
            disabled={isRunning}
            title="Restart REPL Session (Clean Environment)"
            aria-label="Restart REPL Session"
          >
            <FaRedo />
          </button>

          <button
            className="repl-btn"
            onClick={handleClear}
            title="Clear REPL Screen (Ctrl+L)"
            aria-label="Clear REPL Screen"
          >
            <FaTrash />
          </button>
        </div>
      </div>

      <div ref={terminalRef} className="repl-terminal-body" />
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from "react";
import {
  FaPlay,
  FaPause,
  FaStop,
  FaRobot,
  FaCheckCircle,
  FaTimesCircle,
  FaSpinner,
  FaFileDownload,
  FaSync,
  FaBug,
  FaShieldAlt,
  FaListUl,
  FaPlus,
  FaTrash,
  FaExternalLinkAlt,
  FaChevronDown,
  FaChevronRight,
  FaSave,
  FaDesktop,
  FaTerminal,
  FaCrosshairs,
  FaCopy,
  FaCheck,
  FaMousePointer,
  FaKeyboard,
  FaBullseye,
  FaTimes,
  FaEye,
  FaEyeSlash,
  FaCamera,
  FaChrome,
  FaEdge
} from "react-icons/fa";
import { SiPython } from "react-icons/si";
import { VscDebugRestart, VscReport, VscBeaker, VscInspect } from "react-icons/vsc";
import {
  HyperionWebDriver,
  getActivePreviewerIframe,
  getSafeIframeDocument,
  generateTestSuites,
  executeTestCase,
  generateMarkdownReport,
  generateHtmlReport,
  generateJsonReport,
  globalAgentCursor,
  getPythonSeleniumStatus,
  configurePythonSelenium,
  runPythonSeleniumSuite,
  runPythonSeleniumAgent,
  executePythonSeleniumStep,
  capturePythonSeleniumScreenshot
} from "../../services/seleniumEngine";
import { HyperionQAAgent } from "../../services/seleniumAgent";
import { globalElementInspector } from "../../services/elementInspector";
import LiveBrowser from "../LiveBrowser/LiveBrowser";
import useEditor from "../../hooks/useEditor";
import useFile from "../../hooks/useFile";
import "./SeleniumRunner.css";

export default function SeleniumRunner({ isStudioMode = false }) {
  const { openLiveBrowserTab, openFile, files: editorFiles } = useEditor();
  const { createFile, files: workspaceFiles } = useFile() || {};

  // Split-view state for side-by-side previewing inside Selenium Studio
  const [showSplitPreview, setShowSplitPreview] = useState(isStudioMode);

  // Active Sub-tab inside Selenium Runner: "tests" | "agent" | "reports"
  const [activeTab, setActiveTab] = useState("tests");

  // Testing Engine state: "python" (Python Selenium 4 backend) or "dom" (In-browser DOM simulator)
  const [engineMode, setEngineMode] = useState("python");
  const [pythonStatus, setPythonStatus] = useState(null);
  const [isPythonLoading, setIsPythonLoading] = useState(false);
  const [isHeadless, setIsHeadless] = useState(true);
  const [browserType, setBrowserType] = useState("chrome");
  const [liveScreenshot, setLiveScreenshot] = useState(null);
  const [viewScreenshotModal, setViewScreenshotModal] = useState(null);

  // Previewer Connection state
  const [isPreviewerConnected, setIsPreviewerConnected] = useState(false);
  const [previewerTitle, setPreviewerTitle] = useState("");
  const [previewerUrl, setPreviewerUrl] = useState(
    () => (window.__hyperion_previewer_url__ && window.__hyperion_previewer_url__ !== "about:blank")
      ? window.__hyperion_previewer_url__
      : "http://localhost:5174"
  );

  // Test Runner State
  const [testSuites, setTestSuites] = useState([]);
  const [selectedTests, setSelectedTests] = useState({});
  const [expandedSuites, setExpandedSuites] = useState({});
  const [expandedTests, setExpandedTests] = useState({});
  const [isRunning, setIsRunning] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [activeRunningTestId, setActiveRunningTestId] = useState(null);
  const [speed, setSpeed] = useState("normal"); // slow, normal, fast, turbo

  // Test Results & Reports State
  const [testResults, setTestResults] = useState([]);
  const [runSummary, setRunSummary] = useState({
    total: 0,
    passed: 0,
    failed: 0,
    durationMs: 0
  });

  // Autonomous Agent State
  const [isAgentRunning, setIsAgentRunning] = useState(false);
  const [agentGoal, setAgentGoal] = useState("Idle - Ready for exploration");
  const [agentProgress, setAgentProgress] = useState(0);
  const [agentThoughts, setAgentThoughts] = useState([]);
  const [agentFindings, setAgentFindings] = useState([]);
  const [agentHealthScore, setAgentHealthScore] = useState(null);

  // Custom Test Creation Modal State
  const [showCustomModal, setShowCustomModal] = useState(false);
  const [customTestName, setCustomTestName] = useState("");
  const [customTestSelector, setCustomTestSelector] = useState("button");
  const [customTestAction, setCustomTestAction] = useState("click");
  const [customTestValue, setCustomTestValue] = useState("");

  // Chromium Inspect & Select State
  const [isInspectActive, setIsInspectActive] = useState(false);
  const [selectedElement, setSelectedElement] = useState(null);
  const [copiedLocator, setCopiedLocator] = useState(null);
  const [inspectTypeInput, setInspectTypeInput] = useState("");

  // Refs for execution abort/pause control
  const driverRef = useRef(null);
  const agentRef = useRef(null);
  const abortFlagRef = useRef(false);
  const pausePromiseResolveRef = useRef(null);

  // Initialize Driver & Element Inspector Listeners
  useEffect(() => {
    driverRef.current = new HyperionWebDriver(getActivePreviewerIframe);

    const handleInspectModeChanged = (e) => {
      setIsInspectActive(!!e.detail?.active);
    };

    const handleElementSelected = (e) => {
      setSelectedElement(e.detail);
    };

    window.addEventListener("hyperion:inspect-mode-changed", handleInspectModeChanged);
    window.addEventListener("hyperion:inspect-element-selected", handleElementSelected);

    const handleInspectShortcut = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === "c" || e.key === "C")) {
        e.preventDefault();
        handleToggleInspect();
      }
    };
    window.addEventListener("keydown", handleInspectShortcut, true);

    return () => {
      window.removeEventListener("hyperion:inspect-mode-changed", handleInspectModeChanged);
      window.removeEventListener("hyperion:inspect-element-selected", handleElementSelected);
      window.removeEventListener("keydown", handleInspectShortcut, true);
    };
  }, []);

  // Poll Python Selenium backend status
  const fetchSeleniumStatus = async () => {
    try {
      const status = await getPythonSeleniumStatus();
      if (status && status.success) {
        setPythonStatus(status);
        if (status.config) {
          setIsHeadless(status.config.headless !== false);
          setBrowserType(status.config.browser || "chrome");
        }
      } else {
        setPythonStatus(null);
      }
    } catch {
      setPythonStatus(null);
    }
  };

  useEffect(() => {
    fetchSeleniumStatus();
    const interval = setInterval(fetchSeleniumStatus, 3500);
    return () => clearInterval(interval);
  }, []);

  const handleToggleHeadless = async () => {
    setIsPythonLoading(true);
    const newHeadless = !isHeadless;
    setIsHeadless(newHeadless);
    try {
      await configurePythonSelenium({ headless: newHeadless, browser: browserType });
      await fetchSeleniumStatus();
    } catch (e) {
      console.error("Failed to toggle headless:", e);
    } finally {
      setIsPythonLoading(false);
    }
  };

  const handleChangeBrowser = async (newBrowser) => {
    setIsPythonLoading(true);
    setBrowserType(newBrowser);
    try {
      await configurePythonSelenium({ browser: newBrowser, headless: isHeadless });
      await fetchSeleniumStatus();
    } catch (e) {
      console.error("Failed to switch browser:", e);
    } finally {
      setIsPythonLoading(false);
    }
  };

  const handleRestartSelenium = async () => {
    setIsPythonLoading(true);
    try {
      await configurePythonSelenium({ headless: isHeadless, browser: browserType });
      await fetchSeleniumStatus();
    } catch (e) {
      console.error("Failed to restart Selenium:", e);
    } finally {
      setIsPythonLoading(false);
    }
  };

  const handleCaptureSnapshot = async () => {
    setIsPythonLoading(true);
    try {
      const shot = await capturePythonSeleniumScreenshot();
      if (shot) {
        setLiveScreenshot(shot);
        setViewScreenshotModal(shot);
      }
    } catch (e) {
      console.error("Failed to capture snapshot:", e);
    } finally {
      setIsPythonLoading(false);
    }
  };

  // Poll for Builtin Previewer detection
  useEffect(() => {
    const checkConnection = () => {
      const iframe = getActivePreviewerIframe();
      if (iframe) {
        setIsPreviewerConnected(true);
        const doc = getSafeIframeDocument(iframe);
        setPreviewerTitle(doc?.title || iframe.title || "Live Previewer Attached");
        try {
          const href = iframe.contentWindow?.location?.href;
          if (href && href !== "about:blank" && !href.startsWith("chrome-error://")) {
            setPreviewerUrl(href);
            window.__hyperion_previewer_url__ = href;
          } else if (iframe.src && iframe.src !== "about:blank") {
            setPreviewerUrl(iframe.src);
            window.__hyperion_previewer_url__ = iframe.src;
          } else {
            // Keep existing non-blank URL or fallback to default
            setPreviewerUrl((prev) => (prev && prev !== "about:blank" ? prev : (window.__hyperion_previewer_url__ || "http://localhost:5174")));
          }
        } catch {
          if (iframe.src && iframe.src !== "about:blank") {
            setPreviewerUrl(iframe.src);
            window.__hyperion_previewer_url__ = iframe.src;
          } else {
            setPreviewerUrl((prev) => (prev && prev !== "about:blank" ? prev : (window.__hyperion_previewer_url__ || "http://localhost:5174")));
          }
        }
      } else {
        setIsPreviewerConnected(false);
        setPreviewerTitle("");
        setPreviewerUrl((prev) => (prev && prev !== "about:blank" ? prev : (window.__hyperion_previewer_url__ || "http://localhost:5174")));
      }
    };

    checkConnection();
    const interval = setInterval(checkConnection, 1500);

    const handleLoaded = () => {
      checkConnection();
      handleGenerateTests();
    };
    window.addEventListener("hyperion:previewer-loaded", handleLoaded);

    return () => {
      clearInterval(interval);
      window.removeEventListener("hyperion:previewer-loaded", handleLoaded);
    };
  }, []);

  // Generate initial test suites when previewer becomes available or on load
  const handleGenerateTests = async () => {
    const iframe = getActivePreviewerIframe();
    let doc = getSafeIframeDocument(iframe);
    if (!doc && driverRef.current) {
      doc = await driverRef.current.getOrFetchDocument();
    }
    const suites = generateTestSuites({
      previewerDoc: doc,
      files: editorFiles || workspaceFiles || []
    });
    setTestSuites(suites);

    // Default select all tests and expand first two suites
    const initialSelection = {};
    const initialExpand = {};
    suites.forEach((s, idx) => {
      if (idx < 2) initialExpand[s.id] = true;
      s.tests.forEach((t) => {
        initialSelection[t.id] = true;
      });
    });
    setSelectedTests(initialSelection);
    setExpandedSuites(initialExpand);
  };

  useEffect(() => {
    handleGenerateTests();
  }, [isPreviewerConnected]);

  // Open Previewer tab if not open
  const handleLaunchPreviewer = () => {
    const target = previewerUrl || window.__hyperion_previewer_url__ || "http://localhost:5174";
    openLiveBrowserTab(target, "Live Browser Preview");
  };

  // Toggle selection
  const toggleSelectTest = (testId) => {
    setSelectedTests((prev) => ({
      ...prev,
      [testId]: !prev[testId]
    }));
  };

  const toggleSelectSuite = (suite) => {
    const allSelected = suite.tests.every((t) => selectedTests[t.id]);
    const updated = { ...selectedTests };
    suite.tests.forEach((t) => {
      updated[t.id] = !allSelected;
    });
    setSelectedTests(updated);
  };

  // Expand / Collapse
  const toggleExpandSuite = (suiteId) => {
    setExpandedSuites((prev) => ({ ...prev, [suiteId]: !prev[suiteId] }));
  };

  const toggleExpandTest = (testId) => {
    setExpandedTests((prev) => ({ ...prev, [testId]: !prev[testId] }));
  };

  // --- Runner Execution Controls ---

  const waitIfPaused = async () => {
    if (isPaused) {
      await new Promise((resolve) => {
        pausePromiseResolveRef.current = resolve;
      });
    }
  };

  const handlePauseResume = () => {
    if (isPaused) {
      setIsPaused(false);
      if (pausePromiseResolveRef.current) {
        pausePromiseResolveRef.current();
        pausePromiseResolveRef.current = null;
      }
    } else {
      setIsPaused(true);
    }
  };

  const handleStopRun = () => {
    abortFlagRef.current = true;
    setIsRunning(false);
    setIsPaused(false);
    setActiveRunningTestId(null);
    driverRef.current?.clearHighlight();
    if (pausePromiseResolveRef.current) {
      pausePromiseResolveRef.current();
      pausePromiseResolveRef.current = null;
    }
  };

  const handleRunAll = async (onlySelected = false) => {
    if (isRunning) return;

    const testsToRun = [];
    testSuites.forEach((suite) => {
      suite.tests.forEach((test) => {
        if (!onlySelected || selectedTests[test.id]) {
          testsToRun.push(test);
        }
      });
    });

    if (testsToRun.length === 0) {
      setIsRunning(false);
      return;
    }

    const targetUrl = previewerUrl || window.__hyperion_previewer_url__ || "http://localhost:5174";

    // 1. Python Selenium 4 Backend Engine Mode
    if (engineMode === "python") {
      setIsRunning(true);
      setIsPaused(false);
      abortFlagRef.current = false;
      const startOverall = Date.now();

      try {
        const suitePayload = testsToRun.map((t) => ({
          id: t.id,
          name: t.name,
          steps: (t.steps || []).map((s) => ({
            action: s.type || s.action || "click",
            by: s.by || "css",
            selector: s.selector || "",
            value: s.value || s.script || s.expected || "",
            desc: s.desc || ""
          }))
        }));

        const response = await runPythonSeleniumSuite(targetUrl, suitePayload, "Python Selenium Suite");

        if (response && response.success) {
          const pyResults = (response.results || []).map((r) => ({
            testId: r.id,
            testName: r.name,
            status: r.status,
            durationMs: r.durationMs,
            error: r.error,
            steps: (r.steps || []).map((s) => ({
              status: s.status,
              type: s.action,
              desc: s.selector ? `${s.action}: ${s.selector}` : s.action,
              durationMs: s.durationMs,
              error: s.error
            })),
            screenshot: r.screenshot,
            consoleLogs: r.consoleLogs || []
          }));

          setTestResults(pyResults);

          const lastScreenshot = [...pyResults].reverse().find((r) => r.screenshot)?.screenshot;
          if (lastScreenshot) {
            setLiveScreenshot(lastScreenshot);
          }

          setRunSummary({
            total: response.summary?.total || testsToRun.length,
            passed: response.summary?.passed || 0,
            failed: response.summary?.failed || 0,
            durationMs: response.summary?.durationMs || (Date.now() - startOverall),
            results: pyResults,
            markdownReport: response.markdownReport
          });
        } else {
          throw new Error(response?.error || "Python Selenium execution failed");
        }
      } catch (err) {
        console.error("[SeleniumRunner] Python suite error:", err);
        alert("Selenium Python execution error: " + (err.message || "Failed to execute"));
      } finally {
        setIsRunning(false);
        setActiveRunningTestId(null);
      }
      return;
    }

    // 2. In-Browser DOM Simulator Engine Mode
    // Ensure previewer iframe exists or auto-launch previewer tab
    const existingIframe = getActivePreviewerIframe();
    if (!existingIframe && !showSplitPreview) {
      if (openLiveBrowserTab) {
        openLiveBrowserTab(targetUrl, "Live Browser Preview");
        await new Promise((r) => setTimeout(r, 600));
      }
    }

    setIsRunning(true);
    setIsPaused(false);
    abortFlagRef.current = false;

    const driver = driverRef.current;
    driver.speed = speed;
    await driver.getOrFetchDocument();

    const currentResults = [];
    let passedCount = 0;
    let failedCount = 0;
    const startOverall = Date.now();

    for (const test of testsToRun) {
      if (abortFlagRef.current) break;
      await waitIfPaused();

      setActiveRunningTestId(test.id);

      const testResult = await executeTestCase(driver, test, (liveResult) => {
        setTestResults((prev) => {
          const idx = prev.findIndex((r) => r.testId === liveResult.testId);
          if (idx >= 0) {
            const next = [...prev];
            next[idx] = { ...liveResult };
            return next;
          }
          return [...prev, liveResult];
        });
      });

      currentResults.push(testResult);
      if (testResult.status === "passed") passedCount++;
      else failedCount++;

      setTestResults([...currentResults]);
    }

    driver.clearHighlight();
    setActiveRunningTestId(null);
    setIsRunning(false);

    setRunSummary({
      total: testsToRun.length,
      passed: passedCount,
      failed: failedCount,
      durationMs: Date.now() - startOverall,
      results: currentResults
    });
  };

  // --- Autonomous Agent Controls ---

  const handleStartAgent = async (overrideTarget = null) => {
    if (isAgentRunning) return;

    setIsAgentRunning(true);
    setAgentThoughts([]);
    setAgentFindings([]);
    setAgentHealthScore(null);
    setActiveTab("agent");

    const targetUrl = previewerUrl || window.__hyperion_previewer_url__ || "http://localhost:5174";

    // 1. Python Selenium Autonomous Agent Mode
    if (engineMode === "python") {
      try {
        setAgentGoal(`Python Selenium autonomous exploration on ${targetUrl}...`);
        setAgentProgress(25);

        const res = await runPythonSeleniumAgent(targetUrl, 15);
        if (res && res.success) {
          setAgentGoal("Completed Python Selenium exploration");
          setAgentProgress(100);
          setAgentHealthScore(res.healthScore !== undefined ? res.healthScore : 90);

          if (res.thoughts) {
            const formattedThoughts = res.thoughts.map((th, i) => ({
              id: `py_th_${i}`,
              timestamp: new Date().toLocaleTimeString(),
              text: th,
              type: "action"
            }));
            setAgentThoughts(formattedThoughts);
          }

          if (res.findings) {
            const formattedFindings = res.findings.map((f, i) => ({
              id: `py_find_${i}`,
              title: f.title || "Observation",
              description: f.description || "",
              severity: f.type === "error" ? "high" : "low",
              recommendation: f.details ? JSON.stringify(f.details) : null
            }));
            setAgentFindings(formattedFindings);
          }

          if (res.screenshot) {
            setLiveScreenshot(res.screenshot);
          }
        } else {
          throw new Error(res?.error || "Agent exploration failed");
        }
      } catch (err) {
        console.error("[SeleniumRunner] Python Agent error:", err);
        setAgentGoal("Agent exploration encountered an error");
        setAgentThoughts((prev) => [
          ...prev,
          { id: `err_${Date.now()}`, timestamp: new Date().toLocaleTimeString(), text: err.message, type: "error" }
        ]);
      } finally {
        setIsAgentRunning(false);
      }
      return;
    }

    // 2. DOM Simulator Agent Mode
    const existingIframe = getActivePreviewerIframe();
    if (!existingIframe && !showSplitPreview) {
      if (openLiveBrowserTab) {
        openLiveBrowserTab(targetUrl, "Live Browser Preview");
        await new Promise((r) => setTimeout(r, 600));
      }
    }

    const agent = new HyperionQAAgent(driverRef.current);
    agentRef.current = agent;

    const targetToPrioritize = overrideTarget || selectedElement;

    try {
      const summary = await agent.runAutonomousExploration({
        speed,
        targetedElement: targetToPrioritize,
        onThought: (thought, allThoughts) => {
          setAgentThoughts([...allThoughts]);
        },
        onFinding: (finding, allFindings) => {
          setAgentFindings([...allFindings]);
        },
        onGoalUpdate: (goal) => {
          setAgentGoal(goal);
        },
        onProgress: (p) => {
          setAgentProgress(p);
        }
      });
      setAgentHealthScore(summary.healthScore);
    } catch (err) {
      console.error("[SeleniumAgent] Error running agent:", err);
    } finally {
      setIsAgentRunning(false);
    }
  };

  const handleStopAgent = () => {
    if (agentRef.current) {
      agentRef.current.abort();
    }
    setIsAgentRunning(false);
  };

  // --- Chromium Element Inspector Handlers ---

  const handleToggleInspect = () => {
    if (globalElementInspector.isActive) {
      globalElementInspector.stop(false);
    } else {
      const existingIframe = getActivePreviewerIframe();
      if (!existingIframe && !showSplitPreview) {
        setShowSplitPreview(true);
      }
      globalElementInspector.start({
        onSelect: (summary) => {
          setSelectedElement(summary);
        }
      });
    }
  };

  const handleClearSelectedElement = () => {
    setSelectedElement(null);
    globalElementInspector.clearHighlight();
  };

  const handleCopyLocator = (type, text) => {
    if (!text) return;
    try {
      navigator.clipboard.writeText(text);
      setCopiedLocator(type);
      setTimeout(() => {
        setCopiedLocator(null);
      }, 1800);
    } catch {
      // Fallback
      setCopiedLocator(type);
      setTimeout(() => setCopiedLocator(null), 1800);
    }
  };

  const handleSendAgentToElement = async () => {
    if (!selectedElement) return;
    setActiveTab("agent");

    const iframe = getActivePreviewerIframe();
    const doc = getSafeIframeDocument(iframe);
    let el = selectedElement.elementRef;
    if (!el && selectedElement.bestSelector && doc) {
      try {
        el = doc.querySelector(selectedElement.bestSelector);
      } catch {}
    }

    if (el) {
      await globalAgentCursor.moveTo(el, `Inspecting <${selectedElement.tagName}>`, { duration: 550 });
      await driverRef.current?.sleep(300);

      const thoughtText = `[User Dispatch] Guided agent cursor to inspected element: "${selectedElement.bestSelector}". Dimensions: ${selectedElement.dimensions?.width}×${selectedElement.dimensions?.height}px. Role: "${selectedElement.role}".`;
      setAgentThoughts((prev) => [
        ...prev,
        {
          id: `th_${Date.now()}`,
          timestamp: new Date().toLocaleTimeString(),
          text: thoughtText,
          type: "action"
        }
      ]);
    }
  };

  const handleSimulateClick = async () => {
    if (!selectedElement) return;

    if (engineMode === "python") {
      try {
        const res = await executePythonSeleniumStep({
          action: "click",
          by: "css",
          selector: selectedElement.bestSelector
        });
        setAgentThoughts((prev) => [
          ...prev,
          {
            id: `th_${Date.now()}`,
            timestamp: new Date().toLocaleTimeString(),
            text: `[Python Selenium] Clicked "${selectedElement.bestSelector}": ${res?.details || "Success"}`,
            type: res?.success ? "success" : "error"
          }
        ]);
      } catch (err) {
        console.error("Python click error:", err);
      }
      return;
    }

    if (!driverRef.current) return;
    const iframe = getActivePreviewerIframe();
    const doc = getSafeIframeDocument(iframe);
    let el = selectedElement.elementRef;
    if (!el && selectedElement.bestSelector && doc) {
      try {
        el = doc.querySelector(selectedElement.bestSelector);
      } catch {}
    }

    if (el) {
      await globalAgentCursor.moveTo(el, `Clicking <${selectedElement.tagName}>`, { duration: 400 });
      await driverRef.current.click(el);
      setAgentThoughts((prev) => [
        ...prev,
        {
          id: `th_${Date.now()}`,
          timestamp: new Date().toLocaleTimeString(),
          text: `[Interaction] Dispatched synthetic click to "${selectedElement.bestSelector}".`,
          type: "success"
        }
      ]);
    }
  };

  const handleSimulateSendKeys = async () => {
    if (!selectedElement || !inspectTypeInput) return;

    if (engineMode === "python") {
      try {
        const res = await executePythonSeleniumStep({
          action: "type",
          by: "css",
          selector: selectedElement.bestSelector,
          value: inspectTypeInput
        });
        setAgentThoughts((prev) => [
          ...prev,
          {
            id: `th_${Date.now()}`,
            timestamp: new Date().toLocaleTimeString(),
            text: `[Python Selenium] Typed "${inspectTypeInput}" into "${selectedElement.bestSelector}": ${res?.details || "Success"}`,
            type: res?.success ? "success" : "error"
          }
        ]);
        setInspectTypeInput("");
      } catch (err) {
        console.error("Python sendKeys error:", err);
      }
      return;
    }

    if (!driverRef.current) return;
    const iframe = getActivePreviewerIframe();
    const doc = getSafeIframeDocument(iframe);
    let el = selectedElement.elementRef;
    if (!el && selectedElement.bestSelector && doc) {
      try {
        el = doc.querySelector(selectedElement.bestSelector);
      } catch {}
    }

    if (el) {
      await globalAgentCursor.moveTo(el, `Typing text...`, { duration: 400 });
      await driverRef.current.sendKeys(el, inspectTypeInput);
      setAgentThoughts((prev) => [
        ...prev,
        {
          id: `th_${Date.now()}`,
          timestamp: new Date().toLocaleTimeString(),
          text: `[Interaction] Typed "${inspectTypeInput}" into "${selectedElement.bestSelector}".`,
          type: "success"
        }
      ]);
      setInspectTypeInput("");
    }
  };

  const handleTargetForAgent = () => {
    if (!selectedElement) return;
    setActiveTab("agent");
    handleStartAgent(selectedElement);
  };

  const handleAddElementToCustomTest = () => {
    if (!selectedElement) return;
    const tag = selectedElement.tagName.toLowerCase();
    setCustomTestName(`Verify ${tag} (${selectedElement.id ? '#' + selectedElement.id : selectedElement.bestSelector})`);
    setCustomTestSelector(selectedElement.bestSelector);
    if (["input", "textarea"].includes(tag)) {
      setCustomTestAction("sendKeys");
      setCustomTestValue("Sample input");
    } else if (["button", "a"].includes(tag) || selectedElement.role === "button") {
      setCustomTestAction("click");
      setCustomTestValue("");
    } else {
      setCustomTestAction("assertVisible");
      setCustomTestValue("");
    }
    setActiveTab("tests");
    setShowCustomModal(true);
  };

  // --- Add Custom Test Case ---
  const handleAddCustomTest = () => {
    if (!customTestName.trim()) return;

    const newTest = {
      id: `custom_${Date.now()}`,
      name: customTestName,
      steps: [
        {
          type: "waitForElement",
          selector: customTestSelector,
          condition: "visible",
          desc: `Wait for element: ${customTestSelector}`
        },
        {
          type: customTestAction,
          selector: customTestSelector,
          value: customTestValue,
          expected: customTestValue,
          desc: `${customTestAction} on ${customTestSelector}`
        },
        {
          type: "takeSnapshot",
          desc: "Capture result snapshot"
        }
      ]
    };

    setTestSuites((prev) => {
      let customSuite = prev.find((s) => s.id === "suite_custom");
      if (!customSuite) {
        customSuite = {
          id: "suite_custom",
          name: "✨ Custom Selenium Tests",
          description: "User-defined interactive test cases and assertions.",
          tests: [newTest]
        };
        return [...prev, customSuite];
      } else {
        return prev.map((s) =>
          s.id === "suite_custom" ? { ...s, tests: [...s.tests, newTest] } : s
        );
      }
    });

    setSelectedTests((prev) => ({ ...prev, [newTest.id]: true }));
    setShowCustomModal(false);
    setCustomTestName("");
  };

  // --- Reports Export Handlers ---

  const handleDownloadHtml = () => {
    const html = generateHtmlReport(
      { ...runSummary, results: testResults },
      testSuites
    );
    const blob = new Blob([html], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `selenium_test_report_${Date.now()}.html`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleDownloadMarkdown = () => {
    const md = runSummary.markdownReport || generateMarkdownReport(
      { ...runSummary, results: testResults },
      testSuites
    );
    const blob = new Blob([md], { type: "text/markdown" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "TEST_REPORT.md";
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleSaveToWorkspace = async () => {
    const md = runSummary.markdownReport || generateMarkdownReport(
      { ...runSummary, results: testResults },
      testSuites
    );
    if (createFile) {
      try {
        await createFile("TEST_REPORT.md");
        // Also open as tab in editor
        openFile?.({
          name: "TEST_REPORT.md",
          path: "TEST_REPORT.md",
          content: md,
          language: "markdown"
        });
        alert("Saved TEST_REPORT.md directly to workspace root!");
      } catch (err) {
        handleDownloadMarkdown();
      }
    } else {
      handleDownloadMarkdown();
    }
  };

  return (
    <div className={`selenium-runner-root ${showSplitPreview ? "has-split" : ""}`}>
      <div className="selenium-runner-container">
      {/* Python Selenium 4 Engine Bar */}
      <div className="selenium-engine-bar">
        <div className="engine-identity">
          <div className="engine-icon-wrap">
            <SiPython className="python-brand-icon" />
          </div>
          <div className="engine-info">
            <div className="engine-title-row">
              <span className="engine-title">Selenium 4 WebDriver</span>
              <span className={`engine-badge ${pythonStatus?.success ? "online" : "offline"}`}>
                <span className="status-dot" />
                {pythonStatus?.success ? "ONLINE" : "OFFLINE"}
              </span>
            </div>
            <span className="engine-subtext">
              {pythonStatus?.success
                ? `Python ${pythonStatus.python_version || "3.12"} • ${browserType.toUpperCase()} • Port 5006`
                : "Python Selenium backend on port 5006"}
            </span>
          </div>
        </div>

        <div className="engine-controls">
          {/* Mode Selector */}
          <select
            className="engine-mode-select"
            value={engineMode}
            onChange={(e) => setEngineMode(e.target.value)}
            title="Switch active test execution engine"
          >
            <option value="python">🐍 Python Selenium 4 (Native)</option>
            <option value="dom">🌐 In-Browser Simulator (DOM)</option>
          </select>

          {engineMode === "python" && (
            <>
              {/* Browser Selector */}
              <div className="engine-browser-toggle">
                <button
                  className={`engine-mini-btn ${browserType === "chrome" ? "active" : ""}`}
                  onClick={() => handleChangeBrowser("chrome")}
                  disabled={isPythonLoading}
                  title="Use Google Chrome WebDriver"
                >
                  <FaChrome /> Chrome
                </button>
                <button
                  className={`engine-mini-btn ${browserType === "edge" ? "active" : ""}`}
                  onClick={() => handleChangeBrowser("edge")}
                  disabled={isPythonLoading}
                  title="Use Microsoft Edge WebDriver"
                >
                  <FaEdge /> Edge
                </button>
              </div>

              {/* Headless Toggle */}
              <button
                className={`engine-toggle-btn ${isHeadless ? "headless" : "visible"}`}
                onClick={handleToggleHeadless}
                disabled={isPythonLoading}
                title={isHeadless ? "Switch to Visible Browser Window" : "Switch to Headless Background Execution"}
              >
                {isHeadless ? <FaEyeSlash /> : <FaEye />}
                <span>{isHeadless ? "Headless" : "Visible"}</span>
              </button>

              {/* Instant Snapshot */}
              <button
                className="engine-icon-btn"
                onClick={handleCaptureSnapshot}
                title="Capture instant screenshot from Selenium WebDriver"
                disabled={isPythonLoading}
              >
                <FaCamera />
              </button>

              {/* Restart Driver */}
              <button
                className="engine-icon-btn restart"
                onClick={handleRestartSelenium}
                title="Restart Selenium session"
                disabled={isPythonLoading}
              >
                <VscDebugRestart className={isPythonLoading ? "spin-icon" : ""} />
              </button>
            </>
          )}
        </div>
      </div>

      {/* Target Previewer Connection Header */}
      <div className="selenium-target-bar">
        <div className="target-indicator-group">
          <span
            className={`connection-dot ${isPreviewerConnected ? "connected" : "disconnected"}`}
          />
          <div className="target-text">
            <span className="target-state">
              {isPreviewerConnected ? "BUILTIN PREVIEWER LINKED" : "PREVIEWER DETACHED"}
            </span>
            <span className="target-url" title={previewerUrl}>
              {isPreviewerConnected
                ? previewerTitle || previewerUrl
                : "No active preview iframe detected"}
            </span>
          </div>
        </div>

        <div className="target-actions-group">
          <button
            className={`selenium-inspect-btn ${isInspectActive ? "active" : ""}`}
            onClick={handleToggleInspect}
            title={isInspectActive ? "Exit Element Inspector (Esc)" : "Inspect & Select Element in Preview (Ctrl+Shift+C)"}
          >
            <FaCrosshairs className={isInspectActive ? "spin-pulse" : ""} /> {isInspectActive ? "Inspecting..." : "Inspect"}
          </button>

          {!isPreviewerConnected ? (
            <button
              className="selenium-launch-btn"
              onClick={handleLaunchPreviewer}
              title="Launch previewer tab in editor"
            >
              <FaExternalLinkAlt /> Launch Previewer
            </button>
          ) : (
            <button
              className="selenium-bridge-btn"
              onClick={() => {
                window.dispatchEvent(new CustomEvent("hyperion:enable-automation-bridge"));
                handleGenerateTests();
              }}
              title="Activate / Sync Same-Origin Automation Bridge for live DOM access"
            >
              ⚡ Sync Bridge
            </button>
          )}

          <button
            className={`selenium-split-toggle-btn ${showSplitPreview ? "active" : ""}`}
            onClick={() => setShowSplitPreview(!showSplitPreview)}
            title="Toggle Side-by-Side Live Preview Pane"
          >
            <FaDesktop /> {showSplitPreview ? "Hide Preview" : "Split Preview"}
          </button>
        </div>
      </div>

      {/* Chromium DevTools-Style Inspect Active Banner */}
      {isInspectActive && (
        <div className="inspect-active-banner">
          <div className="inspect-banner-info">
            <FaCrosshairs className="inspect-banner-crosshair" />
            <span>
              <strong>Inspect Mode Active:</strong> Hover over any element in the preview to highlight. Click to select. Press <kbd>Esc</kbd> to exit.
            </span>
          </div>
          <button
            className="inspect-banner-cancel-btn"
            onClick={() => globalElementInspector.stop(true)}
            title="Exit inspection mode without selecting"
          >
            Cancel (Esc)
          </button>
        </div>
      )}

      {/* Chromium-Style Selected Element Inspector Card */}
      {selectedElement && (
        <div className="selected-element-card">
          <div className="selected-element-header">
            <div className="element-badges">
              <span className="badge tag-badge">&lt;{selectedElement.tagName}&gt;</span>
              {selectedElement.id && (
                <span className="badge id-badge" title={`ID: ${selectedElement.id}`}>
                  #{selectedElement.id}
                </span>
              )}
              {selectedElement.className && (
                <span className="badge class-badge" title={`Classes: ${selectedElement.className}`}>
                  .{selectedElement.className.trim().split(/\s+/)[0]}
                </span>
              )}
              {selectedElement.dimensions && (
                <span className="badge dim-badge">
                  {selectedElement.dimensions.width} × {selectedElement.dimensions.height} px
                </span>
              )}
              {selectedElement.role && (
                <span className="badge role-badge" title="ARIA Accessibility Role">
                  role: <strong>{selectedElement.role}</strong>
                </span>
              )}
            </div>

            <div className="element-card-actions">
              <button
                className="card-action-btn primary"
                onClick={handleTargetForAgent}
                title="Focus Autonomous QA Agent on this component"
              >
                <FaBullseye /> Target for Agent
              </button>
              <button
                className="card-action-btn close"
                onClick={handleClearSelectedElement}
                title="Deselect inspected element"
              >
                <FaTimes />
              </button>
            </div>
          </div>

          {/* Quick Action Simulation Bar */}
          <div className="element-quick-sim-bar">
            <button
              className="sim-action-btn glide"
              onClick={handleSendAgentToElement}
              title="Glide AI cursor to element and stream reasoning thought"
            >
              <FaRobot /> Send Agent Here
            </button>

            <button
              className="sim-action-btn click"
              onClick={handleSimulateClick}
              title="Dispatch live synthetic click to this element"
            >
              <FaMousePointer /> Click
            </button>

            <div className="sim-type-group">
              <input
                type="text"
                className="sim-type-input"
                value={inspectTypeInput}
                onChange={(e) => setInspectTypeInput(e.target.value)}
                placeholder="Type to send keys..."
                onKeyDown={(e) => e.key === "Enter" && handleSimulateSendKeys()}
              />
              <button
                className="sim-action-btn type"
                onClick={handleSimulateSendKeys}
                disabled={!inspectTypeInput.trim()}
                title="Dispatch keystrokes into this element"
              >
                <FaKeyboard /> Send
              </button>
            </div>

            <button
              className="sim-action-btn add-step"
              onClick={handleAddElementToCustomTest}
              title="Pre-fill custom test step with this element"
            >
              <FaPlus /> Add Test Step
            </button>
          </div>

          {/* Copyable Locators Table */}
          <div className="element-locators-table">
            <div className="locator-row">
              <span className="locator-label">CSS:</span>
              <code className="locator-code" title={selectedElement.bestSelector}>
                {selectedElement.bestSelector}
              </code>
              <button
                className="copy-locator-btn"
                onClick={() => handleCopyLocator("css", selectedElement.bestSelector)}
                title="Copy CSS Selector"
              >
                {copiedLocator === "css" ? <FaCheck className="copied" /> : <FaCopy />}
              </button>
            </div>

            <div className="locator-row">
              <span className="locator-label">XPath:</span>
              <code className="locator-code" title={selectedElement.xpath}>
                {selectedElement.xpath}
              </code>
              <button
                className="copy-locator-btn"
                onClick={() => handleCopyLocator("xpath", selectedElement.xpath)}
                title="Copy XPath Expression"
              >
                {copiedLocator === "xpath" ? <FaCheck className="copied" /> : <FaCopy />}
              </button>
            </div>

            <div className="locator-row">
              <span className="locator-label">Testing Library:</span>
              <code className="locator-code" title={selectedElement.testingLibrary}>
                {selectedElement.testingLibrary}
              </code>
              <button
                className="copy-locator-btn"
                onClick={() => handleCopyLocator("testingLibrary", selectedElement.testingLibrary)}
                title="Copy Testing Library Locator"
              >
                {copiedLocator === "testingLibrary" ? <FaCheck className="copied" /> : <FaCopy />}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Sub-Tabs */}
      <div className="selenium-nav-tabs">
        <button
          className={`selenium-tab-btn ${activeTab === "tests" ? "active" : ""}`}
          onClick={() => setActiveTab("tests")}
        >
          <VscBeaker /> Tests ({testSuites.reduce((acc, s) => acc + s.tests.length, 0)})
        </button>
        <button
          className={`selenium-tab-btn ${activeTab === "agent" ? "active" : ""}`}
          onClick={() => setActiveTab("agent")}
        >
          <FaRobot /> Agentic QA {isAgentRunning && <FaSpinner className="spin-icon" />}
        </button>
        <button
          className={`selenium-tab-btn ${activeTab === "reports" ? "active" : ""}`}
          onClick={() => setActiveTab("reports")}
        >
          <VscReport /> Reports & Logs
        </button>
      </div>

      {/* TAB 1: TEST AUTOMATION */}
      {activeTab === "tests" && (
        <div className="selenium-tab-content">
          {/* Action Toolbar */}
          <div className="selenium-toolbar">
            <div className="btn-group">
              <button
                className="toolbar-btn primary"
                onClick={() => handleRunAll(false)}
                disabled={isRunning}
                title="Run All Test Suites"
              >
                {isRunning ? <FaSpinner className="spin-icon" /> : <FaPlay />} Run All
              </button>

              <button
                className="toolbar-btn secondary"
                onClick={() => handleRunAll(true)}
                disabled={isRunning}
                title="Run Selected Tests"
              >
                <FaListUl /> Run Selected
              </button>

              {isRunning && (
                <>
                  <button
                    className="toolbar-btn control"
                    onClick={handlePauseResume}
                    title={isPaused ? "Resume Execution" : "Pause Execution"}
                  >
                    {isPaused ? <FaPlay /> : <FaPause />}
                  </button>
                  <button
                    className="toolbar-btn stop"
                    onClick={handleStopRun}
                    title="Stop Execution"
                  >
                    <FaStop />
                  </button>
                </>
              )}
            </div>

            <div className="toolbar-aux">
              <select
                className="speed-selector"
                value={speed}
                onChange={(e) => setSpeed(e.target.value)}
                title="Execution delay between steps"
              >
                <option value="slow">Slow (1200ms)</option>
                <option value="normal">Normal (450ms)</option>
                <option value="fast">Fast (120ms)</option>
                <option value="turbo">Turbo (0ms)</option>
              </select>

              <button
                className="toolbar-btn icon-only"
                onClick={handleGenerateTests}
                title="Rescan Previewer DOM and Regenerate Tests"
              >
                <FaSync />
              </button>

              <button
                className="toolbar-btn icon-only"
                onClick={() => setShowCustomModal(true)}
                title="Add Custom Test Case"
              >
                <FaPlus />
              </button>
            </div>
          </div>

          {/* Test Suites Tree */}
          <div className="suites-list">
            {testSuites.map((suite) => {
              const isExpanded = expandedSuites[suite.id];
              const isSuiteAllSelected = suite.tests.every(
                (t) => selectedTests[t.id]
              );

              return (
                <div className="suite-item" key={suite.id}>
                  <div className="suite-header">
                    <span
                      className="suite-chevron"
                      onClick={() => toggleExpandSuite(suite.id)}
                    >
                      {isExpanded ? <FaChevronDown /> : <FaChevronRight />}
                    </span>

                    <input
                      type="checkbox"
                      className="suite-checkbox"
                      checked={isSuiteAllSelected}
                      onChange={() => toggleSelectSuite(suite)}
                    />

                    <span
                      className="suite-name"
                      onClick={() => toggleExpandSuite(suite.id)}
                    >
                      {suite.name}
                    </span>

                    <span className="suite-count">({suite.tests.length})</span>
                  </div>

                  {isExpanded && (
                    <div className="suite-tests-list">
                      {suite.tests.map((test) => {
                        const isSelected = !!selectedTests[test.id];
                        const testResult = testResults.find(
                          (r) => r.testId === test.id
                        );
                        const isCurrentRunning = activeRunningTestId === test.id;
                        const isTestExpanded = expandedTests[test.id];

                        return (
                          <div
                            className={`test-item ${isCurrentRunning ? "running" : ""} ${testResult?.status || ""}`}
                            key={test.id}
                          >
                            <div className="test-header">
                              <input
                                type="checkbox"
                                checked={isSelected}
                                onChange={() => toggleSelectTest(test.id)}
                              />

                              <span
                                className="test-status-icon"
                                onClick={() => toggleExpandTest(test.id)}
                              >
                                {isCurrentRunning ? (
                                  <FaSpinner className="spin-icon running-color" />
                                ) : testResult?.status === "passed" ? (
                                  <FaCheckCircle className="pass-color" />
                                ) : testResult?.status === "failed" ? (
                                  <FaTimesCircle className="fail-color" />
                                ) : (
                                  <span className="pending-dot" />
                                )}
                              </span>

                              <span
                                className="test-name"
                                onClick={() => toggleExpandTest(test.id)}
                              >
                                {test.name}
                              </span>

                              {testResult?.durationMs !== undefined && (
                                <span className="test-duration">
                                  {testResult.durationMs}ms
                                </span>
                              )}
                            </div>

                            {/* Expanded Test Steps */}
                            {isTestExpanded && (
                              <div className="test-steps-container">
                                {test.steps.map((step, idx) => {
                                  const stepResult = testResult?.steps?.[idx];
                                  return (
                                    <div
                                      className={`step-row ${stepResult?.status || ""}`}
                                      key={idx}
                                    >
                                      <span className="step-idx">{idx + 1}.</span>
                                      <span className="step-type">[{step.type}]</span>
                                      <span className="step-desc">
                                        {step.desc || step.selector}
                                      </span>
                                      {stepResult?.durationMs !== undefined && (
                                        <span className="step-ms">
                                          {stepResult.durationMs}ms
                                        </span>
                                      )}
                                      {stepResult?.error && (
                                        <div className="step-error-msg">
                                          {stepResult.error}
                                        </div>
                                      )}
                                    </div>
                                  );
                                })}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* TAB 2: AGENTIC TESTING */}
      {activeTab === "agent" && (
        <div className="selenium-tab-content agent-panel">
          {/* Agent Control Header */}
          <div className="agent-hero-card">
            <div className="agent-hero-info">
              <FaRobot className="agent-avatar" />
              <div>
                <h4 className="agent-title">Autonomous QA Agent</h4>
                <p className="agent-desc">
                  Autonomous exploratory tester that dynamically inspects DOM,
                  formulates testing goals, discovers UI defects, and validates accessibility.
                </p>
              </div>
            </div>

            <div className="agent-actions">
              {!isAgentRunning ? (
                <button
                  className="agent-start-btn"
                  onClick={handleStartAgent}
                >
                  <FaPlay /> Start Agentic Test
                </button>
              ) : (
                <button className="agent-stop-btn" onClick={handleStopAgent}>
                  <FaStop /> Abort Agent
                </button>
              )}
            </div>
          </div>

          {/* Active Goal & Progress Bar */}
          <div className="agent-goal-card">
            <div className="agent-goal-header">
              <span className="goal-label">CURRENT GOAL:</span>
              <span className="goal-text">{agentGoal}</span>
              <span className="goal-pct">{agentProgress}%</span>
            </div>
            <div className="agent-progress-track">
              <div
                className="agent-progress-fill"
                style={{ width: `${agentProgress}%` }}
              />
            </div>
          </div>

          {/* Health Score Card if complete */}
          {agentHealthScore !== null && (
            <div className="health-score-card">
              <div className="score-circle">
                <span className="score-number">{agentHealthScore}</span>
                <span className="score-total">/100</span>
              </div>
              <div className="score-summary">
                <h4 className="score-title">
                  {agentHealthScore >= 90
                    ? "Application Status: Excellent"
                    : agentHealthScore >= 70
                    ? "Application Status: Moderate"
                    : "Application Status: Attention Needed"}
                </h4>
                <p className="score-stats">
                  {agentFindings.length} autonomous findings discovered across{" "}
                  {agentThoughts.length} execution observations.
                </p>
              </div>
            </div>
          )}

          {/* Agent Thoughts Stream */}
          <div className="agent-stream-section">
            <div className="section-title">
              <FaTerminal /> Live Reasoning Stream
            </div>
            <div className="thoughts-terminal">
              {agentThoughts.length === 0 ? (
                <div className="thoughts-empty">
                  Agent is idle. Click "Start Agentic Test" to begin exploratory testing.
                </div>
              ) : (
                agentThoughts.map((th) => (
                  <div className={`thought-line ${th.type}`} key={th.id}>
                    <span className="thought-time">[{th.timestamp}]</span>
                    <span className="thought-text">{th.text}</span>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Agent Discovered Findings */}
          <div className="agent-findings-section">
            <div className="section-title">
              <FaBug /> Discovered Findings & Audit ({agentFindings.length})
            </div>
            <div className="findings-list">
              {agentFindings.length === 0 ? (
                <div className="findings-empty">No flaws or issues discovered yet.</div>
              ) : (
                agentFindings.map((f) => (
                  <div className={`finding-card ${f.severity}`} key={f.id}>
                    <div className="finding-top">
                      <span className={`finding-badge ${f.severity}`}>
                        {f.severity.toUpperCase()}
                      </span>
                      <span className="finding-title">{f.title}</span>
                    </div>
                    <p className="finding-desc">{f.description}</p>
                    {f.recommendation && (
                      <div className="finding-rec">
                        <strong>Fix:</strong> {f.recommendation}
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* TAB 3: REPORTS & LOGS */}
      {activeTab === "reports" && (
        <div className="selenium-tab-content reports-panel">
          {/* Executive Summary Metrics */}
          <div className="reports-metrics-row">
            <div className="report-metric-card">
              <span className="metric-val">{runSummary.total}</span>
              <span className="metric-lbl">Total Tests</span>
            </div>
            <div className="report-metric-card pass">
              <span className="metric-val">{runSummary.passed}</span>
              <span className="metric-lbl">Passed</span>
            </div>
            <div className="report-metric-card fail">
              <span className="metric-val">{runSummary.failed}</span>
              <span className="metric-lbl">Failed</span>
            </div>
            <div className="report-metric-card time">
              <span className="metric-val">
                {(runSummary.durationMs / 1000).toFixed(1)}s
              </span>
              <span className="metric-lbl">Duration</span>
            </div>
          </div>

          {/* Export Action Controls */}
          <div className="reports-actions-box">
            <button
              className="export-btn html"
              onClick={handleDownloadHtml}
              title="Download standalone HTML report with interactive log viewer"
            >
              <FaFileDownload /> Export HTML Report
            </button>

            <button
              className="export-btn md"
              onClick={handleDownloadMarkdown}
              title="Download TEST_REPORT.md for GitHub"
            >
              <FaFileDownload /> Export Markdown
            </button>

            <button
              className="export-btn save"
              onClick={handleSaveToWorkspace}
              title="Save TEST_REPORT.md directly into project root workspace"
            >
              <FaSave /> Save to Workspace
            </button>
          </div>

          {/* Results Breakdown */}
          <div className="results-breakdown-section">
            <div className="section-title">Test Results Breakdown</div>
            {testResults.length === 0 ? (
              <div className="results-empty">
                No test results recorded yet. Run tests from the "Tests" tab to compile a report.
              </div>
            ) : (
              <div className="results-list">
                {testResults.map((res) => (
                  <div
                    className={`result-item-card ${res.status}`}
                    key={res.testId}
                  >
                    <div className="result-item-header">
                      <span className="result-title">{res.testName}</span>
                      <span className={`result-tag ${res.status}`}>
                        {res.status.toUpperCase()}
                      </span>
                    </div>
                    <div className="result-item-meta">
                      Duration: {res.durationMs}ms | Steps:{" "}
                      {res.steps.filter((s) => s.status === "passed").length} /{" "}
                      {res.steps.length} passed
                    </div>
                    {res.error && (
                      <div className="result-error-box">
                        <strong>Error:</strong> {res.error}
                      </div>
                    )}
                    {res.screenshot && (
                      <div className="result-screenshot-row">
                        <div
                          className="result-thumb-wrapper"
                          onClick={() => setViewScreenshotModal(res.screenshot)}
                          title="Click to expand Selenium browser screenshot"
                        >
                          <img src={res.screenshot} alt="Screenshot" className="result-screenshot-thumb" />
                          <span className="thumb-hover-overlay"><FaCamera /> Expand</span>
                        </div>
                      </div>
                    )}
                    {res.consoleLogs && res.consoleLogs.length > 0 && (
                      <div className="result-logs-box">
                        <span className="logs-header"><FaTerminal /> Console Logs ({res.consoleLogs.length}):</span>
                        {res.consoleLogs.slice(0, 3).map((log, li) => (
                          <div className={`log-entry ${log.level?.toLowerCase() || ""}`} key={li}>
                            [{log.level}] {log.message}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Custom Test Creation Modal */}
      {showCustomModal && (
        <div className="modal-backdrop">
          <div className="custom-test-modal">
            <h4 className="modal-title">Create Custom Selenium Test</h4>
            <div className="modal-form">
              <label>Test Case Name</label>
              <input
                type="text"
                value={customTestName}
                onChange={(e) => setCustomTestName(e.target.value)}
                placeholder="e.g. Verify Login Button Click"
              />

              <label>Target CSS Selector / By</label>
              <input
                type="text"
                value={customTestSelector}
                onChange={(e) => setCustomTestSelector(e.target.value)}
                placeholder="e.g. #login-btn or button.primary"
              />

              <label>Action</label>
              <select
                value={customTestAction}
                onChange={(e) => setCustomTestAction(e.target.value)}
              >
                <option value="click">click</option>
                <option value="sendKeys">sendKeys (type text)</option>
                <option value="clear">clear</option>
                <option value="assertText">assertText</option>
                <option value="assertVisible">assertVisible</option>
              </select>

              {(customTestAction === "sendKeys" ||
                customTestAction === "assertText") && (
                <>
                  <label>Value / Expected Text</label>
                  <input
                    type="text"
                    value={customTestValue}
                    onChange={(e) => setCustomTestValue(e.target.value)}
                    placeholder="Value to type or expect"
                  />
                </>
              )}
            </div>

            <div className="modal-actions">
              <button
                className="modal-cancel-btn"
                onClick={() => setShowCustomModal(false)}
              >
                Cancel
              </button>
              <button
                className="modal-submit-btn"
                onClick={handleAddCustomTest}
                disabled={!customTestName.trim()}
              >
                Add Test
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Live Selenium Screenshot Modal */}
      {viewScreenshotModal && (
        <div className="screenshot-modal-backdrop" onClick={() => setViewScreenshotModal(null)}>
          <div className="screenshot-modal-card" onClick={(e) => e.stopPropagation()}>
            <div className="screenshot-modal-header">
              <span className="screenshot-modal-title">
                <FaCamera /> Selenium WebDriver Capture
              </span>
              <button
                className="screenshot-modal-close"
                onClick={() => setViewScreenshotModal(null)}
              >
                <FaTimes />
              </button>
            </div>
            <div className="screenshot-modal-body">
              <img src={viewScreenshotModal} alt="Selenium Viewport" className="screenshot-full-img" />
            </div>
          </div>
        </div>
      )}
      </div>
      {showSplitPreview && (
        <div className="selenium-runner-preview-pane">
          <LiveBrowser
            initialUrl={
              (previewerUrl && previewerUrl !== "about:blank")
                ? previewerUrl
                : ((window.__hyperion_previewer_url__ && window.__hyperion_previewer_url__ !== "about:blank")
                    ? window.__hyperion_previewer_url__
                    : "http://localhost:5174")
            }
            title="Live Automation Target Preview"
            onClose={() => setShowSplitPreview(false)}
          />
        </div>
      )}
    </div>
  );
}

