        </div>

        <div
          className="term-dropdown-item"
          onClick={() => handleAction(() => createTerminal("python"))}
        >
          <span className="term-item-icon"><FaPython /></span>
          <span className="term-item-label">Python Interactive Terminal</span>
        </div>

        <div
          className="term-dropdown-item"
          onClick={() => handleAction(() => createTerminal("agent"))}
        >
          <span className="term-item-icon"><FaRobot /></span>
          <span className="term-item-label">Agent Host (Local)</span>
        </div>

        {/* Submenu for Split Terminal with Profile */}
        <div
          className="term-dropdown-item has-submenu"
          onMouseEnter={() => setHoverSubmenu(true)}
          onMouseLeave={() => setHoverSubmenu(false)}
        >
          <span className="term-item-icon"><FaColumns /></span>
          <span className="term-item-label">Split Terminal with Profile</span>
          <FaChevronRight className="term-submenu-arrow" />

          {hoverSubmenu && (
            <div className={`term-sub-dropdown-menu ${coords.openSubmenuLeft ? "open-left" : ""}`}>
              <div
                className="term-dropdown-item"
                onClick={() => handleAction(() => splitTerminal("powershell"))}
              >
                <span className="term-item-icon"><FaTerminal /></span>
                <span className="term-item-label">PowerShell</span>
              </div>
              <div
                className="term-dropdown-item"
                onClick={() => handleAction(() => splitTerminal("bash"))}
              >
                <span className="term-item-icon"><FaTerminal /></span>
                <span className="term-item-label">Git Bash</span>
              </div>
              <div
                className="term-dropdown-item"
                onClick={() => handleAction(() => splitTerminal("cmd"))}
              >
                <span className="term-item-icon"><FaTerminal /></span>
                <span className="term-item-label">Command Prompt</span>
              </div>
              <div
                className="term-dropdown-item"
                onClick={() => handleAction(() => splitTerminal("node"))}
              >
                <span className="term-item-icon"><FaNodeJs /></span>
                <span className="term-item-label">JavaScript Debug Terminal</span>
              </div>
              <div
                className="term-dropdown-item"
                onClick={() => handleAction(() => splitTerminal("python"))}
              >
                <span className="term-item-icon"><FaPython /></span>
                <span className="term-item-label">Python Interactive Terminal</span>
              </div>
              <div
                className="term-dropdown-item"
                onClick={() => handleAction(() => splitTerminal("cypher"))}
              >
                <span className="term-item-icon cypher-icon"><FaShieldAlt /></span>
                <span className="term-item-label">Cypher Security Terminal</span>
              </div>
            </div>
          )}
        </div>

        <div className="term-dropdown-divider" />

        {/* Configuration */}
        <div
          className="term-dropdown-item"
          onClick={handleOpenSettings}
        >
          <span className="term-item-icon"><FaCog /></span>
          <span className="term-item-label">Configure Terminal Settings</span>
        </div>

        <div
          className="term-dropdown-item"
          onClick={() => {
            setShowProfileModal(true);
            onClose();
          }}
        >
          <span className="term-item-icon"><FaTerminal /></span>
          <span className="term-item-label">Select Default Profile</span>
        </div>

        <div className="term-dropdown-divider" />

        {/* Tasks */}
        <div
          className="term-dropdown-item"
          onClick={() => handleAction(() => {
            if (openTaskPicker) openTaskPicker();
            else if (runTask) runTask("npm test");
          })}
        >
          <span className="term-item-icon"><FaTasks /></span>
          <span className="term-item-label">Run Task...</span>
        </div>

        <div
          className="term-dropdown-item"
          onClick={() => handleAction(() => configureTasks && configureTasks())}
        >
          <span className="term-item-icon"><FaCode /></span>
          <span className="term-item-label">Configure Tasks...</span>
        </div>
      </div>

      {/* Select Default Profile Modal */}
      {showProfileModal && (
        <div className="term-modal-backdrop" onClick={() => setShowProfileModal(false)}>
          <div className="term-modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="term-modal-header">
              <h3>Select Default Terminal Profile</h3>
              <p>Choose the default shell profile used when opening new terminals:</p>
            </div>
            <div className="term-profile-options">
              {[
                { id: "powershell", name: "PowerShell", desc: "Windows PowerShell / pwsh shell" },
                { id: "bash", name: "Git Bash", desc: "GNU Bash MINGW64 environment" },
                { id: "cmd", name: "Command Prompt", desc: "Windows cmd.exe environment" },
                { id: "cypher", name: "Cypher Security Terminal", desc: "AI security intelligence & audit CLI" }
              ].map((opt) => (
                <div
                  key={opt.id}
                  className={`term-profile-opt-item ${defaultProfile === opt.id ? "active" : ""}`}
                  onClick={() => {
                    if (setDefaultProfile) setDefaultProfile(opt.id);
                    setShowProfileModal(false);
                  }}
                >
                  <div className="term-profile-opt-info">
                    <span className="term-profile-opt-title">{opt.name}</span>
                    <span className="term-profile-opt-desc">{opt.desc}</span>
                  </div>
                  {defaultProfile === opt.id && <FaCheck className="term-check-icon" />}
                </div>
              ))}
            </div>
            <div className="term-modal-footer">
              <button className="term-modal-btn" onClick={() => setShowProfileModal(false)}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );

  return createPortal(menuElement, document.body);
}

import React, { useState, useEffect } from "react";
import { BsFillPeopleFill } from "react-icons/bs";
import { PiSpeedometerFill } from "react-icons/pi";
import { FaUserSecret, FaPlay, FaSpinner, FaCheckCircle, FaExclamationTriangle, FaShieldAlt, FaRedo } from "react-icons/fa";
import { runLoadTest, runSpeedTest, runSecretTest, getTestingStatus } from "../../services/testingService";
import "./TestingSuite.css";

export default function TestingSuite({ mode = "all", initialTab = "load" }) {
  // If mode is specific ("load", "speed", "secret"), lock to that mode; otherwise use initialTab
  const [activeTab, setActiveTab] = useState(mode !== "all" ? mode : initialTab);
  const [engineStatus, setEngineStatus] = useState(null);

  // Load Test Form State
  const [loadUrl, setLoadUrl] = useState(
    typeof window !== "undefined" ? window.location.origin : "http://localhost:5173"
  );
  const [loadConnections, setLoadConnections] = useState(10);
  const [loadDuration, setLoadDuration] = useState(5);
  const [loadPipelining, setLoadPipelining] = useState(1);
  const [loadLoading, setLoadLoading] = useState(false);
  const [loadResults, setLoadResults] = useState(null);
  const [loadError, setLoadError] = useState(null);

  // Speed Test Form State
  const [speedUrl, setSpeedUrl] = useState(
    typeof window !== "undefined" ? window.location.origin : "http://localhost:5173"
  );
  const [speedDevice, setSpeedDevice] = useState("desktop");
  const [speedLoading, setSpeedLoading] = useState(false);
  const [speedResults, setSpeedResults] = useState(null);
  const [speedError, setSpeedError] = useState(null);

  // Secret Test Form State
  const [secretLoading, setSecretLoading] = useState(false);
  const [secretResults, setSecretResults] = useState(null);
  const [secretError, setSecretError] = useState(null);
  const [scanGitHistory, setScanGitHistory] = useState(false);

  useEffect(() => {
    if (mode !== "all") {
      setActiveTab(mode);
    } else {
      setActiveTab(initialTab);
    }
  }, [mode, initialTab]);

  useEffect(() => {
    getTestingStatus().then(setEngineStatus).catch(() => {});
  }, []);

  // Handlers
  const handleRunLoadTest = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    setLoadLoading(true);
    setLoadError(null);
    try {
      const res = await runLoadTest({
        url: loadUrl,
        connections: loadConnections,
        duration: loadDuration,
        pipelining: loadPipelining
      });
      setLoadResults(res);
    } catch (err) {
      setLoadError(err.message || "Failed to execute load test benchmark.");
    } finally {
      setLoadLoading(false);
    }
  };

  const handleRunSpeedTest = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    setSpeedLoading(true);
    setSpeedError(null);
    try {
      const res = await runSpeedTest({
        url: speedUrl,
        device: speedDevice
      });
      setSpeedResults(res);
    } catch (err) {
      setSpeedError(err.message || "Failed to execute Lighthouse speed test.");
    } finally {
      setSpeedLoading(false);
    }
  };

  const handleRunSecretTest = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    setSecretLoading(true);
    setSecretError(null);
    try {
      const res = await runSecretTest({ scanGitHistory });
      setSecretResults(res);
    } catch (err) {
      setSecretError(err.message || "Failed to execute Gitleaks scan.");
    } finally {
      setSecretLoading(false);
    }
  };

  // Auto-run once if empty on direct tab load for instant visual feedback
  useEffect(() => {
    if (activeTab === "load" && !loadResults && !loadLoading) {
      handleRunLoadTest();
    } else if (activeTab === "speed" && !speedResults && !speedLoading) {
      handleRunSpeedTest();
    } else if (activeTab === "secret" && !secretResults && !secretLoading) {
      handleRunSecretTest();
    }
  }, [activeTab]);

  return (
    <div className="testing-suite-container">
      {/* Header */}
      <div className="testing-suite-header">
        <div className="testing-suite-title-group">
          <h1>
            {activeTab === "load" && <BsFillPeopleFill style={{ color: "var(--accent-color, #38bdf8)" }} />}
            {activeTab === "speed" && <PiSpeedometerFill style={{ color: "var(--accent-color, #38bdf8)" }} />}
            {activeTab === "secret" && <FaUserSecret style={{ color: "var(--accent-color, #38bdf8)" }} />}
            {activeTab === "load" && "Load Test Studio (npx autocannon)"}
            {activeTab === "speed" && "Speed & Core Web Vitals Studio (npx lighthouse)"}
            {activeTab === "secret" && "Secret Leak Sentinel (gitleaks)"}
          </h1>
          <p>
            {activeTab === "load" && "High-concurrency HTTP load benchmark measuring RPS throughput, p50/p90/p99 latency, and server endurance."}
            {activeTab === "speed" && "Lighthouse audit evaluating Core Web Vitals (FCP, LCP, TBT, CLS), Accessibility, and Modern Standards."}
            {activeTab === "secret" && "Cryptographic secret and token scanner protecting AWS, GitHub, JWT, Stripe, and private keys from leaks."}
          </p>
        </div>

        {/* Show tab switcher only when in unified "all" mode */}
        {mode === "all" && (
          <div className="testing-suite-tabs">
            <button
              className={`testing-suite-tab-btn ${activeTab === "load" ? "active" : ""}`}
              onClick={() => setActiveTab("load")}
            >
              <BsFillPeopleFill /> Load Test
            </button>
            <button
              className={`testing-suite-tab-btn ${activeTab === "speed" ? "active" : ""}`}
              onClick={() => setActiveTab("speed")}
            >
              <PiSpeedometerFill /> Speed Test
            </button>
            <button
              className={`testing-suite-tab-btn ${activeTab === "secret" ? "active" : ""}`}
              onClick={() => setActiveTab("secret")}
            >
              <FaUserSecret /> Secret Test
            </button>
          </div>
        )}
      </div>

      {/* =========================================================================
          TAB 1: LOAD TEST (AUTOCANNON)
          ========================================================================= */}
      {activeTab === "load" && (
        <div>
          <div className="testing-config-card">
            <form onSubmit={handleRunLoadTest}>
              <div className="testing-form-grid">
                <div className="testing-form-group" style={{ gridColumn: "span 2" }}>
                  <label>Target URL Endpoint</label>
                  <input
                    type="url"
                    className="testing-input"
                    value={loadUrl}
                    onChange={(e) => setLoadUrl(e.target.value)}
                    placeholder="http://localhost:5173"
                    required
                  />
                </div>
                <div className="testing-form-group">
                  <label>Concurrent Connections ({loadConnections})</label>
                  <input
                    type="number"
                    min="1"
                    max="100"
                    className="testing-input"
                    value={loadConnections}
                    onChange={(e) => setLoadConnections(e.target.value)}
                  />
                </div>
                <div className="testing-form-group">
                  <label>Duration ({loadDuration}s)</label>
                  <input
                    type="number"
                    min="1"
                    max="60"
                    className="testing-input"
                    value={loadDuration}
                    onChange={(e) => setLoadDuration(e.target.value)}
                  />
                </div>
              </div>

              <button type="submit" className="testing-submit-btn" disabled={loadLoading}>
                {loadLoading ? (
                  <>
                    <FaSpinner className="spin-icon" /> Benchmarking Target...
                  </>
                ) : (
                  <>
                    <FaPlay /> Run Load Test (npx autocannon)
                  </>
                )}
              </button>
            </form>
          </div>

          {loadError && (
            <div style={{ color: "#ef4444", padding: "12px", background: "rgba(239, 68, 68, 0.1)", borderRadius: "6px", marginBottom: "16px" }}>
              <FaExclamationTriangle /> {loadError}
            </div>
          )}

          {loadResults && (
            <div className="testing-results-section">
              <div className="testing-kpi-row">
                <div className="testing-kpi-card">
                  <div className="kpi-label">Requests / Sec</div>
                  <div className="kpi-value">{loadResults.requests?.average || 0}</div>
                  <div className="kpi-sub">Total: {loadResults.requests?.total || 0} reqs</div>
                </div>
                <div className="testing-kpi-card">
                  <div className="kpi-label">Average Latency</div>
                  <div className="kpi-value">{loadResults.latency?.average || 0} ms</div>
                  <div className="kpi-sub">p99: {loadResults.latency?.p99 || 0} ms</div>
                </div>
                <div className="testing-kpi-card">
                  <div className="kpi-label">Throughput</div>
                  <div className="kpi-value">{loadResults.throughput?.mb_per_sec || 0} MB/s</div>
                  <div className="kpi-sub">Total: {Math.round((loadResults.throughput?.total || 0) / 1024)} KB</div>
                </div>
                <div className="testing-kpi-card">
                  <div className="kpi-label">Status Codes</div>
                  <div className="kpi-value" style={{ color: "#22c55e" }}>
                    {Object.entries(loadResults.statusCodes || {}).map(([k, v]) => `${k}: ${v}`).join(", ") || "200 OK"}
                  </div>
                  <div className="kpi-sub">Errors: {loadResults.errors || 0}</div>
                </div>
              </div>

              <div className="testing-table-container">
                <table className="testing-table">
                  <thead>
                    <tr>
                      <th>Percentile</th>
                      <th>Latency (ms)</th>
                      <th>Benchmark Status</th>
                      <th>Engine Mode</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr><td>50% (Median)</td><td>{loadResults.latency?.p50} ms</td><td><span className="badge-good">Optimal</span></td><td>{loadResults.engine}</td></tr>
                    <tr><td>90%</td><td>{loadResults.latency?.p90} ms</td><td><span className="badge-good">Fast</span></td><td>{loadResults.engine}</td></tr>
                    <tr><td>99%</td><td>{loadResults.latency?.p99} ms</td><td><span className="badge-good">Verified</span></td><td>{loadResults.engine}</td></tr>
                    <tr><td>Min</td><td>{loadResults.latency?.min} ms</td><td><span className="badge-good">Fastest</span></td><td>{loadResults.engine}</td></tr>
                    <tr><td>Max</td><td>{loadResults.latency?.max} ms</td><td><span className="badge-med">Peak</span></td><td>{loadResults.engine}</td></tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}

      {/* =========================================================================
          TAB 2: SPEED TEST (LIGHTHOUSE)
          ========================================================================= */}
      {activeTab === "speed" && (
        <div>
          <div className="testing-config-card">
            <form onSubmit={handleRunSpeedTest}>
              <div className="testing-form-grid">
                <div className="testing-form-group" style={{ gridColumn: "span 2" }}>
                  <label>Application URL</label>
                  <input
                    type="url"
                    className="testing-input"
                    value={speedUrl}
                    onChange={(e) => setSpeedUrl(e.target.value)}
                    placeholder="http://localhost:5173"
                    required
                  />
                </div>
                <div className="testing-form-group">
                  <label>Device Profile</label>
                  <select
                    className="testing-input"
                    value={speedDevice}
                    onChange={(e) => setSpeedDevice(e.target.value)}
                  >
                    <option value="desktop">Desktop Chrome</option>
                    <option value="mobile">Mobile Moto G4</option>
                  </select>
                </div>
              </div>

              <button type="submit" className="testing-submit-btn" disabled={speedLoading}>
                {speedLoading ? (
                  <>
                    <FaSpinner className="spin-icon" /> Running Lighthouse Audit...
                  </>
                ) : (
                  <>
                    <FaPlay /> Run Speed Test (npx lighthouse)
                  </>
                )}
              </button>
            </form>
          </div>

          {speedError && (
            <div style={{ color: "#ef4444", padding: "12px", background: "rgba(239, 68, 68, 0.1)", borderRadius: "6px", marginBottom: "16px" }}>
              <FaExclamationTriangle /> {speedError}
            </div>
          )}

          {speedResults && (
            <div className="testing-results-section">
              {/* Score Badges */}
              <div className="testing-kpi-row">
                <div className="testing-kpi-card" style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                  <div className={`score-circle ${speedResults.scores?.performance >= 90 ? "score-green" : (speedResults.scores?.performance >= 50 ? "score-yellow" : "score-red")}`}>
                    {speedResults.scores?.performance}
                  </div>
                  <div>
                    <div className="kpi-label">Performance</div>
                    <div style={{ fontSize: "12px", color: "#8b949e" }}>Core Web Vitals</div>
                  </div>
                </div>

                <div className="testing-kpi-card" style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                  <div className={`score-circle ${speedResults.scores?.accessibility >= 90 ? "score-green" : "score-yellow"}`}>
                    {speedResults.scores?.accessibility}
                  </div>
                  <div>
                    <div className="kpi-label">Accessibility</div>
                    <div style={{ fontSize: "12px", color: "#8b949e" }}>ARIA & Contrast</div>
                  </div>
                </div>

                <div className="testing-kpi-card" style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                  <div className={`score-circle ${speedResults.scores?.bestPractices >= 90 ? "score-green" : "score-yellow"}`}>
                    {speedResults.scores?.bestPractices}
                  </div>
                  <div>
                    <div className="kpi-label">Best Practices</div>
                    <div style={{ fontSize: "12px", color: "#8b949e" }}>Modern Web Standards</div>
                  </div>
                </div>

                <div className="testing-kpi-card" style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                  <div className={`score-circle ${speedResults.scores?.seo >= 90 ? "score-green" : "score-yellow"}`}>
                    {speedResults.scores?.seo}
                  </div>
                  <div>
                    <div className="kpi-label">SEO</div>
                    <div style={{ fontSize: "12px", color: "#8b949e" }}>Search Visibility</div>
                  </div>
                </div>
              </div>

              {/* Core Web Vitals */}
              <div className="testing-table-container">
                <table className="testing-table">
                  <thead>
                    <tr>
                      <th>Core Web Vital Metric</th>
                      <th>Observed Value</th>
                      <th>Evaluation Threshold</th>
                      <th>Rating</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <td><strong>First Contentful Paint (FCP)</strong></td>
                      <td>{speedResults.metrics?.fcp} ms</td>
                      <td>&lt; 1800 ms (Good)</td>
                      <td><span className="badge-good">GOOD</span></td>
                    </tr>
                    <tr>
                      <td><strong>Largest Contentful Paint (LCP)</strong></td>
                      <td>{speedResults.metrics?.lcp} ms</td>
                      <td>&lt; 2500 ms (Good)</td>
                      <td><span className="badge-good">GOOD</span></td>
                    </tr>
                    <tr>
                      <td><strong>Total Blocking Time (TBT)</strong></td>
                      <td>{speedResults.metrics?.tbt} ms</td>
                      <td>&lt; 200 ms (Good)</td>
                      <td><span className="badge-good">FAST</span></td>
                    </tr>
                    <tr>
                      <td><strong>Cumulative Layout Shift (CLS)</strong></td>
                      <td>{speedResults.metrics?.cls}</td>
                      <td>&lt; 0.1 (Good)</td>
                      <td><span className="badge-good">STABLE</span></td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}

      {/* =========================================================================
          TAB 3: SECRET TEST (GITLEAKS)
          ========================================================================= */}
      {activeTab === "secret" && (
        <div>
          <div className="testing-config-card">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "16px" }}>
              <div>
                <h3 style={{ fontSize: "15px", color: "var(--text-primary, #f0f6fc)", marginBottom: "4px" }}>Gitleaks Workspace Secret Scanner</h3>
                <p style={{ fontSize: "13px", color: "var(--text-secondary, #8b949e)" }}>Scans repository files for hardcoded AWS keys, GitHub PATs, private keys, JWTs, and database credentials.</p>
              </div>

              <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                <label style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "13px", cursor: "pointer", color: "var(--text-secondary, #8b949e)" }}>
                  <input
                    type="checkbox"
                    checked={scanGitHistory}
                    onChange={(e) => setScanGitHistory(e.target.checked)}
                  />
                  Scan Git Commit Logs
                </label>

                <button
                  className="testing-submit-btn"
                  onClick={handleRunSecretTest}
                  disabled={secretLoading}
                >
                  {secretLoading ? (
                    <>
                      <FaSpinner className="spin-icon" /> Scanning Codebase...
                    </>
                  ) : (
                    <>
                      <FaPlay /> Scan Workspace (gitleaks)
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>

          {secretError && (
            <div style={{ color: "#ef4444", padding: "12px", background: "rgba(239, 68, 68, 0.1)", borderRadius: "6px", marginBottom: "16px" }}>
              <FaExclamationTriangle /> {secretError}
            </div>
          )}

          {secretResults && (
            <div className="testing-results-section">
              <div className="testing-kpi-row">
                <div className="testing-kpi-card">
                  <div className="kpi-label">Files Scanned</div>
                  <div className="kpi-value">{secretResults.files_scanned || 0}</div>
                  <div className="kpi-sub">Total Monorepo Source</div>
                </div>
                <div className="testing-kpi-card">
                  <div className="kpi-label">Total Leaks Detected</div>
                  <div className="kpi-value" style={{ color: secretResults.total_leaks > 0 ? "#ef4444" : "#22c55e" }}>
                    {secretResults.total_leaks}
                  </div>
                  <div className="kpi-sub">{secretResults.total_leaks === 0 ? "✔ All Clean" : "Requires Rotation"}</div>
                </div>
                <div className="testing-kpi-card">
                  <div className="kpi-label">Critical Leaks</div>
                  <div className="kpi-value" style={{ color: "#ef4444" }}>
                    {secretResults.severity_summary?.CRITICAL || 0}
                  </div>
                  <div className="kpi-sub">AWS / Tokens / Keys</div>
                </div>
              </div>

              {secretResults.findings && secretResults.findings.length > 0 ? (
                <div className="testing-table-container">
                  <table className="testing-table">
                    <thead>
                      <tr>
                        <th>Severity</th>
                        <th>Secret Type</th>
                        <th>Location</th>
                        <th>Masked Secret</th>
                        <th>Snippet</th>
                        <th>Remediation</th>
                      </tr>
                    </thead>
                    <tbody>
                      {secretResults.findings.map((f, i) => (
                        <tr key={i}>
                          <td>
                            <span className={f.severity === "CRITICAL" ? "badge-crit" : (f.severity === "HIGH" ? "badge-high" : "badge-med")}>
                              {f.severity}
                            </span>
                          </td>
                          <td><strong>{f.secret_type || f.rule_id}</strong></td>
                          <td><code>{f.file}:{f.line}</code></td>
                          <td><code>{f.masked_secret}</code></td>
                          <td><div className="code-snippet">{f.snippet}</div></td>
                          <td><small>{f.remediation}</small></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div style={{ textAlign: "center", padding: "48px 24px", background: "var(--bg-secondary, #161b22)", borderRadius: "8px", border: "1px solid var(--border-color, #30363d)" }}>
                  <FaCheckCircle style={{ fontSize: "48px", color: "#22c55e", marginBottom: "16px" }} />
                  <h3 style={{ fontSize: "18px", color: "var(--text-primary, #f0f6fc)", marginBottom: "8px" }}>Zero Leaked Secrets Detected</h3>
                  <p style={{ color: "var(--text-secondary, #8b949e)", maxWidth: "500px", margin: "0 auto" }}>
                    Gitleaks scanned {secretResults.files_scanned || "all"} codebase files against OWASP & Gitleaks rules. No unprotected API keys, JWT secrets, private keys, or credentials were discovered.
                  </p>
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { createContext, useState, useRef, useContext, useEffect } from "react";
import fileTree from "../data/fileTree";
import { traverseDirectory, flattenFiles, readFileContent, writeFileContent, getLanguageFromFileName } from "../services/fileService";
import { loadEditorFile, saveEditorFile, refreshEditorContent } from "../services/editorService";
import { FileContext } from "./FileContext";
import { saveWorkspaceState, getStoredWorkspaceState, clearWorkspaceState } from "../services/workspacePersistence";
import { isIgnoredPath } from "../services/architectureScanner";

const initialFiles = flattenFiles(fileTree);

function extractTitleFromHtml(htmlContent) {
  if (!htmlContent) return null;
  const titleMatch = htmlContent.match(/<title[^>]*>([^<]+)<\/title>/i);
  return titleMatch ? titleMatch[1].trim() : null;
}

export const EditorContext = createContext(null);

export function EditorProvider({ children }) {
  const fileContext = useContext(FileContext);
  const initialCached = getStoredWorkspaceState();

  const [workspaceTree, setWorkspaceTree] = useState(() => {
    return initialCached?.workspaceTree && initialCached.workspaceTree.length > 0
      ? initialCached.workspaceTree
      : fileTree;
  });
  const [workspaceHandle, setWorkspaceHandle] = useState(null);

  const [files, setFiles] = useState(() => {
    if (initialCached?.workspaceTree && initialCached.workspaceTree.length > 0) {
      return flattenFiles(initialCached.workspaceTree);
    }
    return initialFiles;
  });

  const [openFiles, setOpenFiles] = useState(() => {
    if (initialCached?.openFiles && initialCached.openFiles.length > 0) {
      return initialCached.openFiles;
    }
    return initialFiles.slice(0, 1);
  });

  const [activeFile, setActiveFile] = useState(() => {
    if (initialCached?.openFiles && initialCached.openFiles.length > 0) {
      if (initialCached.activeFileId) {
        const found = initialCached.openFiles.find((f) => f.id === initialCached.activeFileId);
        if (found) return found;
      }
      return initialCached.openFiles[0];
    }
    return initialFiles[0] ?? null;
  });

  const editorRef = useRef(null);
  const [sidebarActive, setSidebarActive] = useState(() => {
    return initialCached?.sidebarActive || "explorer";
  });
  const [searchQuery, setSearchQuery] = useState("");
  const [replaceQuery, setReplaceQuery] = useState("");
  const [isReplaceOpen, setIsReplaceOpen] = useState(false);
  const [problems, setProblems] = useState([]);

  // View & Layout states
  const [isSidebarVisible, setIsSidebarVisible] = useState(true);
  const [isBottomPanelOpen, setIsBottomPanelOpen] = useState(true);
  const [bottomPanelTab, setBottomPanelTab] = useState("Terminal");
  const [isStatusBarVisible, setIsStatusBarVisible] = useState(true);
  const [isZenMode, setIsZenMode] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [commandPaletteMode, setCommandPaletteMode] = useState("commands"); // "commands" | "views"
  const [isWordWrapOn, setIsWordWrapOn] = useState(true);
  const [isAutoSave, setIsAutoSave] = useState(() => {
    const saved = localStorage.getItem("hyperion_autosave");
    return saved !== null ? saved === "true" : true;
  });

  function toggleWordWrap() {
    setIsWordWrapOn((prev) => {
      const next = !prev;
      if (editorRef.current) {
        editorRef.current.updateOptions({ wordWrap: next ? "on" : "off" });
      }
      return next;
    });
  }

  function toggleAutoSave() {
    setIsAutoSave((prev) => {
      const next = !prev;
      localStorage.setItem("hyperion_autosave", String(next));
      return next;
    });
  }

  // Debounced auto-save effect when isAutoSave is enabled
  const autoSaveTimerRef = useRef(null);
  useEffect(() => {
    if (!isAutoSave || !activeFile) return;
    if (activeFile.isBinary || activeFile.isPreview || activeFile.isLiveUrl) return;

    if (autoSaveTimerRef.current) {
      clearTimeout(autoSaveTimerRef.current);
    }

    autoSaveTimerRef.current = setTimeout(async () => {
      let targetHandle = activeFile.handle;
      if (!targetHandle && fileContext?.files) {
        const match = fileContext.files.find((f) => f.id === activeFile.id || f.path === activeFile.path);
        if (match?.handle) {
          targetHandle = match.handle;
        }
      }
      if (targetHandle) {
        try {
          await saveEditorFile({ ...activeFile, handle: targetHandle });
        } catch {}
      }
    }, 1500);

    return () => {
      if (autoSaveTimerRef.current) clearTimeout(autoSaveTimerRef.current);
    };
  }, [activeFile?.content, isAutoSave, activeFile?.id]);

  function toggleSidebar() {
    setIsSidebarVisible((prev) => !prev);
  }

  function toggleBottomPanel() {
    setIsBottomPanelOpen((prev) => !prev);
  }

  function toggleStatusBar() {
    setIsStatusBarVisible((prev) => !prev);
  }

  function toggleZenMode() {
    setIsZenMode((prev) => !prev);
  }

  function toggleFullScreen() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  }

  function openView(viewId) {
    switch (viewId) {
      case "explorer":
        setSidebarActive("explorer");
        setIsSidebarVisible(true);
        break;
      case "search":
        setSidebarActive("search");
        setIsSidebarVisible(true);
        break;
      case "git":
      case "sourceControl":
        setSidebarActive("git");
        setIsSidebarVisible(true);
        break;
      case "run":
        setSidebarActive("run");
        setIsSidebarVisible(true);
        break;
      case "extensions":
        setSidebarActive("extensions");
        setIsSidebarVisible(true);
        break;
      case "problems":
        setBottomPanelTab("Problems");
        setIsBottomPanelOpen(true);
        break;
      case "output":
        setBottomPanelTab("Output");
        setIsBottomPanelOpen(true);
        break;
      case "debugConsole":
        setBottomPanelTab("Debug Console");
        setIsBottomPanelOpen(true);
        break;
      case "terminal":
        setBottomPanelTab("Terminal");
        setIsBottomPanelOpen(true);
        break;
      case "ports":
        setBottomPanelTab("Ports");
        setIsBottomPanelOpen(true);
        break;
      case "repl":
        setBottomPanelTab("REPL");
        setIsBottomPanelOpen(true);
        break;
      case "browser":
        openLiveBrowserTab("http://localhost:5173", "Live Browser Preview");
        break;
      case "architecture":
        setSidebarActive("architecture");
        setIsSidebarVisible(true);
        break;
      case "architecture-canvas":
        openArchitectureTab();
        break;
      case "api-client":
      case "curl":
      case "postman":
        setSidebarActive("api-client");
        setIsSidebarVisible(true);
        break;
      case "api-client-tab":
        openApiClientTab();
        break;
      case "mongoschema":
      case "erd":
        openMongoSchemaTab();
        break;
      case "routes":
      case "backend-routes":
        openBackendRoutesTab();
        break;
      case "selenium":
      case "selenium-studio":
        openSeleniumStudioTab();
        break;
      case "settings":
      case "preferences":
        openSettingsTab();
        break;
      default:
        break;
    }
  }

  function jumpToProblem(problem) {
    if (!problem) return;
    if (problem.fileId || problem.filename) {
      const target = openFiles.find(
        (f) => f.id === problem.fileId || f.name === problem.filename || f.path === problem.filename
      ) || files.find((f) => f.name === problem.filename || f.path === problem.filename);
      if (target && target.id !== activeFile?.id) {
        openFile(target);
      }
    }
    setTimeout(() => {
      if (editorRef.current) {
        const line = problem.startLineNumber || problem.lineNumber || 1;
        const col = problem.startColumn || problem.column || 1;
        editorRef.current.revealPositionInCenter({ lineNumber: line, column: col });
        editorRef.current.setPosition({ lineNumber: line, column: col });
        editorRef.current.focus();
      }
    }, 60);
  }

  // Sync files and handles from FileContext
  useEffect(() => {
    if (fileContext?.files && fileContext.files.length > 0) {
      setFiles((prevFiles) => {
        return fileContext.files.map((fcFile) => {
          const inMemoryOpen = openFiles.find((of) => of.id === fcFile.id || of.path === fcFile.path);
          if (inMemoryOpen && inMemoryOpen.content != null) {
            return { ...fcFile, content: inMemoryOpen.content };
          }
          const existingInMemory = prevFiles.find((pf) => pf.id === fcFile.id || pf.path === fcFile.path);
          if (existingInMemory && existingInMemory.content != null) {
            return { ...fcFile, content: existingInMemory.content };
          }
          return fcFile;
        });
      });

      // Attach live handles to openFiles
      setOpenFiles((prevOpen) => {
        return prevOpen.map((tab) => {
          const match = fileContext.files.find((f) => f.id === tab.id || f.path === tab.path);
          if (match?.handle) {
            return { ...tab, handle: match.handle };
          }
          return tab;
        });
      });

      // Attach live handle to activeFile
      setActiveFile((prevActive) => {
        if (!prevActive) return prevActive;
        const match = fileContext.files.find((f) => f.id === prevActive.id || f.path === prevActive.path);
        if (match?.handle) {
          return { ...prevActive, handle: match.handle };
        }
        return prevActive;
      });
    }
  }, [fileContext?.files]);

  // Persist openFiles, activeFile, and sidebar tab in LocalStorage
  useEffect(() => {
    saveWorkspaceState({
      openFiles,
      activeFileId: activeFile?.id || null,
      sidebarActive
    });
  }, [openFiles, activeFile, sidebarActive]);

  async function openFolder() {
    if (fileContext?.openFolder) {
      await fileContext.openFolder();
      setOpenFiles([]);
      setActiveFile(null);
      return;
    }

    if (!window.showDirectoryPicker) {
      alert("Your browser does not support the File System Access API.");
      return;
    }

    try {
      const dirHandle = await window.showDirectoryPicker();
      const tree = [
        {
          id: dirHandle.name,
          name: dirHandle.name,
          type: "folder",
          path: dirHandle.name,
          handle: dirHandle,
          children: await traverseDirectory(dirHandle, dirHandle.name)
        }
      ];

      const flatFiles = flattenFiles(tree);
      setWorkspaceHandle(dirHandle);
      setWorkspaceTree(tree);
      setFiles(flatFiles);
      setOpenFiles([]);
      setActiveFile(null);
    } catch (error) {
      console.error("Failed to open folder:", error);
    }
  }

  async function openFile(file) {
    const existingFile =
      files.find((f) => f.id === file.id || f.path === file.path) ||
      fileContext?.files?.find((f) => f.id === file.id || f.path === file.path) ||
      file;

    let loadedFile = { ...existingFile, ...file };

    if (loadedFile.handle && loadedFile.content == null && !loadedFile.isBinary) {
      loadedFile = await loadEditorFile(loadedFile);
      setFiles((prev) => prev.map((f) => (f.id === loadedFile.id ? loadedFile : f)));
    }

    setOpenFiles((prev) => {
      const alreadyOpenIndex = prev.findIndex((f) => f.id === loadedFile.id);
      if (alreadyOpenIndex >= 0) {
        return prev.map((f, i) => (i === alreadyOpenIndex ? { ...f, ...loadedFile } : f));
      }
      return [...prev, loadedFile];
    });

    setActiveFile(loadedFile);
  }

  function createNewTextFile() {
    const existingNums = openFiles
      .map((f) => {
        const m = f.name?.match(/^Untitled-(\d+)\.txt$/i);
        return m ? parseInt(m[1], 10) : 0;
      })
      .filter(Boolean);
    const nextNum = existingNums.length > 0 ? Math.max(...existingNums) + 1 : 1;
    const filename = `Untitled-${nextNum}.txt`;
    const newFile = {
      id: `untitled_${Date.now()}_${nextNum}`,
      name: filename,
      path: filename,
      language: "plaintext",
      content: ""
    };
    setFiles((prev) => [...prev, newFile]);
    setOpenFiles((prev) => [...prev, newFile]);
    setActiveFile(newFile);
    return newFile;
  }

  async function saveActiveFile() {
    if (!activeFile) return false;

    let targetHandle = activeFile.handle;
    if (!targetHandle && fileContext?.files) {
      const match = fileContext.files.find((f) => f.id === activeFile.id || f.path === activeFile.path);
      if (match?.handle) {
        targetHandle = match.handle;
        activeFile.handle = match.handle;
      }
    }

    if (targetHandle) {
      try {
        await saveEditorFile({ ...activeFile, handle: targetHandle });
        return true;
      } catch (error) {
        console.error("Save failed:", error);
      }
    }

    // If no direct handle (in-memory or untitled file), allow native save dialog if available
    if (window.showSaveFilePicker) {
      try {
        const handle = await window.showSaveFilePicker({ suggestedName: activeFile.name });
        await writeFileContent(handle, activeFile.content || "");
        activeFile.handle = handle;
        return true;
      } catch (e) {
        if (e.name === "AbortError") return false;
      }
    }

    // Fallback: Export as downloadable file
    const blob = new Blob([activeFile.content || ""], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = activeFile.name;
    a.click();
    URL.revokeObjectURL(url);
    return true;
  }

  async function saveAsFile() {
    if (!activeFile) return false;

    if (window.showSaveFilePicker) {
      try {
        const handle = await window.showSaveFilePicker({ suggestedName: activeFile.name });
        await writeFileContent(handle, activeFile.content || "");
        const cloned = {
          id: handle.name + "_" + Date.now(),
          name: handle.name,
          path: handle.name,
          handle,
          content: activeFile.content || "",
          language: getLanguageFromFileName(handle.name)
        };
        setFiles((prev) => [...prev, cloned]);
        setOpenFiles((prev) => [...prev, cloned]);
        setActiveFile(cloned);
        return true;
      } catch (e) {
        if (e.name === "AbortError") return false;
      }
    }

    const newName = window.prompt("Save File As:", activeFile.name);
    if (newName && newName.trim()) {
      const trimmed = newName.trim();
      const blob = new Blob([activeFile.content || ""], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = trimmed;
      a.click();
      URL.revokeObjectURL(url);
      createOrOpenFile(trimmed, activeFile.content || "");
      return true;
    }
    return false;
  }

  async function saveAllFiles() {
    let savedCount = 0;
    for (const file of openFiles) {
      if (file.handle) {
        try {
          await saveEditorFile(file);
          savedCount++;
        } catch (err) {
          console.warn(`Failed to save ${file.name}:`, err);
        }
      }
    }
    return savedCount;
  }

  async function revertActiveFile() {
    if (!activeFile) return false;
    if (activeFile.handle) {
      try {
        const diskContent = await readFileContent(activeFile.handle);
        if (diskContent !== null) {
          updateContent(diskContent);
          return true;
        }
      } catch (err) {
        console.warn("Revert file failed:", err);
      }
    }
    return false;
  }

  function closeWorkspace() {
    setOpenFiles([]);
    setActiveFile(null);
    setWorkspaceTree([]);
    setFiles([]);
    clearWorkspaceState();
    if (fileContext?.closeFolder) {
      fileContext.closeFolder();
    }
  }

  function closeFile(id) {
    const updated = openFiles.filter((file) => file.id !== id);

    setOpenFiles(updated);

    if (activeFile && activeFile.id === id) {
      setActiveFile(updated[0] ?? null);
    }
  }

  function updateContent(value) {
    if (!activeFile) return;

    const { updatedFiles, updatedOpenFiles, updatedActiveFile } = refreshEditorContent(
      activeFile.id,
      files,
      openFiles,
      activeFile,
      value
    );

    setFiles(updatedFiles);
    setOpenFiles(updatedOpenFiles);
    setActiveFile(updatedActiveFile);
  }

  function openPreviewTab(file) {
    const htmlTitle = extractTitleFromHtml(file.content);
    const tabName = htmlTitle || file.name;

    const previewTab = {
      id: `preview-${file.id}`,
      name: tabName,
      type: "preview",
      sourceFile: file,
      isPreview: true,
      htmlTitle: htmlTitle
    };

    const alreadyOpen = openFiles.some((f) => f.id === previewTab.id);
    if (!alreadyOpen) {
      setOpenFiles((prev) => [...prev, previewTab]);
    }

    setActiveFile(previewTab);
  }

  const [comparedFile, setComparedFile] = useState(null);

  function openDiffTab(originalFile, modifiedFile) {
    if (!originalFile || !modifiedFile) return;
    const tabId = `diff-${originalFile.id || originalFile.name}-${modifiedFile.id || modifiedFile.name}`;
    const name = `${originalFile.name} ↔ ${modifiedFile.name}`;

    const diffTab = {
      id: tabId,
      name,
      type: "diff",
      isDiff: true,
      originalFile,
      modifiedFile
    };

    setOpenFiles((prev) => {
      const existing = prev.find((f) => f.id === tabId);
      if (existing) {
        setActiveFile(existing);
        return prev;
      }
      setActiveFile(diffTab);
      return [...prev, diffTab];
    });
  }

  function renameOpenFile(oldId, newName, newPath) {
    setOpenFiles((prev) =>
      prev.map((f) => {
        if (f.id === oldId || f.name === oldId || f.path === oldId) {
          return {
            ...f,
            name: newName,
            path: newPath || f.path,
            language: getLanguageFromFileName(newName)
          };
        }
        return f;
      })
    );
    setActiveFile((prev) => {
      if (prev && (prev.id === oldId || prev.name === oldId || prev.path === oldId)) {
        return {
          ...prev,
          name: newName,
          path: newPath || prev.path,
          language: getLanguageFromFileName(newName)
        };
      }
      return prev;
    });
  }

  function openLiveBrowserTab(targetUrl, tabTitle) {
    if (!targetUrl) return null;
    let cleanUrl = targetUrl.trim();
    if (!cleanUrl.startsWith("http://") && !cleanUrl.startsWith("https://")) {
      cleanUrl = "http://" + cleanUrl;
    }
    const tabId = `browser-${cleanUrl}`;
    const name = tabTitle || `Preview: ${cleanUrl.replace(/^https?:\/\//, '')}`;

    setOpenFiles((prev) => {
      const existing = prev.find((f) => f.id === tabId || f.url === cleanUrl);
      if (existing) {
        setActiveFile(existing);
        return prev;
      }
      const newTab = {
        id: tabId,
        name,
        type: "browser",
        isPreview: true,
        isLiveUrl: true,
        url: cleanUrl
      };
      setActiveFile(newTab);
      return [...prev, newTab];
    });
  }

  function openArchitectureTab() {
    const tabId = "hyperion-architecture-blueprint";
    const name = "Architecture Blueprint";

    setOpenFiles((prev) => {
      const existing = prev.find((f) => f.id === tabId);
      if (existing) {
        setActiveFile(existing);
        return prev;
      }
      const newTab = {
        id: tabId,
        name,
        type: "architecture",
        isPreview: true,
        isArchitecture: true
      };
      setActiveFile(newTab);
      return [...prev, newTab];
    });
  }

  function openApiClientTab() {
    const tabId = "hyperion-api-client";
    const name = "API Client & cURL";

    setOpenFiles((prev) => {
      const existing = prev.find((f) => f.id === tabId);
      if (existing) {
        setActiveFile(existing);
        return prev;
      }
      const newTab = {
        id: tabId,
        name,
        type: "api-client",
        isPreview: true,
        isApiClient: true
      };
      setActiveFile(newTab);
      return [...prev, newTab];
    });
  }

  function openSourceControlTab() {
    const tabId = "hyperion-source-control";
    const name = "Source Control: Git";

    setOpenFiles((prev) => {
      const existing = prev.find((f) => f.id === tabId);
      if (existing) {
        setActiveFile(existing);
        return prev;
      }
      const newTab = {
        id: tabId,
        name,
        type: "source-control",
        isPreview: true,
        isSourceControl: true
      };
      setActiveFile(newTab);
      return [...prev, newTab];
    });
  }

  function openMongoSchemaTab(modelName = null) {
    const tabId = "hyperion-mongoschema-erd";
    const name = "MongoSchema ERD";

    setOpenFiles((prev) => {
      const existing = prev.find((f) => f.id === tabId);
      if (existing) {
        if (modelName) {
          existing.initialModel = modelName;
        }
        setActiveFile(existing);
        return prev;
      }
      const newTab = {
        id: tabId,
        name,
        type: "mongoschema",
        isPreview: true,
        isMongoSchema: true,
        initialModel: modelName
      };
      setActiveFile(newTab);
      return [...prev, newTab];
    });
  }

