      setWorkspaceTree((prev) => {
        const addNode = (nodes) => {
          if (!targetFolder) return [...nodes, newFolder];
          return nodes.map((n) => {
            if (n.id === targetFolder.id && n.type === "folder") {
              return { ...n, children: [...(n.children || []), newFolder] };
            }
            if (n.children) {
              return { ...n, children: addNode(n.children) };
            }
            return n;
