        const updated = addNode(prev);
        setFiles(flattenFiles(updated));
        saveWorkspaceState({
          folderName: persistedFolderInfo?.name || "Workspace",
          folderPath: persistedFolderInfo?.path || "",
          workspaceTree: updated
