      loadFileContent,
      saveFile,
      needsPermission,
      persistedFolderInfo,
      closeFolder,
      addDirectoryToWorkspace
    }),
    [workspaceTree, workspaceHandle, files, needsPermission, persistedFolderInfo]
  );

  return <FileContext.Provider value={value}>{children}</FileContext.Provider>;
