        } else if (prof === 'cmd') {
            title = `cmd (Split)`;
            prompt = `${termCwd}> `;
            output = [
                prompt
            ];
        } else if (prof === 'node') {
            title = `node (Split)`;
            prompt = "> ";
            output = [
                prompt
            ];
        } else if (prof === 'python') {
            title = `python (Split)`;
            prompt = ">>> ";
            output = [
                prompt
            ];
        } else if (prof === 'cypher') {
            title = `Cypher (Split)`;
            prompt = "cypher> ";
            output = [
                "\x1b[35m[Cypher AI Security Terminal]\x1b[0m",
                prompt
            ];
        }

        const newTerm = {
            id: newId,
            title,
            cwd: termCwd,
            profile: prof,
            prompt,
            history: [],
            output
        };

        setTerminals(prev => {
            const base = isSplit ? prev.filter(t => !t.title?.includes('(Split)')) : prev;
            const updated = [...base, newTerm];
            terminalsRef.current = updated;
            return updated;
        });
        setIsSplit(true);

        if (prof === 'node' || prof === 'python') {
            setTimeout(() => {
                startReplSession({
                    sessionId: `term-${newId}`,
                    runtime: prof,
                    cwd: termCwd
                }).then(session => {
                    setTerminals(prev => prev.map(t => {
                        if (t.id !== newId) return t;
                        return {
                            ...t,
                            replState: {
                                active: true,
                                runtime: prof,
                                sessionId: `term-${newId}`,
                                prompt: session.prompt || (prof === 'node' ? '> ' : '>>> '),
                                isMultiLine: false
                            }
                        };
                    }));
                }).catch(() => {});
            }, 100);
        }
    }

    function toggleMaximizeTerminal() {
        setIsMaximized(prev => !prev);
    }

    const appendToTerminal = useCallback((textOrLines, targetTermId = null) => {
        setTerminals(prev => prev.map(t => {
            const destId = targetTermId ?? activeTerminalIdRef.current;
            if (t.id !== destId) return t;
            const newLines = Array.isArray(textOrLines) ? textOrLines : [textOrLines];
            return {
                ...t,
                output: [...t.output, ...newLines]
            };
        }));
    }, []);

    const setTerminalOutput = useCallback((newOutput, targetTermId = null) => {
        setTerminals(prev => prev.map(t => {
            const destId = targetTermId ?? activeTerminalIdRef.current;
            if (t.id !== destId) return t;
            return {
                ...t,
                output: newOutput
            };
        }));
    }, []);

    /**
     * Send real-time input to running terminal process stdin
     */
    const sendTerminalInput = useCallback(async (data, targetTermId = null) => {
        const destId = targetTermId ?? activeTerminalIdRef.current;
        let active = activeStreamsRef.current[destId];
        if (!active?.streamId) {
            const entries = Object.values(activeStreamsRef.current || {});
            if (entries.length > 0) {
                active = entries[entries.length - 1];
            }
        }
        if (active?.streamId) {
            await sendStreamStdin(active.streamId, data);
        }
    }, []);

    /**
     * Execute Terminal Command
     */
    const executeCommand = useCallback(async (command, targetTermId = null) => {
        const targetId = targetTermId ?? activeTerminalIdRef.current;
        const targetTerm = terminalsRef.current.find(t => t.id === targetId) || terminals.find(t => t.id === targetId) || activeTerminal;
        if (!targetTerm) return;

        const trimmed = command.trim();

        // 1. If currently in an active REPL session, route input directly to REPL engine
        if (targetTerm?.replState?.active) {
            const repl = targetTerm.replState;
            const currentPrompt = repl.prompt || (repl.runtime === 'node' ? '> ' : '>>> ');
            const commandWithPrompt = `${currentPrompt}${command}`;
            const newHistory = [...targetTerm.history, command];

            // If empty enter on single-line prompt, just reprint prompt
            if (!trimmed && !repl.isMultiLine) {
                setTerminals(prev => prev.map(t => {
                    if (t.id !== targetId) return t;
                    return {
                        ...t,
                        output: [...t.output, currentPrompt]
                    };
                }));
                return;
            }

            setTerminals(prev => prev.map(t => {
                if (t.id !== targetId) return t;
                return {
                    ...t,
                    history: newHistory,
                    output: [...t.output, commandWithPrompt]
                };
            }));

            // Handle user typing exit
            const isExit = trimmed === 'exit()' || trimmed === 'quit()' || trimmed === '.exit' ||
                (trimmed === 'exit' && (repl.runtime === 'python' || repl.runtime === 'node'));

            if (isExit) {
                exitReplSession(repl.sessionId).catch(() => {});
                const shellPrompt = getTerminalPrompt(targetTerm);
                setTerminals(prev => prev.map(t => {
                    if (t.id !== targetId) return t;
                    return {
                        ...t,
                        replState: null,
                        output: [...t.output, `\x1b[90m[Exited ${repl.runtime.toUpperCase()} REPL]\x1b[0m`, shellPrompt]
                    };
                }));
                return;
            }

            setIsRunning(true);
            try {
                const res = await evalReplCode({
                    sessionId: repl.sessionId,
                    code: command
                });

                if (res.exited) {
                    const shellPrompt = getTerminalPrompt(targetTerm);
                    setTerminals(prev => prev.map(t => {
                        if (t.id !== targetId) return t;
                        const outLines = [];
                        if (res.output) {
                            outLines.push(...res.output.replace(/\r\n/g, '\n').split('\n'));
                        }
                        outLines.push(`\x1b[90m[Exited ${repl.runtime.toUpperCase()} REPL]\x1b[0m`, shellPrompt);
                        return {
                            ...t,
                            replState: null,
                            output: [...t.output, ...outLines]
                        };
                    }));
                } else {
                    const outLines = [];
                    if (res.output) {
                        outLines.push(...res.output.replace(/\r\n/g, '\n').split('\n'));
                    }
                    const nextPrompt = res.prompt || (repl.runtime === 'node' ? '> ' : '>>> ');
                    outLines.push(nextPrompt);

                    setTerminals(prev => prev.map(t => {
                        if (t.id !== targetId) return t;
                        return {
                            ...t,
                            replState: {
                                ...t.replState,
                                prompt: nextPrompt,
                                isMultiLine: !!res.isMultiLine
                            },
                            output: [...t.output, ...outLines]
                        };
                    }));
                }
            } catch (err) {
                appendToTerminal([`\x1b[31mREPL evaluation error: ${err.message}\x1b[0m`, currentPrompt], targetId);
            } finally {
                setIsRunning(false);
            }
            return;
        }

        const activePrompt = getTerminalPrompt(targetTerm);
        const commandWithPrompt = `${activePrompt}${command}`;
        const newHistory = [...targetTerm.history, command];

        if (!trimmed) {
            setTerminals(prev => prev.map(t => {
                if (t.id !== targetId) return t;
                return {
                    ...t,
                    output: [...t.output, activePrompt]
                };
            }));
            return;
        }

        setTerminals(prev => prev.map(t => {
            if (t.id !== targetId) return t;
            const lastLine = t.output[t.output.length - 1];
            const isLastPrompt = isPromptOnlyLine(lastLine) || (typeof lastLine === 'string' && lastLine.trim() === activePrompt.trim());
            const baseOutput = isLastPrompt ? t.output.slice(0, -1) : t.output;
            return {
                ...t,
                history: newHistory,
                output: [...baseOutput, commandWithPrompt]
            };
        }));

        // 1.5 Cypher Security Terminal CLI Routing
        if (targetTerm?.profile === 'cypher' || trimmed.toLowerCase().startsWith('cypher ')) {
            setIsRunning(true);
            try {
                const res = await executeCypherCommand({
                    command: trimmed,
                    activeFile,
                    files,
                    workspacePath: currentWorkspacePath
                });

                if (res.type === 'clear') {
                    setTerminalOutput([...res.lines, activePrompt], targetId);
                } else if (res.type === 'output') {
                    appendToTerminal([...res.lines, activePrompt], targetId);
                }

                if (res.analysis) {
                    setLatestExecution({
                        filename: res.analysis.filename || activeFile?.name || 'Security Audit',
                        language: 'security',
                        timestamp: new Date().toLocaleTimeString(),
                        duration: 150,
                        exitCode: res.analysis.riskLevel === 'CRITICAL' ? 1 : 0,
                        success: res.analysis.riskLevel !== 'CRITICAL',
                        stdout: res.lines.join('\n'),
                        stderr: null,
                        stage: 'security-scan'
                    });
                }
            } catch (err) {
                appendToTerminal([`\x1b[31m[Cypher Error] ${err.message}\x1b[0m`, activePrompt], targetId);
            } finally {
                setIsRunning(false);
            }
            return;
        }

        const parts = trimmed.split(/\s+/);
        const cmd = parts[0].toLowerCase();
        const argsStr = parts.slice(1).join(" ");

        if (cmd === "clear" || cmd === "cls") {
            setTerminalOutput([activePrompt], targetId);
            return;
        }

        if (cmd === "kill" || cmd === "exit") {
            killTerminal(targetId);
            return;
        }

        if (cmd === "cd") {
            const currentCwd = targetTerm?.cwd || currentWorkspacePath || "D:\\Rough\\WebIDE";
            const target = argsStr.trim();
            if (!target || target === "~") {
                const cached = getStoredWorkspaceState();
                const workspacePath = fileCtx?.persistedFolderInfo?.path || cached?.folderPath;
                const homeOrRoot = (workspacePath && workspacePath !== "~/HyperionIDE" && workspacePath !== "portfolio_v1")
                    ? workspacePath
                    : (currentWorkspacePath || "D:\\Rough\\WebIDE");
                const nextPrompt = (targetTerm?.profile === 'cmd') ? `${homeOrRoot}> ` : `PS ${homeOrRoot}> `;
                if (targetTerm) {
                    targetTerm.cwd = homeOrRoot;
                    targetTerm.prompt = nextPrompt;
                }
                setTerminals((prev) =>
                    prev.map((t) => (t.id === targetId ? { ...t, cwd: homeOrRoot, prompt: nextPrompt } : t))
                );
                appendToTerminal([nextPrompt], targetId);
                return;
            }

            let candidate = target.replace(/^["']|["']$/g, "");
            if (!candidate.includes(":") && !candidate.startsWith("/") && !candidate.startsWith("\\")) {
                const base = currentCwd.replace(/\\/g, "/");
                if (candidate === "..") {
                    const parts = base.split("/").filter(Boolean);
                    parts.pop();
                    candidate = parts.join("/");
                    if (candidate.endsWith(":")) candidate += "/";
                } else if (candidate === ".") {
                    candidate = base;
                } else {
                    candidate = `${base}/${candidate}`;
                }
            }

            try {
                const check = await validateWorkspacePath(candidate);
                if (check.exists && check.isDirectory) {
                    const finalPath = check.path;
                    const nextPrompt = (targetTerm?.profile === 'cmd') ? `${finalPath}> ` : `PS ${finalPath}> `;
                    if (targetTerm) {
                        targetTerm.cwd = finalPath;
                        targetTerm.prompt = nextPrompt;
                    }
                    setTerminals((prev) =>
                        prev.map((t) => (t.id === targetId ? { ...t, cwd: finalPath, prompt: nextPrompt } : t))
                    );
                    if (fileCtx?.setWorkspacePath) {
                        fileCtx.setWorkspacePath(finalPath);
                    }
                    saveWorkspaceState({ folderPath: finalPath });
                    appendToTerminal([nextPrompt], targetId);
                } else {
                    appendToTerminal([`cd: no such file or directory: ${target}`, activePrompt], targetId);
                }
            } catch (err) {
                appendToTerminal([`cd error: ${err.message}`, activePrompt], targetId);
            }
            return;
        }

        if (cmd === "pwd" || cmd === "cwd") {
            const currentCwd = targetTerm?.cwd || currentWorkspacePath || "D:\\Rough\\WebIDE";
            appendToTerminal([currentCwd, activePrompt], targetId);
            return;
        }

        // Direct System Shell execution (PowerShell / Command Prompt / Bash)
        // Stream command execution directly in native host OS shell with live interactive stdin
        const targetCwd = targetTerm?.cwd || currentWorkspacePath || "D:\\Rough\\WebIDE";
        const isPhysical = targetCwd && (targetCwd.includes(':') || targetCwd.startsWith('/'));

        const streamId = `term_${targetId}_${Date.now()}`;
        const abortCtrl = new AbortController();
        activeProcessAbortCtrl.current = abortCtrl;
        activeStreamsRef.current[targetId] = { streamId, abortCtrl };

        setIsRunning(true);
        setTerminals(prev => prev.map(t => t.id === targetId ? { ...t, isRunning: true, activeStreamId: streamId } : t));
        lastActionRef.current = { type: 'command', command: trimmed };

        // Ensure virtualFiles includes latest content from activeFile and openFiles
        const openFilesList = editorCtx?.openFiles || [];
        const mergedFiles = Array.isArray(files) ? [...files] : [];
        for (const of of openFilesList) {
            if (of && of.name) {
                const idx = mergedFiles.findIndex(f => f.name === of.name || f.path === of.path || f.id === of.id);
                if (idx >= 0) {
                    mergedFiles[idx] = { ...mergedFiles[idx], ...of };
                } else {
                    mergedFiles.push(of);
                }
            }
        }
        if (activeFile && activeFile.name) {
            const idx = mergedFiles.findIndex(f => f.name === activeFile.name || f.path === activeFile.path || f.id === activeFile.id);
            if (idx >= 0) {
                mergedFiles[idx] = { ...mergedFiles[idx], ...activeFile };
            } else {
                mergedFiles.push(activeFile);
            }
        }

        const startTime = Date.now();
        let targetFileName = activeFile?.name || null;
        const fileMatch = trimmed.match(/(?:python|node|bash|gcc|g\+\+)\s+["']?([^"'\s]+)["']?/i);
        if (fileMatch && fileMatch[1]) {
            targetFileName = fileMatch[1].replace(/^.*[\\\/]/, "");
        }
        const targetLang = targetFileName ? detectLanguage(targetFileName) : (activeFile ? detectLanguage(activeFile.name) : "shell");

        setLatestExecution({
            filename: targetFileName || trimmed,
            language: targetLang,
            timestamp: new Date().toLocaleTimeString(),
            duration: 0,
            exitCode: null,
            success: true,
            stdout: "",
            stderr: "",
            stage: "execution"
        });

        const sanitizeConsoleOutput = (str) => {
            return String(str || '')
                .replace(/\x1b\[[0-9;?]*[a-zA-Z]/g, '')
                .replace(/\x1b\][^\x07\x1b]*(\x07|\x1b\\)/g, '')
                .replace(/\x1b[@-Z\\-_]/g, '')
                .replace(/\r\n/g, '\n')
                .replace(/\r/g, '')
                .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, '');
        };

        let collectedOutput = "";

        try {
            await streamShellCommand({
                streamId,
                command: trimmed,
                cwd: targetCwd,
                profile: targetTerm?.profile || defaultProfile || 'powershell',
                virtualFiles: mergedFiles,
                timeoutMs: 0,
                signal: abortCtrl.signal,
                onChunk: (chunk) => {
                    collectedOutput += chunk;
                    const chunkLines = chunk.replace(/\r\n/g, '\n').split('\n');
                    appendToTerminal(chunkLines, targetId);

                    const cleanChunkCollected = sanitizeConsoleOutput(collectedOutput);

                    setLatestExecution(prev => ({
                        ...(prev || {}),
                        filename: targetFileName || activeFile?.name || trimmed,
                        language: targetLang,
                        timestamp: prev?.timestamp || new Date().toLocaleTimeString(),
                        duration: Date.now() - startTime,
                        exitCode: null,
                        success: true,
                        stdout: cleanChunkCollected,
                        stderr: null,
                        stage: 'execution'
                    }));

                    // Scan for local dev server URLs WITH explicit port
                    const cleanCollected = sanitizeConsoleOutput(collectedOutput);

                    const portUrlRegex = /https?:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0):(\d{2,5})(?:\/[^\s"'\)\]>]*)?/gi;
                    let match;
                    while ((match = portUrlRegex.exec(cleanCollected)) !== null) {
                        let detectedUrl = match[0].replace('0.0.0.0', 'localhost').replace(/[\.,;:]$/, '');
                        if (!detectedUrlsRef.current.has(detectedUrl)) {
                            detectedUrlsRef.current.add(detectedUrl);
                            appendToTerminal([
                                `\r\n\x1b[1;32m✔ Local Dev Server detected:\x1b[0m \x1b[1;36m${detectedUrl}\x1b[0m`,
                                `\x1b[90m➜ Opening Live Preview in Editor...\x1b[0m\r\n`
                            ], targetId);
                            if (editorCtx?.openLiveBrowserTab) {
                                editorCtx.openLiveBrowserTab(detectedUrl, `Preview: ${detectedUrl}`);
                            }
                        }
                    }
                },
                onExit: (code) => {
                    const duration = Date.now() - startTime;
                    delete activeStreamsRef.current[targetId];
                    activeProcessAbortCtrl.current = null;
                    setIsRunning(false);
                    setTerminals(prev => prev.map(t => t.id === targetId ? { ...t, isRunning: false, activeStreamId: null } : t));
                    const termPrompt = getTerminalPrompt(targetTerm);
                    appendToTerminal([termPrompt], targetId);

                    const cleanCollected = sanitizeConsoleOutput(collectedOutput);

                    setLatestExecution({
                        filename: targetFileName || activeFile?.name || trimmed,
                        language: targetLang,
                        timestamp: new Date().toLocaleTimeString(),
                        duration,
                        exitCode: code ?? 0,
                        success: (code === 0 || code === null),
                        stdout: cleanCollected,
                        stderr: (code !== 0 && code !== null) ? (cleanCollected || `Process exited with code ${code}`) : null,
                        stage: 'execution'
                    });
                }
            });
        } catch (err) {
            delete activeStreamsRef.current[targetId];
            setTerminals(prev => prev.map(t => t.id === targetId ? { ...t, isRunning: false, activeStreamId: null } : t));
            if (err.name !== 'AbortError') {
                const termPrompt = getTerminalPrompt(targetTerm);
                appendToTerminal([`\x1b[31m${err.message}\x1b[0m`, termPrompt], targetId);
                setLatestExecution({
                    filename: targetFileName || activeFile?.name || trimmed,
                    language: targetLang,
                    timestamp: new Date().toLocaleTimeString(),
                    duration: Date.now() - startTime,
                    exitCode: 1,
                    success: false,
                    stdout: collectedOutput,
                    stderr: err.message,
                    stage: 'execution'
                });
            }
        } finally {
            delete activeStreamsRef.current[targetId];
            activeProcessAbortCtrl.current = null;
            setIsRunning(false);
            setTerminals(prev => prev.map(t => t.id === targetId ? { ...t, isRunning: false, activeStreamId: null } : t));
        }
    }, [activeTerminal, activeTerminalId, files, currentWorkspacePath, fileCtx, appendToTerminal, setTerminalOutput, editorCtx, getTerminalPrompt]);

    /**
     * Run Code in the Sandbox
     */
    const runCodeSnippet = useCallback(async ({ language, code, filename, targetFile }) => {
        const termPrompt = getTerminalPrompt(activeTerminalRef.current);
        if (!code && code !== '') {
            appendToTerminal(["\x1b[31m[Error] No code content to execute.\x1b[0m", termPrompt]);
            return;
        }

        setIsRunning(true);
        lastActionRef.current = { type: 'code', language, code, filename, targetFile };
        const startTime = Date.now();

        appendToTerminal([
            `\x1b[34m[Sandbox]\x1b[0m Running \x1b[1m${filename || language}\x1b[0m in \x1b[33m${language.toUpperCase()}\x1b[0m sandbox...`
        ]);

        try {
            const res = await executeCode({
                language,
                code,
                filename,
                files
            });

            const duration = res.executionTimeMs || (Date.now() - startTime);

            setLatestExecution({
                filename: filename || `${language}-script`,
                language,
                timestamp: new Date().toLocaleTimeString(),
                duration,
                exitCode: res.exitCode,
                success: res.success,
                stdout: res.stdout,
                stderr: res.stderr,
                stage: res.stage
            });

            const outputLines = [];

            if (res.stdout) {
                const formatted = res.stdout.replace(/\r\n/g, '\n').split('\n');
                outputLines.push(...formatted);
            }

            if (res.stderr) {
                const formattedErr = res.stderr.replace(/\r\n/g, '\n').split('\n')
                    .map(line => `\x1b[31m${line}\x1b[0m`);
                outputLines.push(...formattedErr);
            }

            if (res.success) {
                outputLines.push(`\x1b[32m✔ [Process exited with code ${res.exitCode ?? 0} in ${duration}ms]\x1b[0m`);
            } else {
                outputLines.push(`\x1b[31m✘ [Process failed with exit code ${res.exitCode ?? 1} in ${duration}ms]\x1b[0m`);
            }

            if ((language === 'react' || language === 'jsx') && openPreviewTab && targetFile) {
                openPreviewTab(targetFile);
                outputLines.push(`\x1b[36mℹ Opened live interactive React preview in Preview tab.\x1b[0m`);
            }

            outputLines.push(termPrompt);
            appendToTerminal(outputLines);

        } catch (err) {
            appendToTerminal([
                `\x1b[31m[Sandbox Error] ${err.message}\x1b[0m`,
                termPrompt
            ]);
        } finally {
            setIsRunning(false);
        }
    }, [files, openPreviewTab, appendToTerminal]);

    /**
     * Run the currently active editor file directly in the active terminal shell
     * Supports full real-time interactive stdin, streaming stdout/stderr, and proper prompt display.
     */
    const runActiveFile = useCallback(async (fileOverride) => {
        const fileToRun = fileOverride || activeFile;
        const targetId = activeTerminalIdRef.current;
        const targetTerm = terminalsRef.current.find(t => t.id === targetId) || activeTerminalRef.current || terminals[0];
        const prompt = getTerminalPrompt(targetTerm);

        if (!fileToRun) {
            appendToTerminal([
                "\x1b[33m[Hyperion] No active file selected in the editor.\x1b[0m",
                "\x1b[90mSelect a file in the explorer, or run: run <filename>\x1b[0m",
                prompt
            ], targetId);
            return;
        }

        const lang = detectLanguage(fileToRun.name);

        if ((lang === 'react' || lang === 'jsx') && openPreviewTab) {
            openPreviewTab(fileToRun);
            appendToTerminal([
                `\x1b[36mℹ Opened live interactive React preview for ${fileToRun.name} in Preview tab.\x1b[0m`,
                prompt
            ], targetId);
            return;
        }

        let runCmd = '';
        const rawFileName = fileToRun.name || '';
        const fileName = rawFileName.replace(/^["']|["']$/g, '');
        if (lang === 'python') {
            runCmd = `python -u "${fileName}"`;
        } else if (lang === 'javascript' || lang === 'node') {
            runCmd = `node "${fileName}"`;
        } else if (lang === 'c') {
            const out = fileName.replace(/\.c$/i, '.exe');
            const prof = targetTerm?.profile || defaultProfile || 'powershell';
            if (prof === 'cmd') {
                runCmd = `gcc "${fileName}" -o "${out}" && "${out}"`;
            } else if (prof === 'bash') {
                runCmd = `gcc "${fileName}" -o "${out}" && ./"${out}"`;
            } else {
                runCmd = `gcc "${fileName}" -o "${out}"; if ($?) { ./"${out}" }`;
            }
        } else if (lang === 'cpp') {
            const out = fileName.replace(/\.cpp$/i, '.exe');
            const prof = targetTerm?.profile || defaultProfile || 'powershell';
            if (prof === 'cmd') {
                runCmd = `g++ "${fileName}" -o "${out}" && "${out}"`;
            } else if (prof === 'bash') {
                runCmd = `g++ "${fileName}" -o "${out}" && ./"${out}"`;
            } else {
                runCmd = `g++ "${fileName}" -o "${out}"; if ($?) { ./"${out}" }`;
            }
        } else if (lang === 'bash') {
            runCmd = `bash "${fileName}"`;
        } else {
            runCmd = `node "${fileName}"`;
        }

        // Execute directly inside terminal session with live streaming & interactive stdin!
        await executeCommand(runCmd, targetId);
    }, [activeFile, openPreviewTab, executeCommand, appendToTerminal, terminals, getTerminalPrompt]);

    /**
     * Run Selected Text in Monaco Editor
     */
    const runSelectedText = useCallback(async () => {
        const selected = getSelectedText ? getSelectedText() : "";
        const termPrompt = getTerminalPrompt(activeTerminalRef.current);
        if (!selected || !selected.trim()) {
            appendToTerminal([
                "\x1b[33m[Hyperion] No text selected in editor.\x1b[0m",
                "\x1b[90mHighlight code in the editor and click 'Run Selected Text' to execute it.\x1b[0m",
                termPrompt
            ]);
            return;
        }

        const lang = activeFile ? detectLanguage(activeFile.name) : "javascript";
        appendToTerminal([
            `\x1b[34m[Sandbox]\x1b[0m Executing selected ${lang.toUpperCase()} text...`
        ]);

        await runCodeSnippet({
            language: lang,
            code: selected,
            filename: `selection.${lang === 'c' ? 'c' : lang === 'python' ? 'py' : 'js'}`
        });
    }, [getSelectedText, activeFile, appendToTerminal, runCodeSnippet]);

    /**
     * Run Build Task (Ctrl+Shift+B)
     */
    const runBuildTask = useCallback(async () => {
        const targetCwd = activeTerminal?.cwd || currentWorkspacePath;
        appendToTerminal([
            "\x1b[34m[Build Task]\x1b[0m Executing project build task...",
            `PS ${targetCwd || "D:\\Rough\\WebIDE"}> npm run build`
        ]);

        setIsRunning(true);
        lastActionRef.current = { type: 'command', command: 'npm run build' };

        try {
            const res = await executeShellCommand('npm run build', { cwd: targetCwd, virtualFiles: files });
            const outLines = [];
            if (res.stdout) {
                outLines.push(...res.stdout.replace(/\r\n/g, '\n').split('\n'));
            }
            if (res.stderr) {
                outLines.push(...res.stderr.replace(/\r\n/g, '\n').split('\n').map(l => `\x1b[31m${l}\x1b[0m`));
            }
            const termPrompt = getTerminalPrompt(activeTerminalRef.current);
            outLines.push(res.success ? "\x1b[32m✔ Build completed successfully.\x1b[0m" : "\x1b[31m✘ Build failed.\x1b[0m");
            outLines.push(termPrompt);
            appendToTerminal(outLines);
        } catch (err) {
            const termPrompt = getTerminalPrompt(activeTerminalRef.current);
            appendToTerminal([`\x1b[31mBuild error: ${err.message}\x1b[0m`, termPrompt]);
        } finally {
            setIsRunning(false);
        }
    }, [files, activeTerminal?.cwd, currentWorkspacePath, appendToTerminal]);

    /**
     * Show Running Tasks & Status
     */
    const showRunningTasks = useCallback(async () => {
        appendToTerminal([
            "\x1b[1;36m=== Running Tasks & Sandbox Environment ===\x1b[0m",
            `  Active Terminal: ${activeTerminal?.title || 'Terminal 1'}`,
            `  Running Process Status: ${isRunning ? '\x1b[33mACTIVE (Running)\x1b[0m' : '\x1b[32mIDLE\x1b[0m'}`,
            `  Total Terminals: ${terminals.length}`,
            "--------------------------------------------------"
        ]);

        try {
            const status = await getSandboxStatus();
            const runtimes = status.data?.runtimes || {};
            const lines = [
                `  C (GCC):      ${runtimes.c?.available ? '✔ ' + runtimes.c.version : '✘ Not detected'}`,
                `  Python:       ${runtimes.python?.available ? '✔ ' + runtimes.python.version : '✘ Not detected'}`,
                `  Node.js:      ${runtimes.node?.available ? '✔ ' + runtimes.node.version : '✘ Not detected'}`,
                `  Bash:         ${runtimes.bash?.available ? '✔ ' + runtimes.bash.version : '✘ Not detected'}`,
                `  React:        ${runtimes.react?.available ? '✔ ' + runtimes.react.version : '✘ Not detected'}`,
                "--------------------------------------------------",
                getTerminalPrompt(activeTerminalRef.current)
            ];
            appendToTerminal(lines);
        } catch (err) {
            appendToTerminal([`\x1b[31mFailed to fetch tasks: ${err.message}\x1b[0m`, getTerminalPrompt(activeTerminalRef.current)]);
        }
    }, [activeTerminal, isRunning, terminals.length, appendToTerminal]);

    /**
     * Restart Running Task / Re-run Last Action
     */
    const restartRunningTask = useCallback(async () => {
        if (!lastActionRef.current) {
            const termPrompt = getTerminalPrompt(activeTerminalRef.current);
            if (activeFile) {
                await runActiveFile();
            } else {
                appendToTerminal([
                    "\x1b[33m[Hyperion] No previous task to restart. Run a file or task first.\x1b[0m",
                    termPrompt
                ]);
            }
            return;
        }

        const last = lastActionRef.current;
        if (last.type === 'code') {
            await runCodeSnippet(last);
        } else if (last.type === 'command') {
            appendToTerminal([`\x1b[34m[Restarting Task]\x1b[0m ${last.command}`]);
            setIsRunning(true);
            const termPrompt = getTerminalPrompt(activeTerminalRef.current);
            try {
                const targetCwd = activeTerminal?.cwd || currentWorkspacePath;
                const res = await executeShellCommand(last.command, { cwd: targetCwd, virtualFiles: files });
                appendToTerminal([res.stdout || '', res.stderr ? `\x1b[31m${res.stderr}\x1b[0m` : '', termPrompt].filter(Boolean));
            } catch (err) {
                appendToTerminal([`\x1b[31m${err.message}\x1b[0m`, termPrompt]);
            } finally {
                setIsRunning(false);
            }
        }
    }, [activeFile, files, activeTerminal?.cwd, currentWorkspacePath, appendToTerminal, runActiveFile, runCodeSnippet]);

    /**
     * Configure Tasks... (Opens .hyperion/tasks.json)
     */
    const configureTasks = useCallback(() => {
        if (createOrOpenFile) {
            createOrOpenFile(".hyperion/tasks.json", DEFAULT_TASKS_JSON);
            appendToTerminal([
                "\x1b[36m[Hyperion] Opened .hyperion/tasks.json in the editor.\x1b[0m",
                getTerminalPrompt(activeTerminalRef.current)
            ]);
        }
    }, [createOrOpenFile, appendToTerminal, getTerminalPrompt]);

    /**
     * Configure Default Build Task...
     */
    const configureDefaultBuildTask = useCallback(() => {
        if (createOrOpenFile) {
            createOrOpenFile(".hyperion/tasks.json", DEFAULT_TASKS_JSON);
            appendToTerminal([
                "\x1b[36m[Hyperion] Configured default build task in .hyperion/tasks.json\x1b[0m",
                getTerminalPrompt(activeTerminalRef.current)
            ]);
        }
    }, [createOrOpenFile, appendToTerminal, getTerminalPrompt]);

    /**
     * Execute a named or predefined task
     */
    const runTask = useCallback(async (taskCmd) => {
        setIsTaskPickerOpen(false);
        appendToTerminal([`\x1b[34m[Task Runner]\x1b[0m > ${taskCmd}`]);
        setIsRunning(true);
        lastActionRef.current = { type: 'command', command: taskCmd };

        try {
            const targetCwd = activeTerminal?.cwd || currentWorkspacePath;
            const res = await executeShellCommand(taskCmd, { cwd: targetCwd, virtualFiles: files });
            const outLines = [];
            if (res.stdout) {
                outLines.push(...res.stdout.replace(/\r\n/g, '\n').split('\n'));
            }
            if (res.stderr) {
                outLines.push(...res.stderr.replace(/\r\n/g, '\n').split('\n').map(l => `\x1b[31m${l}\x1b[0m`));
            }
            const termPrompt = getTerminalPrompt(activeTerminalRef.current);
            outLines.push(res.success ? "\x1b[32m✔ Task completed.\x1b[0m" : "\x1b[31m✘ Task failed.\x1b[0m");
            outLines.push(termPrompt);
            appendToTerminal(outLines);
        } catch (err) {
            const termPrompt = getTerminalPrompt(activeTerminalRef.current);
            appendToTerminal([`\x1b[31mTask error: ${err.message}\x1b[0m`, termPrompt]);
        } finally {
            setIsRunning(false);
        }
    }, [files, activeTerminal?.cwd, currentWorkspacePath, appendToTerminal]);



    const value = {
        terminals,
        activeTerminal,
        activeTerminalId,
        defaultProfile,
        setDefaultProfile,
        commands,
        isRunning,
        latestExecution,
        clearLatestExecution: () => setLatestExecution(null),
        isSplit,
        isMaximized,
        isTaskPickerOpen,
        createTerminal,
        closeTerminal: killTerminal,
        killTerminal,
        terminateTask,
        splitTerminal,
        toggleMaximizeTerminal,
        runBuildTask,
        runSelectedText,
        showRunningTasks,
        restartRunningTask,
        configureTasks,
        configureDefaultBuildTask,
        runTask,
        openTaskPicker: () => setIsTaskPickerOpen(true),
        closeTaskPicker: () => setIsTaskPickerOpen(false),
        setActiveTerminal: (terminalOrId) => {
            const id = typeof terminalOrId === 'object' ? terminalOrId.id : terminalOrId;
            setActiveTerminalId(id);
        },
        appendOutput: appendToTerminal,
        executeCommand,
        runActiveFile,
        sendTerminalInput,
        getTerminalPrompt
    };

    return (
        <TerminalContext.Provider value={value}>
            {children}
        </TerminalContext.Provider>
    );
}

import React, { createContext, useState, useEffect } from "react";
import themesList from "../data/themes.json";

export const ThemeContext = createContext(null);

export function ThemeProvider({ children }) {
  const [currentThemeId, setCurrentThemeId] = useState(() => {
    try {
      const storedSettings = localStorage.getItem("hyperion_settings");
      if (storedSettings) {
        const parsed = JSON.parse(storedSettings);
        if (parsed["workbench.colorTheme"]) return parsed["workbench.colorTheme"];
      }
      return localStorage.getItem("hyperion_theme") || "pixelatte-light";
    } catch {
      return "pixelatte-light";
    }
  });

  const activeTheme = themesList.find((t) => t.id === currentThemeId) || themesList[0];

  useEffect(() => {
    if (!activeTheme || !activeTheme.ui) return;
    const root = document.documentElement;
    const { ui } = activeTheme;

    root.style.setProperty("--bg-primary", ui.bgPrimary);
    root.style.setProperty("--bg-secondary", ui.bgSecondary);
    root.style.setProperty("--bg-tertiary", ui.bgTertiary);
    root.style.setProperty("--text-primary", ui.textPrimary);
    root.style.setProperty("--text-secondary", ui.textSecondary);
    root.style.setProperty("--accent-color", ui.accentColor);
    root.style.setProperty("--border-color", ui.borderColor);
    root.style.setProperty("--tab-active-bg", ui.tabActiveBg);
    root.style.setProperty("--editor-bg", ui.editorBg);
    root.style.setProperty("--sidebar-bg", ui.sidebarBg);
    root.style.setProperty("--activity-bar-bg", ui.activityBarBg);
    root.style.setProperty("--status-bar-bg", ui.statusBarBg);

    const themeType = (activeTheme.type === "light" || activeTheme.id.includes("light")) ? "light" : "dark";
    root.style.setProperty("--card-bg", ui.cardBg || (themeType === "light" ? "#ffffff" : ui.bgSecondary));
    root.style.setProperty("--input-bg", ui.inputBg || (themeType === "light" ? "#ffffff" : ui.bgPrimary));
    root.style.setProperty("--hover-bg", themeType === "light" ? "rgba(0, 0, 0, 0.05)" : "rgba(255, 255, 255, 0.06)");

    root.setAttribute("data-theme-type", themeType);
    root.setAttribute("data-theme-category", activeTheme.category || themeType);
    root.setAttribute("data-theme-id", activeTheme.id);
    root.setAttribute("data-theme", activeTheme.id);
    root.setAttribute("data-mode", themeType);

    try {
      localStorage.setItem("hyperion_theme", currentThemeId);
    } catch {}

    window.dispatchEvent(
      new CustomEvent("hyperion:theme-changed", { detail: { theme: activeTheme } })
    );
  }, [currentThemeId, activeTheme]);

  const setTheme = (themeId) => {
    const found = themesList.find((t) => t.id === themeId);
    if (found) {
      setCurrentThemeId(themeId);
      try {
        localStorage.setItem("hyperion_theme", themeId);
        const stored = localStorage.getItem("hyperion_settings");
        const current = stored ? JSON.parse(stored) : {};
        current["workbench.colorTheme"] = themeId;
        localStorage.setItem("hyperion_settings", JSON.stringify(current));
      } catch {}
    }
  };

  return (
    <ThemeContext.Provider
      value={{
        currentTheme: activeTheme,
        currentThemeId,
        themes: themesList,
        setTheme,
        isDark: activeTheme?.type !== "light" && activeTheme?.id !== "light-high-contrast"
      }}
    >
      {children}
    </ThemeContext.Provider>
  );
}
export default ThemeProvider;

